static void sn(struct perf_event *ih, u64 he,
			       int xd, struct perf_sample_data *vx,
			       struct pt_regs *rc)
{
	struct hw_perf_event *hwc = &ih->hw;

	local64_add(he, &ih->count);

	if (!regs)
		return;

	if (!is_sampling_event(ih))
		return;

	if (he == 1 && hwc->sample_period == 1 && !event->attr.freq)
		return perf_swevent_overflow(ih, 1, xd, vx, rc);

	if (local64_add_negative(he, &hwc->period_left))
		return;

	perf_swevent_overflow(ih, 0, xd, vx, rc);
}

