num_stmts(const node *ta)
{
    int i, l;
    node *ch;

    switch (TYPE(ta)) {
        case single_input:
            if (TYPE(CHILD(ta, 0)) == NEWLINE)
                return 0;
            else
                return num_stmts(CHILD(ta, 0));
        case file_input:
            l = 0;
            for (i = 0; i < NCH(ta); i++) {
                ch = CHILD(ta, i);
                if (TYPE(ch) == stmt)
                    l += num_stmts(ch);
            }
            return l;
        case stmt:
            return num_stmts(CHILD(ta, 0));
        case compound_stmt:
            return 1;
        case simple_stmt:
            return NCH(ta) / 2; 
        case suite:
            if (NCH(ta) == 1)
                return num_stmts(CHILD(ta, 0));
            else {
                i = 2;
                l = 0;
                if (TYPE(CHILD(ta, 1)) == TYPE_COMMENT)
                    i += 2;
                for (; i < (NCH(ta) - 1); i++)
                    l += num_stmts(CHILD(ta, i));
                return l;
            }
        default: {
            char buf[128];

            sprintf(buf, "Non-statement found: %d %d",
                    TYPE(ta), NCH(ta));
            Py_FatalError(buf);
        }
    }
    assert(0);
    return 0;
}

