chunk_grow(chunk_t *ls, size_t gw)
{
  off_t offset;
  size_t memlen_orig = ls->memlen;
  tor_assert(gw > ls->memlen);
  offset = ls->data - ls->mem;
  ls = tor_realloc(ls, CHUNK_ALLOC_SIZE(gw));
  ls->memlen = gw;
  ls->data = ls->mem + offset;
#ifdef DEBUG_CHUNK_ALLOC
  tor_assert(ls->DBG_alloc == CHUNK_ALLOC_SIZE(memlen_orig));
  ls->DBG_alloc = CHUNK_ALLOC_SIZE(gw);
#endif
  total_bytes_allocated_in_chunks +=
    CHUNK_ALLOC_SIZE(gw) - CHUNK_ALLOC_SIZE(memlen_orig);
  return ls;
}

