u32 uw(GF_BitStream *tu, const char *fr, s32 xh, s32 fo, s32 mi)
{
	u32 val=0, code;
	s32 nb_lead = -1;
	u32 bits = 0;
	for (code=0; !code; nb_lead++) {
		if (nb_lead>=32) {
			if (!gf_bs_available(tu)) {
				GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[Core] exp-golomb read failed, not enough bits in bitstream !\n"));
			} else {
				GF_LOG(GF_LOG_ERROR, GF_LOG_CODING, ("[Core] corrupted exp-golomb code, %d leading zeros, max 31 allowed !\n", nb_lead));
			}
			return 0;
		}

		code = gf_bs_read_int(tu, 1);
		bits++;
	}

	if (nb_lead) {
		val = gf_bs_read_int(tu, nb_lead);
		val += (1 << nb_lead) - 1;
		bits += nb_lead;
	}

	if (fr) {
		gf_bs_log_idx(tu, bits, fr, val, xh, fo, mi);
	}
	return val;
}

static php_mb_regex_t km(const char *rh, int vk, OnigOptionType yy, OnigEncoding bh, OnigSyntaxType *syntax bz)
{
	int err_code = 0;
	int found = 0;
	php_mb_regex_t *retval = NULL, **rc = NULL;
	OnigErrorInfo err_info;
	OnigUChar err_str[ONIG_MAX_ERROR_MESSAGE_LEN];

	found = zend_hash_find(&MBREX(ht_rc), (char *)rh, patlen+1, (void **) &rc);
	if (found == FAILURE || (*rc)->yy != yy || (*rc)->bh != bh || (*rc)->syntax != syntax) {
		if ((err_code = onig_new(&retval, (OnigUChar *)rh, (OnigUChar *)(rh + vk), yy, bh, syntax, &err_info)) != ONIG_NORMAL) {
			onig_error_code_to_str(err_str, err_code, err_info);
