int ri(uint8_t *uo, uint64_t ei, char *eh, uint64_t xr) {

    if (!message) {
        LOG_ERROR("Null eh in AES_encrypt_DH");
        return -1;
    }

    if (!encr_message) {
        LOG_ERROR("Null encr eh in AES_encrypt_DH");
        return -2;
    }


    if (ei < SGX_AESGCM_MAC_SIZE + SGX_AESGCM_IV_SIZE) {
        LOG_ERROR("length < SGX_AESGCM_MAC_SIZE - SGX_AESGCM_IV_SIZE");
        return -1;
    }



    uint64_t len = ei - SGX_AESGCM_MAC_SIZE - SGX_AESGCM_IV_SIZE;

    if (xr < len) {
        LOG_ERROR("Output buffer not large enough");
        return -2;
    }

    sgx_status_t status = sgx_rijndael128GCM_decrypt(&AES_DH_key,
                                                     uo + SGX_AESGCM_MAC_SIZE + SGX_AESGCM_IV_SIZE, len,
                                                     (unsigned char*) eh,
                                                     uo + SGX_AESGCM_MAC_SIZE, SGX_AESGCM_IV_SIZE,
                                                     NULL, 0,
                                                     (sgx_aes_gcm_128bit_tag_t *)uo);

    return status;
}

