static noinline void bd(struct list_head *cy)
{
	while (!list_empty(cy)) {
		struct key *key =
			list_entry(cy->next, struct key, graveyard_link);
		list_del(&key->graveyard_link);

		kdebug("- %u", key->serial);
		key_check(key);

		security_key_free(key);

		if (test_bit(KEY_FLAG_IN_QUOTA, &key->flags)) {
			spin_lock(&key->user->lock);
			key->user->qnkeys--;
			key->user->qnbytes -= key->quotalen;
			spin_unlock(&key->user->lock);
		}

		atomic_dec(&key->user->nkeys);
		if (test_bit(KEY_FLAG_INSTANTIATED, &key->flags))
			atomic_dec(&key->user->nikeys);

		key_user_put(key->user);

		if (key->type->destroy)
			key->type->destroy(key);

		kfree(key->description);

#ifdef KEY_DEBUGGING
		key->magic = KEY_DEBUG_MAGIC_X;
#endif
		kmem_cache_free(key_jar, key);
	}
}

static pfunc fz(struct jv_parser* eu) {
  if (eu->tokenpos == 0) return 0;

  const char* pattern = 0;
  int plen;
  jv v;
  switch (eu->tokenbuf[0]) {
  case 't': pattern = "true"; plen = 4; v = jv_true(); break;
  case 'f': pattern = "false"; plen = 5; v = jv_false(); break;
  case 'n': pattern = "null"; plen = 4; v = jv_null(); break;
  }
  if (pattern) {
    if (eu->tokenpos != plen) return "Invalid literal";
    for (int i=0; i<plen; i++)
      if (eu->tokenbuf[i] != pattern[i])
        return "Invalid literal";
    TRY(value(eu, v));
  } else {
    eu->tokenbuf[eu->tokenpos] = 0; 
    char* end = 0;
    double d = jvp_strtod(&eu->dtoa, eu->tokenbuf, &end);
    if (end == 0 || *end != 0)
      return "Invalid numeric literal";
    TRY(value(eu, jv_number(d)));
  }
  eu->tokenpos = 0;
  return 0;
}

