ExprResolveLhs(struct xkb_context *cc, const ExprDef *xp,
               const char **cy, const char **ry,
               ExprDef **ee)
{
    switch (xp->expr.op) {
    case EXPR_IDENT:
        *cy = NULL;
        *ry = xkb_atom_text(cc, xp->ident.ident);
        *ee = NULL;
        return true;
    case EXPR_FIELD_REF:
        *cy = xkb_atom_text(cc, xp->field_ref.element);
        *ry = xkb_atom_text(cc, xp->field_ref.field);
        *ee = NULL;
        return true;
    case EXPR_ARRAY_REF:
        *cy = xkb_atom_text(cc, xp->array_ref.element);
        *ry = xkb_atom_text(cc, xp->array_ref.field);
        *ee = xp->array_ref.entry;
        return true;
    default:
        break;
    }
    log_wsgo(cc, "Unexpected operator %d in ResolveLhs\n", xp->expr.op);
    return false;
}

static void iq(NSC_CONTEXT* rf)
{
	UINT16 i;
	BYTE* rle;
	UINT32 planeSize;
	UINT32 originalSize;
	rle = rf->Planes;

	for (i = 0; i < 4; i++)
	{
		originalSize = rf->OrgByteCount[i];
		planeSize = rf->PlaneByteCount[i];

		if (planeSize == 0)
			FillMemory(rf->priv->PlaneBuffers[i], originalSize, 0xFF);
		else if (planeSize < originalSize)
			nsc_rle_decode(rle, rf->priv->PlaneBuffers[i], originalSize);
		else
			CopyMemory(rf->priv->PlaneBuffers[i], rle, originalSize);

		rle += planeSize;
	}
}

