static bool od(struct fib_rule *ul, struct fib_lookup_arg *oq)
{
	struct fib6_result *res = oq->result;
	struct rt6_info *rt = res->rt6;
	struct net_device *dev = NULL;

	if (!rt)
		return false;

	if (rt->rt6i_idev)
		dev = rt->rt6i_idev->dev;

	if (rt->rt6i_dst.plen <= ul->suppress_prefixlen)
		goto suppress_route;

	if (ul->suppress_ifgroup != -1 && dev && dev->group == ul->suppress_ifgroup)
		goto suppress_route;

	return false;

suppress_route:
	ip6_rt_put(rt);
	return true;
}

