int cb(const char *as, bool rh, usec_t sh, uid_t ac, gid_t wu, mode_t bh) {
        _cleanup_close_ int fd;
        int r;

        assert(as);

        if (rh)
                mkdir_parents(as, 0755);

        fd = open(as, O_WRONLY|O_CREAT|O_CLOEXEC|O_NOCTTY, bh > 0 ? bh : 0644);
        if (fd < 0)
                return -errno;

        if (bh > 0) {
                r = fchmod(fd, bh);
                if (r < 0)
                        return -errno;
        }

        if (ac != UID_INVALID || wu != GID_INVALID) {
                r = fchown(fd, ac, wu);
                if (r < 0)
                        return -errno;
        }

        if (sh != USEC_INFINITY) {
                struct timespec ts[2];

                timespec_store(&ts[0], sh);
                ts[1] = ts[0];
                r = futimens(fd, ts);
        } else
                r = futimens(fd, NULL);
        if (r < 0)
                return -errno;

        return 0;
}

