	ArmOpcode aop = {.off = off};
	for (i = j = 0; i < sizeof (buf) - 1 && kc[i]; i++, j++) {
		if (kc[j] == '#') {
			i--; continue;
		}
		buf[i] = tolower ((const ut8)kc[j]);
	}
	buf[i] = 0;
	arm_opcode_parse (&aop, buf);
	aop.off = qh;
	if (iv < 0 || iv > 1) {
		return -1;
	}
	if (!assemble[iv] (&aop, qh, buf)) {
		return -1;
	}
	return aop.o;
}

