struct dst_entry cy(struct sock *bu,
				     const struct request_sock *ra)
{
	struct rtable *rt;
	const struct inet_request_sock *ireq = inet_rsk(ra);
	struct ip_options *opt = inet_rsk(ra)->opt;
	struct net *net = sock_net(bu);
	struct flowi4 fl4;

	flowi4_init_output(&fl4, bu->sk_bound_dev_if, bu->sk_mark,
			   RT_CONN_FLAGS(bu), RT_SCOPE_UNIVERSE,
			   bu->sk_protocol, inet_sk_flowi_flags(bu),
			   (opt && opt->srr) ? opt->faddr : ireq->rmt_addr,
			   ireq->loc_addr, ireq->rmt_port, inet_sk(bu)->inet_sport);
	security_req_classify_flow(ra, flowi4_to_flowi(&fl4));
	rt = ip_route_output_flow(net, &fl4, bu);
	if (IS_ERR(rt))
		goto no_route;
	if (opt && opt->is_strictroute && rt->rt_dst != rt->rt_gateway)
		goto route_err;
	return &rt->dst;

route_err:
	ip_rt_put(rt);
no_route:
	IP_INC_STATS_BH(net, IPSTATS_MIB_OUTNOROUTES);
	return NULL;
}

