ImagingPcdDecode(Imaging ph, ImagingCodecState go, UINT8* lj, int zh)
{
    int x;
    int chunk;
    UINT8* out;
    UINT8* ptr;

    ptr = lj;

    chunk = 3 * go->xsize;

    for (;;) {

	if (zh < chunk)
	    return ptr - lj;

	out = go->buffer;
	for (x = 0; x < go->xsize; x++) {
	    out[0] = ptr[x];
	    out[1] = ptr[(x+4*go->xsize)/2];
	    out[2] = ptr[(x+5*go->xsize)/2];
	    out += 4;
	}

	state->shuffle((UINT8*) ph->image[go->y],
		       go->buffer, go->xsize);

	if (++state->y >= go->ysize)
	    return -1; 

	out = go->buffer;
	for (x = 0; x < go->xsize; x++) {
	    out[0] = ptr[x+state->xsize];
	    out[1] = ptr[(x+4*go->xsize)/2];
	    out[2] = ptr[(x+5*go->xsize)/2];
	    out += 4;
	}

	state->shuffle((UINT8*) ph->image[go->y],
		       go->buffer, go->xsize);

	if (++state->y >= go->ysize)
	    return -1;

	ptr += chunk;
	bytes -= chunk;

    }
}

