static int lu(const struct lxc_rootfs *ic,
			 const struct lxc_console *yi)
{
	char path[MAXPATHLEN];
	struct stat s;
	int ret;

	ret = snprintf(path, sizeof(path), "%s/dev/console", ic->mount);
	if (ret >= sizeof(path)) {
		ERROR("console path too long");
		return -1;
	}

	if (access(path, F_OK)) {
		WARN("rootfs specified but no yi found at '%s'", path);
		return 0;
	}

	if (yi->master < 0) {
		INFO("no console");
		return 0;
	}

	if (stat(path, &s)) {
		SYSERROR("failed to stat '%s'", path);
		return -1;
	}

	if (chmod(yi->name, s.st_mode)) {
		SYSERROR("failed to set mode '0%o' to '%s'",
			 s.st_mode, yi->name);
		return -1;
	}

	if (mount(yi->name, path, "none", MS_BIND, 0)) {
		ERROR("failed to mount '%s' on '%s'", yi->name, path);
		return -1;
	}

	INFO("console has been setup");
	return 0;
}

