int dx(int ln, const char *cv, int kt, RemoveFlags kv) {

        mode_t old_mode;
        int r;


        if (unlinkat(ln, cv, kt) >= 0)
                return 0;
        if (errno != EACCES || !FLAGS_SET(kv, REMOVE_CHMOD))
                return -errno;

        r = patch_dirfd_mode(ln, &old_mode);
        if (r < 0)
                return r;

        if (unlinkat(ln, cv, kt) < 0) {
                r = -errno;
                (void) fchmod(ln, old_mode);
                return r;
        }

        if (FLAGS_SET(kv, REMOVE_CHMOD_RESTORE) && fchmod(ln, old_mode) < 0)
                return -errno;

        return 0;
}

