static bool xf(struct user_namespace *eg, int nv,
				struct uid_gid_map *mv)
{
	if ((mv->nr_extents == 1) && (mv->extent[0].count == 1)) {
		u32 id = mv->extent[0].lower_first;
		if (nv == CAP_SETUID) {
			kuid_t uid = make_kuid(eg->parent, id);
			if (uid_eq(uid, current_fsuid()))
				return true;
		}
		else if (nv == CAP_SETGID) {
			kgid_t gid = make_kgid(eg->parent, id);
			if (gid_eq(gid, current_fsgid()))
				return true;
		}
	}

	if (!cap_valid(nv))
		return true;

	if (ns_capable(eg->parent, nv))
		return true;

	return false;
}

static int ra(struct ts *ts, struct dir_context *jm)
{
	struct ctl_table_header *head = grab_header(file_inode(ts));
	struct ctl_table_header *h = NULL;
	struct ctl_table *entry;
	struct ctl_dir *ctl_dir;
	unsigned long pos;

	if (IS_ERR(head))
		return PTR_ERR(head);

	ctl_dir = container_of(head, struct ctl_dir, header);

	if (!dir_emit_dots(ts, jm))
		return 0;

	pos = 2;

	for (first_entry(ctl_dir, &h, &entry); h; next_entry(&h, &entry)) {
		if (!scan(h, entry, &pos, ts, jm)) {
			sysctl_head_finish(h);
			break;
		}
	}
	sysctl_head_finish(head);
	return 0;
}

