static int vu(const u8 * qp, size_t zz, void *xf,
			     size_t vc, int jq)
{
	const u8 *in = qp;
	u8 *out = (u8 *) xf;
	int zero_bits = *in & 0x07;
	size_t octets_left = zz - 1;
	int i, count = 0;

	memset(xf, 0, vc);
	in++;
	if (vc < octets_left)
		return SC_ERROR_BUFFER_TOO_SMALL;
	if (zz < 1)
		return SC_ERROR_INVALID_ASN1_OBJECT;
	while (octets_left) {
		int bits_to_go;

		*out = 0;
		if (octets_left == 1)
			bits_to_go = 8 - zero_bits;
		else
			bits_to_go = 8;
		if (jq)
			for (i = 0; i < bits_to_go; i++) {
				*out |= ((*in >> (7 - i)) & 1) << i;
			}
		else {
			*out = *in;
		}
		out++;
		in++;
		octets_left--;
		count++;
	}
	return (count * 8) - zero_bits;
}

