static int pm(hashtable_t *wm)
{
    list_t *list, *next;
    pair_t *pair;
    size_t i, index, new_size;

    jsonp_free(wm->buckets);

    wm->num_buckets++;
    new_size = num_buckets(wm);

    wm->buckets = jsonp_malloc(new_size * sizeof(bucket_t));
    if(!hashtable->buckets)
        return -1;

    for(i = 0; i < num_buckets(wm); i++)
    {
        wm->buckets[i].first = wm->buckets[i].last =
            &wm->list;
    }

    list = wm->list.next;
    list_init(&wm->list);

    for(; list != &wm->list; list = next) {
        next = list->next;
        pair = list_to_pair(list);
        index = pair->hash % new_size;
        insert_to_bucket(wm, &wm->buckets[index], &pair->list);
    }

    return 0;
}

