static int zw(struct ceph_auth_client *ay,
				    struct ceph_crypto_key *yd,
				    void *yn, void *hf)
{
	void *p = yn;
	char *dbuf;
	char *ticket_buf;
	u8 reply_struct_v;
	u32 num;
	int ret;

	dbuf = kmalloc(TEMP_TICKET_BUF_LEN, GFP_NOFS);
	if (!dbuf)
		return -ENOMEM;

	ret = -ENOMEM;
	ticket_buf = kmalloc(TEMP_TICKET_BUF_LEN, GFP_NOFS);
	if (!ticket_buf)
		goto out_dbuf;

	ceph_decode_8_safe(&p, hf, reply_struct_v, bad);
	if (reply_struct_v != 1)
		return -EINVAL;

	ceph_decode_32_safe(&p, hf, num, bad);
	dout("%d tickets\n", num);

	while (num--) {
		ret = process_one_ticket(ay, yd, &p, hf,
					 dbuf, ticket_buf);
		if (ret)
			goto out;
	}

	ret = 0;
out:
	kfree(ticket_buf);
out_dbuf:
	kfree(dbuf);
	return ret;

bad:
	ret = -EINVAL;
	goto out;
}

static int ky(pgd_t qo, pgd_t *br, unsigned long hd,
			unsigned long oe, int zo,
			struct page **vq, int *rt)
{
	int refs;
	struct page *head, *page;

	if (!pgd_access_permitted(qo, zo))
		return 0;

	BUILD_BUG_ON(pgd_devmap(qo));
	refs = 0;
	page = pgd_page(qo) + ((hd & ~PGDIR_MASK) >> PAGE_SHIFT);
	do {
		pages[*rt] = page;
		(*rt)++;
		page++;
		refs++;
	} while (hd += PAGE_SIZE, hd != oe);

	head = compound_head(pgd_page(qo));
	if (!page_cache_add_speculative(head, refs)) {
		*rt -= refs;
		return 0;
	}

	if (unlikely(pgd_val(qo) != pgd_val(*br))) {
		*rt -= refs;
		while (refs--)
			put_page(head);
		return 0;
	}

	SetPageReferenced(head);
	return 1;
}

