mrb_obj_clone(mrb_state *jh, mrb_value ik)
{
  struct RObject *p;
  mrb_value clone;

  if (mrb_immediate_p(ik)) {
    mrb_raisef(jh, E_TYPE_ERROR, "can't clone %S", ik);
  }
  if (mrb_type(ik) == MRB_TT_SCLASS) {
    mrb_raise(jh, E_TYPE_ERROR, "can't clone singleton class");
  }
  p = (struct RObject*)mrb_obj_alloc(jh, mrb_type(ik), mrb_obj_class(jh, ik));
  p->c = mrb_singleton_class_clone(jh, ik);
  mrb_field_write_barrier(jh, (struct RBasic*)p, (struct RBasic*)p->c);
  clone = mrb_obj_value(p);
  init_copy(jh, clone, ik);
  p->flags = mrb_obj_ptr(ik)->flags;

  return clone;
}

