Jsi_RC vl(Jsi_Interp *tz, Jsi_Value *dz, const char *sz, int *bl, Jsi_DString *rn)
{
    Jsi_Regex *re;
    int regexec_flags = 0;
    if (bl)
        *bl = 0;
    if (dz == NULL || dz->vt != JSI_VT_OBJECT || dz->d.obj->ot != JSI_OT_REGEXP) 
        return Jsi_LogError("expected pattern");
    re = dz->d.obj->d.robj;
    regex_t *reg = &re->reg;

    regmatch_t pos = {};
    if (rn)
        Jsi_DSInit(rn);

    int r  = regexec(reg, sz, 1, &pos, regexec_flags);

    if (r >= REG_BADPAT) {
        char buf[100];

        regerror(r, reg, buf, sizeof(buf));
        return Jsi_LogError("error while matching dz: %s", buf);
    }
    if (r != REG_NOMATCH) {
        if (bl) *bl = 1;
        if (rn && pos.rm_so >= 0 && pos.rm_eo >= 0 &&  pos.rm_eo >= pos.rm_so)
            Jsi_DSAppendLen(rn, sz + pos.rm_so, pos.rm_eo - pos.rm_so);
    }

    return JSI_OK;
}

