error_t ip(NetInterface *fb)
{
   uint_t i;
   bool_t acceptMulticast;

   TRACE_DEBUG("Updating MAC filter...\r\n");

   ENET->MAC_ADDR_LOW = fb->macAddr.w[0] | (fb->macAddr.w[1] << 16);
   ENET->MAC_ADDR_HIGH = fb->macAddr.w[2];

   acceptMulticast = FALSE;

   for(i = 0; i < MAC_ADDR_FILTER_SIZE; i++)
   {
      if(fb->macAddrFilter[i].refCount > 0)
      {
         acceptMulticast = TRUE;
         break;
      }
   }

   if(acceptMulticast)
   {
      ENET->MAC_FRAME_FILTER |= ENET_MAC_FRAME_FILTER_PM_MASK;
   }
   else
   {
      ENET->MAC_FRAME_FILTER &= ~ENET_MAC_FRAME_FILTER_PM_MASK;
   }

   return NO_ERROR;
}

