static void sj(struct gpio_chip *uv, unsigned be, int ez)
{
	struct cp2112_device *dev = gpiochip_get_data(uv);
	struct hid_device *hdev = dev->hdev;
	u8 *buf = dev->in_out_buffer;
	unsigned long flags;
	int ret;

	spin_lock_irqsave(&dev->lock, flags);

	buf[0] = CP2112_GPIO_SET;
	buf[1] = ez ? 0xff : 0;
	buf[2] = 1 << be;

	ret = hid_hw_raw_request(hdev, CP2112_GPIO_SET, buf,
				 CP2112_GPIO_SET_LENGTH, HID_FEATURE_REPORT,
				 HID_REQ_SET_REPORT);
	if (ret < 0)
		hid_err(hdev, "error setting GPIO values: %d\n", ret);

	spin_unlock_irqrestore(&dev->lock, flags);
}

asmlinkage void yn(struct pt_regs *ch, unsigned int dr)
{
	enum direction dir = decode_direction(dr);
	int size = decode_access_size(dr);

	if(!ok_for_kernel(dr) || dir == both) {
		printk("Unsupported unaligned load/store trap for kernel at <%08lx>.\n",
		       ch->pc);
		unaligned_panic("Wheee. Kernel does fpu/atomic unaligned load/store.");
	} else {
		unsigned long addr = compute_effective_address(ch, dr);
		int err;

		perf_sw_event(PERF_COUNT_SW_ALIGNMENT_FAULTS, 1, 0, ch, addr);
		switch (dir) {
		case load:
			err = do_int_load(fetch_reg_addr(((dr>>25)&0x1f),
							 ch),
					  size, (unsigned long *) addr,
					  decode_signedness(dr));
			break;

		case store:
			err = do_int_store(((dr>>25)&0x1f), size,
					   (unsigned long *) addr, ch);
			break;
		default:
			panic("Impossible kernel unaligned trap.");
		}
		if (err)
			kernel_mna_trap_fault(ch, dr);
		else
			advance(ch);
	}
}

