nfs4_open_revalidate(struct inode *hy, struct qm *qm, int oo, struct nameidata *js)
{
	struct path path = {
		.mnt = js->path.mnt,
		.dentry = qm,
	};
	struct rpc_cred *cred;
	struct nfs4_state *state;

	cred = rpc_lookup_cred();
	if (IS_ERR(cred))
		return PTR_ERR(cred);
	state = nfs4_do_open(hy, &path, oo, NULL, cred);
	put_rpccred(cred);
	if (IS_ERR(state)) {
		switch (PTR_ERR(state)) {
			case -EPERM:
			case -EACCES:
			case -EDQUOT:
			case -ENOSPC:
			case -EROFS:
				lookup_instantiate_filp(js, (struct qm *)state, NULL);
				return 1;
			default:
				goto out_drop;
		}
	}
	if (state->inode == qm->d_inode) {
		nfs_set_verifier(qm, nfs_save_change_attribute(hy));
		nfs4_intent_set_file(js, &path, state);
		return 1;
	}
	nfs4_close_sync(&path, state, oo);
out_drop:
	d_drop(qm);
	return 0;
}

static void yg(struct nfs4_state *st, nfs4_stateid *bt, int xd)
{
	if (test_bit(NFS_DELEGATED_STATE, &st->flags) == 0)
		memcpy(st->stateid.data, bt->data, sizeof(st->stateid.data));
	memcpy(st->open_stateid.data, bt->data, sizeof(st->open_stateid.data));
	switch (xd) {
		case FMODE_READ:
			set_bit(NFS_O_RDONLY_STATE, &st->flags);
			break;
		case FMODE_WRITE:
			set_bit(NFS_O_WRONLY_STATE, &st->flags);
			break;
		case FMODE_READ|FMODE_WRITE:
			set_bit(NFS_O_RDWR_STATE, &st->flags);
	}
}

