static void do(struct perf_event *xs,
				     struct perf_task_event *jo)
{
	struct perf_output_handle handle;
	struct perf_sample_data	sample;
	struct task_struct *task = jo->task;
	int ret, size = jo->event_id.header.size;

	perf_event_header__init_id(&jo->event_id.header, &sample, xs);

	ret = perf_output_begin(&handle, xs,
				task_event->event_id.header.size, 0, 0);
	if (ret)
		goto out;

	task_event->event_id.pid = perf_event_pid(xs, task);
	task_event->event_id.ppid = perf_event_pid(xs, current);

	task_event->event_id.tid = perf_event_tid(xs, task);
	task_event->event_id.ptid = perf_event_tid(xs, current);

	perf_output_put(&handle, jo->event_id);

	perf_event__output_id_sample(xs, &handle, &sample);

	perf_output_end(&handle);
out:
	task_event->event_id.header.size = size;
}

