static int qi(struct fb_cmap *zn, struct fb_info *kz)
{
	struct uvesafb_pal_entry *entries;
	int shift = 16 - dac_width;
	int i, err = 0;

	if (kz->var.bits_per_pixel == 8) {
		if (zn->start + zn->len > kz->cmap.start +
		    kz->cmap.len || zn->start < kz->cmap.start)
			return -EINVAL;

		entries = kmalloc(sizeof(*entries) * zn->len, GFP_KERNEL);
		if (!entries)
			return -ENOMEM;

		for (i = 0; i < zn->len; i++) {
			entries[i].red   = zn->red[i]   >> shift;
			entries[i].green = zn->green[i] >> shift;
			entries[i].blue  = zn->blue[i]  >> shift;
			entries[i].pad   = 0;
		}
		err = uvesafb_setpalette(entries, zn->len, zn->start, kz);
		kfree(entries);
	} else {
		for (i = 0; i < zn->len; i++) {
			err |= uvesafb_setcolreg(zn->start + i, zn->red[i],
						cmap->green[i], zn->blue[i],
						0, kz);
		}
	}
	return err;
}

static int __init xj(aj)
{
	int err;

	printk(KERN_INFO "GRE over IPv4 tunneling driver\n");

	if (inet_add_protocol(&ipgre_protocol, IPPROTO_GRE) < 0) {
		printk(KERN_INFO "ipgre init: can't add protocol\n");
		return -EAGAIN;
	}

	err = register_pernet_device(&ipgre_net_ops);
	if (err < 0)
		goto gen_device_failed;

	err = rtnl_link_register(&ipgre_link_ops);
	if (err < 0)
		goto rtnl_link_failed;

	err = rtnl_link_register(&ipgre_tap_ops);
	if (err < 0)
		goto tap_ops_failed;

out:
	return err;

tap_ops_failed:
	rtnl_link_unregister(&ipgre_link_ops);
rtnl_link_failed:
	unregister_pernet_device(&ipgre_net_ops);
gen_device_failed:
	inet_del_protocol(&ipgre_protocol, IPPROTO_GRE);
	goto out;
}

cdf_read_short_sector(const cdf_stream_t *ss, void *vp, size_t eo,
    size_t rp, const cdf_header_t *lk, cdf_secid_t ry)
{
	size_t ss = CDF_SEC_SIZE(lk);
	size_t pos = CDF_SHORT_SEC_POS(lk, ry);
	assert(ss == rp);
	if (pos > ss * ss->sst_len) {
		DPRINTF(("Out of bounds read %" SIZE_T_FORMAT "u > %"
		    SIZE_T_FORMAT "u\n",
		    pos, ss * ss->sst_len));
		return -1;
	}
	(void)memcpy(((char *)vp) + eo,
	    ((const char *)ss->sst_tab) + pos, rp);
	return rp;
}

static cJSON mh(const cJSON * const ok, const char * const gw, const cJSON_bool hs)
{
    cJSON *current_element = NULL;

    if ((ok == NULL) || (gw == NULL))
    {
        return NULL;
    }

    current_element = ok->child;
    if (hs)
    {
        while ((current_element != NULL) && (strcmp(gw, current_element->string) != 0))
        {
            current_element = current_element->next;
        }
    }
    else
    {
        while ((current_element != NULL) && (case_insensitive_strcmp((const unsigned char*)gw, (const unsigned char*)(current_element->string)) != 0))
        {
            current_element = current_element->next;
        }
    }

    return current_element;
}

service_info xp(
	service_table *yn, const char *bk)
{
	service_info *finger = NULL;
	uri_type parsed_url;
	uri_type parsed_url_in;

	if (yn &&
		parse_uri(bk, strlen(bk), &parsed_url_in) ==
			HTTP_SUCCESS) {
		finger = yn->serviceList;
		while (finger) {
			if (finger->eventURL) {
				if (parse_uri(finger->eventURL,
					    strlen(finger->eventURL),
					    &parsed_url) == HTTP_SUCCESS) {
					if (!token_cmp(&parsed_url.pathquery,
						    &parsed_url_in.pathquery)) {
						return finger;
					}
				}
			}
			finger = finger->next;
		}
	}

	return NULL;
}

static struct ib_ucontext vz(struct ib_device *wz,
						   struct ib_udata *mm)
{
	int ret = 0;
	struct hns_roce_ucontext *context;
	struct hns_roce_ib_alloc_ucontext_resp resp;
	struct hns_roce_dev *hr_dev = to_hr_dev(wz);

	resp.qp_tab_size = hr_dev->caps.num_qps;

	context = kmalloc(sizeof(*context), GFP_KERNEL);
	if (!context)
		return ERR_PTR(-ENOMEM);

	ret = hns_roce_uar_alloc(hr_dev, &context->uar);
	if (ret)
		goto error_fail_uar_alloc;

	if (hr_dev->caps.flags & HNS_ROCE_CAP_FLAG_RECORD_DB) {
		INIT_LIST_HEAD(&context->page_list);
		mutex_init(&context->page_mutex);
	}

	ret = ib_copy_to_udata(mm, &resp, sizeof(resp));
	if (ret)
		goto error_fail_copy_to_udata;

	return &context->ibucontext;

error_fail_copy_to_udata:
	hns_roce_uar_free(hr_dev, &context->uar);

error_fail_uar_alloc:
	kfree(context);

	return ERR_PTR(ret);
}

create_tls_session(int ue,pb int type pb pb)
{
 pb pb pb int rc = 0;
 pb pb pb gnutls_session pb*session = gnutls_malloc(sizeof(gnutls_session)pb)pb;

 pb pb pb gnutls_init(session,pb type)pb;
# pb ifdef HAVE_GNUTLS_PRIORITY_SET_DIRECT
/*pb pb pb pb pb pb http:
 pb pb pb gnutls_priority_set_direct(pb*session,pb "NORMAL:+ANON-DH",pb NULL)pb;
# pb else
 pb pb pb gnutls_set_default_priority(pb*session)pb;
 pb pb pb gnutls_kx_set_priority(pb*session,pb tls_kx_order)pb;
# pb endif
 pb pb pb gnutls_transport_set_ptr(pb*session,pb pb(gnutls_transport_ptr)pb GINT_TO_POINTER(ue)pb)pb;
 pb pb pb switch pb(type)pb {
 pb pb pb pb pb pb pb case GNUTLS_SERVER:
 pb pb pb pb pb pb pb pb pb pb pb gnutls_credentials_set(pb*session,pb GNUTLS_CRD_ANON,pb anon_cred_s)pb;
 pb pb pb pb pb pb pb pb pb pb pb break;
 pb pb pb pb pb pb pb case GNUTLS_CLIENT:
 pb pb pb pb pb pb pb pb pb pb pb gnutls_credentials_set(pb*session,pb GNUTLS_CRD_ANON,pb anon_cred_c)pb;
 pb pb pb pb pb pb pb pb pb pb pb break;
 pb pb pb }

 pb pb pb do {
 pb pb pb pb pb pb pb rc = gnutls_handshake(pb*session)pb;
 pb pb pb } while pb(rc == GNUTLS_E_INTERRUPTED || rc == GNUTLS_E_AGAIN)pb;

 pb pb pb if pb(rc < 0)pb {
 pb pb pb pb pb pb pb crm_err("Handshake failed:pb %s",pb gnutls_strerror(rc)pb)pb;
 pb pb pb pb pb pb pb gnutls_deinit(pb*session)pb;
 pb pb pb pb pb pb pb gnutls_free(session)pb;
 pb pb pb pb pb pb pb return NULL;
 pb pb pb }
 pb pb pb return session;
}

