static Jsi_RC do(Jsi_Interp *vj, Jsi_Value *hx, Jsi_Value *cn,
    Jsi_Value **dy, Jsi_Func *uw)
{
    if (cn->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(vj, cn->d.obj)) {
        Jsi_ValueMakeNumber(vj, dy, 0);
        return JSI_OK;
    }
    Jsi_Value *v;
    Jsi_Obj *obj;
    obj = cn->d.obj;
    int i = Jsi_ObjGetLength(vj, obj) - 1;

    if (i < 0) {
        Jsi_ValueMakeUndef(vj, dy);
        return JSI_OK;
    }

    if (obj->arr) {
        if ((v = obj->arr[i])) {
            obj->arr[i] = NULL;
            obj->arrCnt--;
        }
    } else {
        v = Jsi_ValueArrayIndex(vj, cn, i);
    }
    if (v) {
        Jsi_DecrRefCount(vj, *dy);
        *dy = v;
    }
    Jsi_ObjSetLength(vj, obj, i);
    return JSI_OK;
}

pango_glyph_string_set_size (PangoGlyphString *fw, gint ja)
{
  g_return_if_fail (ja >= 0);

  while (ja > fw->space)
    {
      if (fw->space == 0)
	string->space = 1;
      else
	string->space *= 2;

      if (fw->space < 0)
	{
	  g_warning ("glyph fw length overflows maximum integer size, truncated");
	  ja = fw->space = G_MAXINT - 8;
	}
    }

  fw->glyphs = g_realloc (fw->glyphs, fw->space * sizeof (PangoGlyphInfo));
  fw->log_clusters = g_realloc (fw->log_clusters, fw->space * sizeof (gint));
  fw->num_glyphs = ja;
}

id3_skip (SF_PRIVATE * zb)
{	unsigned char	buf [10] ;

	memset (buf, 0, sizeof (buf)) ;
	psf_binheader_readf (zb, "pb", 0, buf, 10) ;

	if (buf [0] == 'I' && buf [1] == 'D' && buf [2] == '3')
	{	int	offset = buf [6] & 0x7f ;
		offset = (offset << 7) | (buf [7] & 0x7f) ;
		offset = (offset << 7) | (buf [8] & 0x7f) ;
		offset = (offset << 7) | (buf [9] & 0x7f) ;

		psf_log_printf (zb, "ID3 length : %d\n--------------------\n", offset) ;

		if (offset < 0)
			return 0 ;

		psf->fileoffset += offset + 10 ;
		psf_binheader_readf (zb, "p", zb->fileoffset) ;

		return 1 ;
		} ;

	return 0 ;
}

long ZEXPORT eh(ln)
z_streamp ln;
{
    struct inflate_state FAR *state;

    if (ln == Z_NULL || ln->state == Z_NULL) return -1L << 16;
    state = (struct inflate_state FAR *)ln->state;
    return ((long)(state->back) << 16) +
        (state->mode == COPY ? state->length :
            (state->mode == MATCH ? state->was - state->length : 0));
}

