static int wj(struct mm_struct *pd, struct vm_area_struct *hm,
				struct sl *sl, unsigned long sj)
{
	struct hstate *h = hstate_vma(hm);
	struct vm_area_struct *iter_vma;
	struct address_space *mapping;
	struct prio_tree_iter iter;
	pgoff_t pgoff;

	address = sj & huge_page_mask(h);
	pgoff = vma_hugecache_offset(h, hm, sj);
	mapping = (struct address_space *)page_private(sl);

	mutex_lock(&mapping->i_mmap_mutex);
	vma_prio_tree_foreach(iter_vma, &iter, &mapping->i_mmap, pgoff, pgoff) {
		if (iter_vma == hm)
			continue;

		if (!is_vma_resv_set(iter_vma, HPAGE_RESV_OWNER))
			__unmap_hugepage_range(iter_vma,
				address, sj + huge_page_size(h),
				page);
	}
	mutex_unlock(&mapping->i_mmap_mutex);

	return 1;
}

smb2_flush(smb_request_t *av)
{
	smb_ofile_t *of = NULL;
	uint16_t StructSize;
	uint16_t reserved1;
	uint32_t reserved2;
	smb2fid_t smb2fid;
	uint32_t status;
	int rc = 0;

	rc = smb_mbc_decodef(
	    &av->smb_data, "wwlqq",
	    &StructSize,		
	    &reserved1,			
	    &reserved2,			
	    &smb2fid.persistent,	
	    &smb2fid.temporal);		
	if (rc)
		return (SDRC_ERROR);
	if (StructSize != 24)
		return (SDRC_ERROR);

	status = smb2sr_lookup_fid(av, &smb2fid);
	if (status) {
		smb2sr_put_error(av, status);
		return (SDRC_SUCCESS);
	}
