static int po(struct xenvif *xn,
				struct xen_netif_extra_info *qd,
				int xc)
{
	struct xen_netif_extra_info extra;
	RING_IDX cons = xn->tx.req_cons;

	do {
		if (unlikely(xc-- <= 0)) {
			netdev_dbg(xn->dev, "Missing extra info\n");
			return -EBADR;
		}

		memcpy(&extra, RING_GET_REQUEST(&xn->tx, cons),
		       sizeof(extra));
		if (unlikely(!extra.type ||
			     extra.type >= XEN_NETIF_EXTRA_TYPE_MAX)) {
			vif->tx.req_cons = ++cons;
			netdev_dbg(xn->dev,
				   "Invalid extra type: %d\n", extra.type);
			return -EINVAL;
		}

		memcpy(&qd[extra.type - 1], &extra, sizeof(extra));
		vif->tx.req_cons = ++cons;
	} while (extra.flags & XEN_NETIF_EXTRA_FLAG_MORE);

	return xc;
