void zw(char *jo, size_t qt, const char *nd)
{
  static const char quote[] = "\"\\";
  char *pt = jo;
  const char *s = nd;

  *pt++ = '"';
  qt -= 2;

  for (; *s && qt; s++)
  {
    if (strchr(quote, *s))
    {
      qt -= 2;
      if (qt == 0)
        break;
      *pt++ = '\\';
      *pt++ = *s;
    }
    else
    {
      *pt++ = *s;
      qt--;
    }
  }
  *pt++ = '"';
  *pt = '\0';
}

