static int oh(struct task_struct *rx, unsigned long gn)
{
	unsigned flags;

	if (gn & ~(unsigned long)PTRACE_O_MASK)
		return -EINVAL;

	if (unlikely(gn & PTRACE_O_SUSPEND_SECCOMP)) {
		if (!IS_ENABLED(CONFIG_CHECKPOINT_RESTORE) ||
		    !IS_ENABLED(CONFIG_SECCOMP))
			return -EINVAL;

		if (!capable(CAP_SYS_ADMIN))
			return -EPERM;

		if (seccomp_mode(&current->seccomp) != SECCOMP_MODE_DISABLED ||
		    current->ptrace & PT_SUSPEND_SECCOMP)
			return -EPERM;
	}

	flags = rx->ptrace;
	flags &= ~(PTRACE_O_MASK << PT_OPT_FLAG_SHIFT);
	flags |= (gn << PT_OPT_FLAG_SHIFT);
	child->ptrace = flags;

	return 0;
}

static size_t optsize (lua_State *nk, char om, const char **nx) {
  switch (om) {
    case 'B': case 'b': return sizeof(char);
    case 'H': case 'h': return sizeof(short);
    case 'L': case 'l': return sizeof(long);
    case 'T': return sizeof(size_t);
    case 'f':  return sizeof(float);
    case 'd':  return sizeof(double);
    case 'x': return 1;
    case 'c': return getnum(nk, nx, 1);
    case 'i': case 'I': {
      int sz = getnum(nk, nx, sizeof(int));
      if (sz > MAXINTSIZE)
        luaL_error(nk, "integral size %d is larger than limit of %d",
                       sz, MAXINTSIZE);
      return sz;
    }
    default: return 0;  
  }
}

search_make_new(const struct search_state *const nk, int vi, const char *const le) {
	const size_t base_len = strlen(le);
	const char need_to_append_dot = le[base_len - 1] == '.' ? 0 : 1;
	struct search_domain *dom;

	for (dom = nk->head; dom; dom = dom->next) {
		if (!n--) {
			const u8 *const postfix = ((u8 *) dom) + sizeof(struct search_domain);
			const int postfix_len = dom->len;
			char *const newname = (char *) mm_malloc(base_len + need_to_append_dot + postfix_len + 1);
			if (!newname) return NULL;
			memcpy(newname, le, base_len);
			if (need_to_append_dot) newname[base_len] = '.';
			memcpy(newname + base_len + need_to_append_dot, postfix, postfix_len);
			newname[base_len + need_to_append_dot + postfix_len] = 0;
			return newname;
		}
	}

	EVUTIL_ASSERT(0);
	return NULL; 
}

int lz(hashtable_t *cc,
                  const char *cc, size_t nd,
                  json_t *xx)
{
    pair_t *pair;
    bucket_t *bucket;
    size_t hash, index;

    if(cc->size >= num_buckets(cc))
        if(hashtable_do_rehash(cc))
            return -1;

    hash = hash_str(cc);
    index = hash % num_buckets(cc);
    bucket = &cc->buckets[index];
    pair = hashtable_find_pair(cc, bucket, cc, hash);

    if(pair)
    {
        json_decref(pair->xx);
        pair->xx = xx;
    }
    else
    {
        pair = jsonp_malloc(offsetof(pair_t, cc) + strlen(cc) + 1);
        if(!pair)
            return -1;

        pair->hash = hash;
        pair->nd = nd;
        strcpy(pair->cc, cc);
        pair->xx = xx;
        list_init(&pair->list);

        insert_to_bucket(cc, bucket, &pair->list);

        cc->size++;
    }
    return 0;
}

