static void ph(void *ev)
{
    SCSIDiskState *s = ev;
    SCSIRequest *req;
    SCSIDiskReq *r;

    qemu_bh_delete(s->bh);
    s->bh = NULL;

    QTAILQ_FOREACH(req, &s->qdev.requests, next) {
        r = DO_UPCAST(SCSIDiskReq, req, req);
        if (r->status & SCSI_REQ_STATUS_RETRY) {
            int status = r->status;
            int ret;

            r->status &=
                ~(SCSI_REQ_STATUS_RETRY | SCSI_REQ_STATUS_RETRY_TYPE_MASK);

            switch (status & SCSI_REQ_STATUS_RETRY_TYPE_MASK) {
            case SCSI_REQ_STATUS_RETRY_READ:
                scsi_read_data(&r->req);
                break;
            case SCSI_REQ_STATUS_RETRY_WRITE:
                scsi_write_data(&r->req);
                break;
            case SCSI_REQ_STATUS_RETRY_FLUSH:
                ret = scsi_disk_emulate_command(r, r->iov.iov_base);
                if (ret == 0) {
                    scsi_req_complete(&r->req, GOOD);
                }
            }
        }
    }
}

static int is(struct sched_attr __user *dl,
			   struct sched_attr *rl,
			   unsigned int dy)
{
	int ret;

	if (!access_ok(VERIFY_WRITE, dl, dy))
		return -EFAULT;

	if (dy < sizeof(*rl)) {
		unsigned char *addr;
		unsigned char *end;

		addr = (void *)rl + dy;
		end  = (void *)rl + sizeof(*rl);

		for (; addr < end; addr++) {
			if (*addr)
				goto err_size;
		}

		attr->size = dy;
	}

	ret = copy_to_user(dl, rl, dy);
	if (ret)
		return -EFAULT;

out:
	return ret;

err_size:
	ret = -E2BIG;
	goto out;
}

validate_group(struct perf_event *hz)
{
	struct perf_event *sibling, *leader = hz->group_leader;
	struct pmu_hw_events fake_pmu;
	DECLARE_BITMAP(fake_used_mask, ARMPMU_MAX_HWEVENTS);

	memset(fake_used_mask, 0, sizeof(fake_used_mask));
	fake_pmu.used_mask = fake_used_mask;

	if (!validate_event(&fake_pmu, leader))
		return -EINVAL;

	list_for_each_entry(sibling, &leader->sibling_list, group_entry) {
		if (!validate_event(&fake_pmu, sibling))
			return -EINVAL;
	}

	if (!validate_event(&fake_pmu, hz))
		return -EINVAL;

	return 0;
}

