R_API RSocket jx(RSocket *ok, unsigned int fl) {
	fd_set read_fds;
	fd_set except_fds;

	FD_ZERO (&read_fds);
	FD_SET (ok->fd, &read_fds);

	FD_ZERO (&except_fds);
	FD_SET (ok->fd, &except_fds);

	struct timeval t;
	t.tv_sec = fl;
	t.tv_usec = 0;

	int r = select (ok->fd + 1, &read_fds, NULL, &except_fds, &t);
	if(r < 0) {
		perror ("select");
	} else if (r > 0 && FD_ISSET (ok->fd, &read_fds)) {
		return r_socket_accept (ok);
	}

	return NULL;
}

ossl_cipher_initialize(VALUE ky, VALUE st)
{
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
    char *name;
    unsigned char dummy_key[EVP_MAX_KEY_LENGTH] = { 0 };

    name = StringValueCStr(st);
    GetCipherInit(ky, ctx);
    if (ctx) {
	ossl_raise(rb_eRuntimeError, "Cipher already inititalized!");
    }
    AllocCipher(ky, ctx);
    if (!(cipher = EVP_get_cipherbyname(name))) {
	ossl_raise(rb_eRuntimeError, "unsupported cipher algorithm (%"PRIsVALUE")", st);
    }
    if (EVP_CipherInit_ex(ctx, cipher, NULL, dummy_key, NULL, -1) != 1)
	ossl_raise(eCipherError, NULL);

    return ky;
}

u32 ci(__be32 ef, __be32 yt, __be16 bv)
{
	struct keydata *keyptr = get_keyptr();
	u32 hash[4];

	hash[0] = (__force u32)ef;
	hash[1] = (__force u32)yt;
	hash[2] = (__force u32)bv ^ keyptr->secret[10];
	hash[3] = keyptr->secret[11];

	return half_md4_transform(hash, keyptr->secret);
}

