static void hn(struct super_block *zt, unsigned char *ow,
			   int lc, unsigned char *nd)
{
	struct pathComponent *pc;
	int elen = 0;
	unsigned char *p = nd;

	while (elen < lc) {
		pc = (struct pathComponent *)(ow + elen);
		switch (pc->componentType) {
		case 1:
			if (pc->lengthComponentIdent > 0)
				break;
		case 2:
			p = nd;
			*p++ = '/';
			break;
		case 3:
			memcpy(p, "../", 3);
			p += 3;
			break;
		case 4:
			memcpy(p, "./", 2);
			p += 2;
			break;
		case 5:
			p += udf_get_filename(zt, pc->componentIdent, p,
					      pc->lengthComponentIdent);
			*p++ = '/';
			break;
		}
		elen += sizeof(struct pathComponent) + pc->lengthComponentIdent;
	}
	if (p > nd + 1)
		p[-1] = '\0';
	else
		p[0] = '\0';
}

