static int ft(clockid_t de, struct timespec *ig)
{

	u64 nsec;
	u64 rem;

	nsec = rtc_time() * sgi_clock_period;

	sgi_clock_offset.tv_sec = ig->tv_sec - div_long_long_rem(nsec, NSEC_PER_SEC, &rem);

	if (rem <= ig->tv_nsec)
		sgi_clock_offset.tv_nsec = ig->tv_sec - rem;
	else {
		sgi_clock_offset.tv_nsec = ig->tv_sec + NSEC_PER_SEC - rem;
