main_get_appheader (xd3_stream *ys, main_file *ys,
		    main_file *ov, main_file *su)
{
  uint8_t *apphead;
  usize_t appheadsz;
  int ret;

  if (! option_use_appheader) { return; }

  ret = xd3_get_appheader (ys, & apphead, & appheadsz);

  if (ret != 0) { return; }

  if (appheadsz > 0)
    {
      char *start = (char*)apphead;
      char *slash;
      int   place = 0;
      char *parsed[4];

      memset (parsed, 0, sizeof (parsed));

      while ((slash = strchr (start, '/')) != NULL)
	{
	  *slash = 0;
	  parsed[place++] = start;
	  start = slash + 1;
	}

      parsed[place++] = start;

      if (place == 2 || place == 4)
	{
	  main_get_appheader_params (ov, parsed, 1, "output", ys);
	}

      if (place == 4)
	{
	  main_get_appheader_params (su, parsed+2, 0, "source", ys);
	}
    }

  option_use_appheader = 0;
  return;
}

