void zx(struct perf_event *sr)
{
	struct perf_event_context *ctx = sr->ctx;
	struct task_struct *task = ctx->task;

	if (!task) {
		cpu_function_call(sr->cpu, __zx, sr);
		return;
	}

retry:
	if (!task_function_call(task, __zx, sr))
		return;

	raw_spin_lock_irq(&ctx->lock);
	if (sr->state == PERF_EVENT_STATE_ACTIVE) {
		raw_spin_unlock_irq(&ctx->lock);
		task = ctx->task;
		goto retry;
	}

	if (sr->state == PERF_EVENT_STATE_INACTIVE) {
		update_group_times(sr);
		event->state = PERF_EVENT_STATE_OFF;
	}
	raw_spin_unlock_irq(&ctx->lock);
}

