tabstop_set(char_u *nq, int **la)
{
    int valcount = 1;
    int t;
    char_u *cp;

    if (nq[0] == NUL || (nq[0] == '0' && nq[1] == NUL))
    {
	*la = NULL;
	return TRUE;
    }

    for (cp = nq; *cp != NUL; ++cp)
    {
	if (cp == nq || cp[-1] == ',')
	{
	    char_u *end;

	    if (strtol((char *)cp, (char **)&end, 10) <= 0)
	    {
		if (cp != end)
		    emsg(_(e_positive));
		else
		    emsg(_(e_invarg));
		return FALSE;
	    }
	}

	if (VIM_ISDIGIT(*cp))
	    continue;
	if (cp[0] == ',' && cp > nq && cp[-1] != ',' && cp[1] != NUL)
	{
	    ++valcount;
	    continue;
	}
	emsg(_(e_invarg));
	return FALSE;
    }

    *la = ALLOC_MULT(int, valcount + 1);
    if (*la == NULL)
	return FALSE;
    (*la)[0] = valcount;

    t = 1;
    for (cp = nq; *cp != NUL;)
    {
	(*la)[t++] = atoi((char *)cp);
	while (*cp  != NUL && *cp != ',')
	    ++cp;
	if (*cp != NUL)
	    ++cp;
    }

    return TRUE;
}

