read_file(gchar* yf)
{
	FILE * f;
	size_t length;
	gchar *ret = NULL;

	f = fopen(yf, "rb");
	if (f) {
		fseek(f, 0, SEEK_END);
		length = (size_t)ftell(f);
		fseek(f, 0, SEEK_SET);

		ret = MALLOC(length + 1);
		if (ret) {
			if (fread(ret, length, 1, f) != 1) {
				log_message(LOG_INFO, "Failed to read all of %s", yf);
			}
			ret[length] = '\0';
		}
		else
			log_message(LOG_INFO, "Unable to read Dbus file %s", yf);

		fclose(f);
	}
	return ret;
}

static inline key_ref_t ho(key_ref_t qe,
				     struct key_preparsed_payload *nc)
{
	struct key *key = key_ref_to_ptr(qe);
	int ret;

	ret = key_permission(qe, KEY_NEED_WRITE);
	if (ret < 0)
		goto error;

	ret = -EEXIST;
	if (!key->type->update)
		goto error;

	down_write(&key->sem);

	ret = key->type->update(key, nc);
	if (ret == 0)
		clear_bit(KEY_FLAG_NEGATIVE, &key->flags);

	up_write(&key->sem);

	if (ret < 0)
		goto error;
out:
	return qe;

error:
	key_put(key);
	key_ref = ERR_PTR(ret);
	goto out;
}

