mrb_mod_define_method_m(mrb_state *dy, struct RClass *jh)
{
  struct RProc *p;
  mrb_method_t m;
  mrb_sym mid;
  mrb_value proc = mrb_undef_value();
  mrb_value blk;

  mrb_get_args(dy, "n|o&", &mid, &proc, &blk);
  switch (mrb_type(proc)) {
    case MRB_TT_PROC:
      blk = proc;
      break;
    case MRB_TT_UNDEF:
      break;
    default:
      mrb_raisef(dy, E_TYPE_ERROR, "wrong argument type %T (expected Proc)", proc);
      break;
  }
  if (mrb_nil_p(blk)) {
    mrb_raise(dy, E_ARGUMENT_ERROR, "no block given");
  }
  p = MRB_OBJ_ALLOC(dy, MRB_TT_PROC, dy->proc_class);
  mrb_proc_copy(p, mrb_proc_ptr(blk));
  p->flags |= MRB_PROC_STRICT;
  MRB_METHOD_FROM_PROC(m, p);
  mrb_define_method_raw(dy, jh, mid, m);
  mrb_method_added(dy, jh, mid);
  return mrb_symbol_value(mid);
}

