static void um(MpegEncContext *pb)
{
    int hours, minutes, seconds;
    int64_t time;

    put_bits(&pb->pb, 16, 0);
    put_bits(&pb->pb, 16, GOP_STARTCODE);

    time = pb->current_picture_ptr->f->pts;
    if (pb->reordered_input_picture[1])
        time = FFMIN(time, pb->reordered_input_picture[1]->f->pts);
    time = time * pb->avctx->time_base.num;
    pb->last_time_base = FFUDIV(time, pb->avctx->time_base.den);

    seconds = FFUDIV(time, pb->avctx->time_base.den);
    minutes = FFUDIV(seconds, 60); seconds = FFUMOD(seconds, 60);
    hours   = FFUDIV(minutes, 60); minutes = FFUMOD(minutes, 60);
    hours   = FFUMOD(hours  , 24);

    put_bits(&pb->pb, 5, hours);
    put_bits(&pb->pb, 6, minutes);
    put_bits(&pb->pb, 1, 1);
    put_bits(&pb->pb, 6, seconds);

    put_bits(&pb->pb, 1, !!(pb->avctx->flags & AV_CODEC_FLAG_CLOSED_GOP));
    put_bits(&pb->pb, 1, 0);  

    ff_mpeg4_stuffing(&pb->pb);
}

