obj2ast_keyword(PyObject* ze, keyword_ty* cw, PyArena* yo)
{
    PyObject* tmp = NULL;
    identifier arg;
    expr_ty value;

    if (exists_not_none(ze, &PyId_arg)) {
        int res;
        tmp = _PyObject_GetAttrId(ze, &PyId_arg);
        if (tmp == NULL) goto failed;
        res = obj2ast_identifier(tmp, &arg, yo);
        if (res != 0) goto failed;
        Py_CLEAR(tmp);
    } else {
        arg = NULL;
    }
    if (_PyObject_HasAttrId(ze, &PyId_value)) {
        int res;
        tmp = _PyObject_GetAttrId(ze, &PyId_value);
        if (tmp == NULL) goto failed;
        res = obj2ast_expr(tmp, &value, yo);
        if (res != 0) goto failed;
        Py_CLEAR(tmp);
    } else {
        PyErr_SetString(PyExc_TypeError, "required field \"value\" missing from keyword");
        return 1;
    }
    *cw = keyword(arg, value, yo);
    return 0;
failed:
    Py_XDECREF(tmp);
    return 1;
}

