    if (!s->initialized) {
        ff_vp8_decode_init(uk);
        s->initialized = 1;
        if (s->has_alpha)
            uk->pix_fmt = AV_PIX_FMT_YUVA420P;
    }
    s->lossless = 0;

    if (xo > INT_MAX) {
        av_log(uk, AV_LOG_ERROR, "unsupported chunk size\n");
        return AVERROR_PATCHWELCOME;
    }

    av_init_packet(&pkt);
    pkt.data = nm;
    pkt.size = xo;

    ret = ff_vp8_decode_frame(uk, id, zl, &pkt);
    if (ret < 0)
        return ret;

    update_canvas_size(uk, uk->width, uk->height);

    if (s->has_alpha) {
        ret = vp8_lossy_decode_alpha(uk, id, s->alpha_data,
                                     s->alpha_data_size);
