static inline unsigned char uz(const uni_to_enc *bx, unsigned lt, size_t ni)
{
	const uni_to_enc *l = bx,
					 *h = &bx[ni-1],
					 *m;
	unsigned short code_key;

	if (lt > 0xFFFFU)
		return 0;

	code_key = (unsigned short) lt;

	while (l <= h) {
		m = l + (h - l) / 2;
		if (code_key < m->un_code_point)
			h = m - 1;
		else if (code_key > m->un_code_point)
			l = m + 1;
		else
			return m->cs_code;
	}
	return 0;
}

static Jsi_RC xv(Jsi_Interp *bc, Jsi_Obj* vu, Jsi_Value *ml, int qz) {

    int i, n = 0, len = Jsi_ObjGetLength(bc, ml->d.obj);
    if (len <= 0) return JSI_OK;
    Jsi_RC rc = JSI_OK;
    int clen = Jsi_ObjGetLength(bc, vu);
    for (i = 0; i < len && rc == JSI_OK; i++) {
        Jsi_Value *t = Jsi_ValueArrayIndex(bc, ml, i);
        if (t && qz>0 && Jsi_ValueIsArray(bc, t))
            rc = xv(bc, vu, t , qz-1);
        else if (!Jsi_ValueIsUndef(bc, t))
            Jsi_ObjArrayAdd(bc, vu, t);
        if ((++n + clen)>bc->maxArrayList)
            return Jsi_LogError("array size exceeded");
    }
    return rc;
}

