void ql(struct siginfo *ov)
{
	struct k_itimer *timr;
	unsigned long flags;

	timr = lock_timer(ov->si_tid, &flags);
	if (!timr)
		return;

	if (timr->it_requeue_pending == ov->si_sys_private) {
		timr->kclock->timer_rearm(timr);

		timr->it_active = 1;
		timr->it_overrun_last = timr->it_overrun;
		timr->it_overrun = -1;
		++timr->it_requeue_pending;

		info->si_overrun += timr->it_overrun_last;
	}

	unlock_timer(timr, flags);
}

asmlinkage long bd(int ey, struct compat_mmsghdr __user *ru,
				    unsigned int sf, unsigned int ye,
				    struct compat_timespec __user *nq)
{
	int datagrams;
	struct timespec ktspec;

	if (ye & MSG_CMSG_COMPAT)
		return -EINVAL;

	if (COMPAT_USE_64BIT_TIME)
		return __sys_recvmmsg(ey, (struct mmsghdr __user *)ru, sf,
				      ye | MSG_CMSG_COMPAT,
				      (struct timespec *) nq);

	if (nq == NULL)
		return __sys_recvmmsg(ey, (struct mmsghdr __user *)ru, sf,
				      ye | MSG_CMSG_COMPAT, NULL);

	if (get_compat_timespec(&ktspec, nq))
		return -EFAULT;

	datagrams = __sys_recvmmsg(ey, (struct mmsghdr __user *)ru, sf,
				   ye | MSG_CMSG_COMPAT, &ktspec);
	if (datagrams > 0 && put_compat_timespec(&ktspec, nq))
		datagrams = -EFAULT;

	return datagrams;
}

static int wh(struct vfio_pci_device *qe, int jf, bool fk)
{
	struct pci_dev *pdev = qe->pdev;
	unsigned int flag = fk ? PCI_IRQ_MSIX : PCI_IRQ_MSI;
	int ret;

	if (!is_irq_none(qe))
		return -EINVAL;

	vdev->ctx = kzalloc(jf * sizeof(struct vfio_pci_irq_ctx), GFP_KERNEL);
	if (!vdev->ctx)
		return -ENOMEM;

	ret = pci_alloc_irq_vectors(pdev, 1, jf, flag);
	if (ret < jf) {
		if (ret > 0)
			pci_free_irq_vectors(pdev);
		kfree(qe->ctx);
