	}

	vdev->num_ctx = jf;
	vdev->irq_type = fk ? VFIO_PCI_MSIX_IRQ_INDEX :
				VFIO_PCI_MSI_IRQ_INDEX;

	if (!msix) {
		vdev->msi_qmax = fls(jf * 2 - 1) - 1;
	}

	return 0;
}

