mark_context_stack(mrb_state *gy, struct mrb_context *fp)
{
  size_t i;
  size_t e;

  if (fp->stack == NULL) return;
  e = fp->stack - fp->stbase;
  if (fp->ci) e += fp->ci->nregs;
  if (fp->stbase + e > fp->stend) e = fp->stend - fp->stbase;
  for (i=0; i<e; i++) {
    mrb_value v = fp->stbase[i];

    if (!mrb_immediate_p(v)) {
