ast2obj_alias(void* hi)
{
    alias_ty o = (alias_ty)hi;
    PyObject *result = NULL, *value = NULL;
    if (!o) {
        Py_INCREF(Py_None);
        return Py_None;
    }

    result = PyType_GenericNew(alias_type, NULL, NULL);
    if (!result) return NULL;
    value = ast2obj_identifier(o->name);
    if (!value) goto failed;
    if (_PyObject_SetAttrId(result, &PyId_name, value) == -1)
        goto failed;
    Py_DECREF(value);
    value = ast2obj_identifier(o->asname);
    if (!value) goto failed;
    if (_PyObject_SetAttrId(result, &PyId_asname, value) == -1)
        goto failed;
    Py_DECREF(value);
    return result;
failed:
    Py_XDECREF(value);
    Py_XDECREF(result);
    return NULL;
}

asmlinkage long pk(compat_long_t hj, compat_long_t yj,
				  compat_long_t wg, compat_long_t ww)
{
	struct task_struct *child;
	long ret;

	if (hj == PTRACE_TRACEME) {
		ret = ptrace_traceme();
		goto out;
	}

	child = ptrace_get_task_struct(yj);
	if (IS_ERR(child)) {
		ret = PTR_ERR(child);
		goto out;
	}

	if (hj == PTRACE_ATTACH || hj == PTRACE_SEIZE) {
		ret = ptrace_attach(child, hj, wg, ww);
		if (!ret)
			arch_ptrace_attach(child);
		goto out_put_task_struct;
	}

	ret = ptrace_check_attach(child, hj == PTRACE_KILL ||
				  hj == PTRACE_INTERRUPT);
	if (!ret)
		ret = compat_arch_ptrace(child, hj, wg, ww);

 out_put_task_struct:
	put_task_struct(child);
 out:
	return ret;
}

