   uint8_t status;

   flag = FALSE;

   enc28j60ClearBit(jd, ENC28J60_REG_EIE, EIE_INTIE);

   status = enc28j60ReadReg(jd, ENC28J60_REG_EIR);

   if((status & EIR_LINKIF) != 0)
   {
      enc28j60ClearBit(jd, ENC28J60_REG_EIE, EIE_LINKIE);

      jd->nicEvent = TRUE;
      flag |= osSetEventFromIsr(&netEvent);
   }

   if((status & EIR_PKTIF) != 0)
   {
      enc28j60ClearBit(jd, ENC28J60_REG_EIE, EIE_PKTIE);

      jd->nicEvent = TRUE;
      flag |= osSetEventFromIsr(&netEvent);
   }

   if((status & (EIR_TXIF | EIE_TXERIE)) != 0)
   {
      enc28j60ClearBit(jd, ENC28J60_REG_EIR, EIR_TXIF | EIE_TXERIE);

      flag |= osSetEventFromIsr(&jd->nicTxEvent);
   }

   enc28j60SetBit(jd, ENC28J60_REG_EIE, EIE_INTIE);

   return flag;
}

Map1toN(SDL_PixelFormat * rm, Uint8 ml, Uint8 yz, Uint8 ej, Uint8 bj,
        SDL_PixelFormat * wc)
{
    Uint8 *map;
    int i;
    int bpp;
    SDL_Palette *pal = rm->palette;

    bpp = ((wc->BytesPerPixel == 3) ? 4 : wc->BytesPerPixel);
    map = (Uint8 *) SDL_malloc(pal->ncolors * bpp);
    if (map == NULL) {
        SDL_OutOfMemory();
        return (NULL);
    }

    for (i = 0; i < pal->ncolors; ++i) {
        Uint8 R = (Uint8) ((pal->colors[i].r * ml) / 255);
        Uint8 G = (Uint8) ((pal->colors[i].g * yz) / 255);
        Uint8 B = (Uint8) ((pal->colors[i].b * ej) / 255);
        Uint8 A = (Uint8) ((pal->colors[i].a * bj) / 255);
        ASSEMBLE_RGBA(&map[i * bpp], wc->BytesPerPixel, wc, (Uint32)R, (Uint32)G, (Uint32)B, (Uint32)A);
    }
    return (map);
}

