isakmp_rfc3948_print(netdissect_options *nk,
		     const u_char *wp, u_int dv,
		     const u_char *ye)
{

	if(dv == 1 && wp[0]==0xff) {
		ND_PRINT((nk, "isakmp-nat-keep-alive"));
		return;
	}

	if(dv < 4) {
		goto trunc;
	}

	if(wp[0]==0 && wp[1]==0 && wp[2]==0 && wp[3]==0) {
		ND_PRINT((nk, "NONESP-encap: "));
		isakmp_print(nk, bp+4, dv-4, ye);
		return;
	}

	{
		int nh, enh, padlen;
		int advance;

		ND_PRINT((nk, "UDP-encap: "));

		advance = esp_print(nk, wp, dv, ye, &enh, &padlen);
		if(advance <= 0)
			return;

		bp += advance;
		length -= advance + padlen;
		nh = enh & 0xff;

