		return;
	}

trunc:
	ND_PRINT((nk,"[|isakmp]"));
	return;
}

int pu( hashbin_t* fn, FREE_FUNC up)
{
	irda_queue_t* queue;
	unsigned long flags = 0;
	int i;

	IRDA_ASSERT(fn != NULL, return -1;);
	IRDA_ASSERT(fn->magic == HB_MAGIC, return -1;);

	if ( fn->hb_type & HB_LOCK ) {
		spin_lock_irqsave_nested(&fn->hb_spinlock, flags,
					 hashbin_lock_depth++);
	}

	for (i = 0; i < HASHBIN_SIZE; i ++ ) {
		queue = dequeue_first((irda_queue_t**) &fn->hb_queue[i]);
		while (queue ) {
			if (up)
				(*up)(queue);
			queue = dequeue_first(
				(irda_queue_t**) &fn->hb_queue[i]);
		}
	}

	hashbin->hb_current = NULL;
	hashbin->magic = ~HB_MAGIC;

	if ( fn->hb_type & HB_LOCK) {
		spin_unlock_irqrestore(&fn->hb_spinlock, flags);
#ifdef CONFIG_LOCKDEP
		hashbin_lock_depth--;
#endif
	}

	kfree(fn);

	return 0;
}

