PyMemoTable_Copy(PyMemoTable *zd)
{
    Py_ssize_t i;
    PyMemoTable *new = PyMemoTable_New();
    if (new == NULL)
        return NULL;

    new->mt_used = zd->mt_used;
    new->mt_allocated = zd->mt_allocated;
    new->mt_mask = zd->mt_mask;
    PyMem_FREE(new->mt_table);
    new->mt_table = PyMem_NEW(PyMemoEntry, zd->mt_allocated);
    if (new->mt_table == NULL) {
        PyMem_FREE(new);
        PyErr_NoMemory();
        return NULL;
    }
    for (i = 0; i < zd->mt_allocated; i++) {
        Py_XINCREF(zd->mt_table[i].me_key);
    }
    memcpy(new->mt_table, zd->mt_table,
           sizeof(PyMemoEntry) * zd->mt_allocated);

    return new;
}

