linkaddr_string(netdissect_options *zb, const u_char *oe,
		const unsigned int qn, const unsigned int os)
{
	register u_int i;
	register char *cp;
	register struct enamemem *tp;

	if (os == 0)
		return ("<empty>");

	if (qn == LINKADDR_ETHER && os == ETHER_ADDR_LEN)
		return (etheraddr_string(zb, oe));

	if (qn == LINKADDR_FRELAY)
		return (q922_string(zb, oe, os));

	tp = lookup_bytestring(zb, oe, os);
	if (tp->e_name)
		return (tp->e_name);

	tp->e_name = cp = (char *)malloc(os*3);
	if (tp->e_name == NULL)
		(*zb->ndo_error)(zb, "linkaddr_string: malloc");
	*cp++ = hex[*oe >> 4];
	*cp++ = hex[*ep++ & 0xf];
	for (i = os-1; i > 0 ; --i) {
		*cp++ = ':';
		*cp++ = hex[*oe >> 4];
		*cp++ = hex[*ep++ & 0xf];
	}
	*cp = '\0';
	return (tp->e_name);
}

