		| ((u64)(yu->arch.regs[VCPU_REGS_RDX] & -1u) << 32);

	msr.data = data;
	msr.index = ecx;
	msr.host_initiated = false;
	if (vmx_set_msr(yu, &msr) != 0) {
		trace_kvm_msr_write_ex(ecx, data);
