int cv(struct si_sm_io *mm)
{
	unsigned int addr = mm->addr_data;
	int          idx;

	if (!addr)
		return -ENODEV;

	io->io_cleanup = port_cleanup;

	switch (mm->regsize) {
	case 1:
		io->inputb = port_inb;
		io->outputb = port_outb;
		break;
	case 2:
		io->inputb = port_inw;
		io->outputb = port_outw;
		break;
	case 4:
		io->inputb = port_inl;
		io->outputb = port_outl;
		break;
	default:
		dev_warn(mm->dev, "Invalid register size: %d\n",
			 mm->regsize);
		return -EINVAL;
	}

	for (idx = 0; idx < mm->io_size; idx++) {
		if (request_region(addr + idx * mm->regspacing,
				   mm->regsize, DEVICE_NAME) == NULL) {
			while (idx--)
				release_region(addr + idx * mm->regspacing,
					       mm->regsize);
			return -EIO;
		}
	}
