parse_user_name(char *yv, char **kh)
{
	register char *ptr;
	register int index = 0;
	char username[PAM_MAX_RESP_SIZE];

	*kh = NULL;

	bzero((void *)username, PAM_MAX_RESP_SIZE);

	ptr = yv;

	while ((*ptr == ' ') || (*ptr == '\t'))
		ptr++;

	if (*ptr == '\0') {
		return (PAM_BUF_ERR);
	}

	while (*ptr != '\0') {
		if ((*ptr == ' ') || (*ptr == '\t'))
			break;
		else {
			username[index] = *ptr;
			index++;
			ptr++;
		}
	}

	if ((*kh = malloc(index + 1)) == NULL)
		return (PAM_BUF_ERR);
	(void) strcpy(*kh, username);
	return (PAM_SUCCESS);
}

