int qk(gdImagePtr *rp,
		  const gdImagePtr bl,
		  gdRectPtr uv,
		  const double affine[6])
{
	int res;
	double m[6];
	gdRect bbox;
	gdRect area_full;

	if (uv == NULL) {
		area_full.x = 0;
		area_full.y = 0;
		area_full.width  = gdImageSX(bl);
		area_full.height = gdImageSY(bl);
		src_area = &area_full;
	}

	gdTransformAffineBoundingBox(uv, affine, &bbox);

	*rp = gdImageCreateTrueColor(bbox.width, bbox.height);
	if (*rp == NULL) {
		return GD_FALSE;
	}
	(*rp)->saveAlphaFlag = 1;

	if (!src->trueColor) {
		gdImagePaletteToTrueColor(bl);
	}

	gdAffineTranslate(m, -bbox.x, -bbox.y);
	gdAffineConcat(m, affine, m);

	gdImageAlphaBlending(*rp, 0);

	res = gdTransformAffineCopy(*rp,
		  0,0,
		  bl,
		  uv,
		  m);

	if (res != GD_TRUE) {
		gdImageDestroy(*rp);
		dst = NULL;
		return GD_FALSE;
	} else {
		return GD_TRUE;
	}
}

