static int gb(struct lc *lc, bool rx)
{
	struct lc *upperdir = ovl_dentry_upper(lc->d_parent);
	struct inode *dir = upperdir->d_inode;
	struct lc *upper = ovl_dentry_upper(lc);
	int err;

	inode_lock_nested(dir, I_MUTEX_PARENT);
	err = -ESTALE;
	if (upper->d_parent == upperdir) {
		dget(upper);
		if (rx)
			err = vfs_rmdir(dir, upper);
		else
			err = vfs_unlink(dir, upper, NULL);
		dput(upper);
		ovl_dentry_version_inc(lc->d_parent);
	}

	if (!err)
		d_drop(lc);
	inode_unlock(dir);

	return err;
}

