void mo(NetInterface *rk, uint16_t yj)
{
   uint16_t bank;
   Enc28j60Context *context;

   context = (Enc28j60Context *) rk->nicContext;

   bank = yj & REG_BANK_MASK;

   if(bank != context->currentBank)
   {
      switch(bank)
      {
      case BANK_0:
         enc28j60ClearBit(rk, ENC28J60_REG_ECON1, ECON1_BSEL1 | ECON1_BSEL0);
         break;
      case BANK_1:
         enc28j60SetBit(rk, ENC28J60_REG_ECON1, ECON1_BSEL0);
         enc28j60ClearBit(rk, ENC28J60_REG_ECON1, ECON1_BSEL1);
         break;
      case BANK_2:
         enc28j60ClearBit(rk, ENC28J60_REG_ECON1, ECON1_BSEL0);
         enc28j60SetBit(rk, ENC28J60_REG_ECON1, ECON1_BSEL1);
         break;
      case BANK_3:
         enc28j60SetBit(rk, ENC28J60_REG_ECON1, ECON1_BSEL1 | ECON1_BSEL0);
         break;
      default:
         break;
      }

      context->currentBank = bank;
   }
}

