	depth = ext_depth(ru);
	ex = vk[depth].p_ext;

	ext_debug("iy: ru %lu, logical"
		"block %llu, max_blocks %u\n", ru->i_ino,
		(unsigned long long)le32_to_cpu(ex->ee_block),
		ext4_ext_get_actual_len(ex));

	err = ext4_ext_get_access(hp, ru, vk + depth);
	if (err)
		goto out;
	ext4_ext_mark_initialized(ex);

