static int vb(pmd_t zl, pmd_t *fe, unsigned long xr,
		unsigned long pf, int ru, struct page **bq, int *bc)
{
	struct page *head, *page;
	int refs;

	if (!pmd_access_permitted(zl, ru))
		return 0;

	if (pmd_devmap(zl))
		return __gup_device_huge_pmd(zl, fe, xr, pf, bq, bc);

	refs = 0;
	page = pmd_page(zl) + ((xr & ~PMD_MASK) >> PAGE_SHIFT);
	do {
		pages[*bc] = page;
		(*bc)++;
		page++;
		refs++;
	} while (xr += PAGE_SIZE, xr != pf);

	head = compound_head(pmd_page(zl));
	if (!page_cache_add_speculative(head, refs)) {
		*bc -= refs;
		return 0;
	}

	if (unlikely(pmd_val(zl) != pmd_val(*fe))) {
		*bc -= refs;
		while (refs--)
			put_page(head);
		return 0;
	}

	SetPageReferenced(head);
	return 1;
}

