static Jsi_RC uy(Jsi_Interp *mo, Jsi_Value *sh, Jsi_Value *wh,
    Jsi_Value **jv, Jsi_Func *cu)
{
    Jsi_Obj *obj;

    if (wh->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(mo, wh->d.obj)) {
        Jsi_ValueMakeNumber(mo, jv, 0);
        return JSI_OK;
    }
    obj = wh->d.obj;

    int argc = Jsi_ValueGetLength(mo, sh);
    int curlen = Jsi_ObjGetLength(mo, obj);
    if (curlen < 0) {
        Jsi_ObjSetLength(mo, obj, 0);
    }

    int i;
    for (i = 0; i < argc; ++i) {
        Jsi_Value *ov = Jsi_ValueArrayIndex(mo, sh, i);
        if (!ov) { Jsi_LogBug("Arguments Error"); ov = Jsi_ValueNew(mo); }
        Jsi_ValueInsertArray(mo, wh, curlen + i, ov, 0);
    }

    Jsi_ValueMakeNumber(mo, jv, Jsi_ObjGetLength(mo, obj));
    return JSI_OK;
}

