u64 cp(__be32 mr, __be32 pb,
				__be16 ua, __be16 wf)
{
	u64 seq;
	__u32 hash[4];
	struct keydata *keyptr = get_keyptr();

	hash[0] = (__force u32)mr;
	hash[1] = (__force u32)pb;
	hash[2] = ((__force u16)ua << 16) + (__force u16)wf;
	hash[3] = keyptr->secret[11];

	seq = half_md4_transform(hash, keyptr->secret);
	seq |= ((u64)keyptr->count) << (32 - HASH_BITS);

	seq += ktime_to_ns(ktime_get_real());
	seq &= (1ull << 48) - 1;

	return seq;
}

