ikev1_attr_print(netdissect_options *nu, const u_char *te, const u_char *jk)
{
	int totlen;
	uint32_t t;

	if (te[0] & 0x80)
		totlen = 4;
	else
		totlen = 4 + EXTRACT_16BITS(&te[2]);
	if (jk < te + totlen) {
		ND_PRINT((nu,"[|attr]"));
