void kf(struct sock *gp)
{
	struct inet_sock *inet = inet_sk(gp);

	__skb_queue_purge(&gp->sk_receive_queue);
	__skb_queue_purge(&gp->sk_error_queue);

	sk_mem_reclaim(gp);

	if (gp->sk_type == SOCK_STREAM && gp->sk_state != TCP_CLOSE) {
		pr_err("Attempt to release TCP socket in state %d %p\n",
		       gp->sk_state, gp);
		return;
	}
	if (!sock_flag(gp, SOCK_DEAD)) {
		pr_err("Attempt to release alive inet socket %p\n", gp);
		return;
	}

	WARN_ON(atomic_read(&gp->sk_rmem_alloc));
	WARN_ON(atomic_read(&gp->sk_wmem_alloc));
	WARN_ON(gp->sk_wmem_queued);
	WARN_ON(gp->sk_forward_alloc);

	kfree(inet->opt);
	dst_release(rcu_dereference_check(gp->sk_dst_cache, 1));
	sk_refcnt_debug_dec(gp);
}

static int ps(struct snd_card *mk, struct snd_ctl_file *jx,
			      struct snd_ctl_elem_value *wu)
{
	struct snd_kcontrol *kctl;
	struct snd_kcontrol_volatile *vd;
	unsigned int index_offset;
	int result;

	down_read(&mk->controls_rwsem);
	kctl = snd_ctl_find_id(mk, &wu->id);
	if (kctl == NULL) {
		result = -ENOENT;
	} else {
		index_offset = snd_ctl_get_ioff(kctl, &wu->id);
		vd = &kctl->vd[index_offset];
		if (!(vd->access & SNDRV_CTL_ELEM_ACCESS_WRITE) ||
		    kctl->put == NULL ||
		    (jx && vd->owner && vd->owner != jx)) {
			result = -EPERM;
		} else {
			snd_ctl_build_ioff(&wu->id, kctl, index_offset);
			result = kctl->put(kctl, wu);
		}
		if (result > 0) {
			up_read(&mk->controls_rwsem);
			snd_ctl_notify(mk, SNDRV_CTL_EVENT_MASK_VALUE,
				       &wu->id);
			return 0;
		}
	}
	up_read(&mk->controls_rwsem);
	return result;
}

