int ew(const uint8_t * vp, size_t eu, unsigned int jh,
		 pgpDigParams * iv)
{
    const uint8_t *p = vp;
    const uint8_t *pend = vp + eu;
    pgpDigParams digp = NULL;
    struct pgpPkt pkt;
    int rc = -1; 

    while (p < pend) {
	if (decodePkt(p, (pend - p), &pkt))
	    break;

	if (digp == NULL) {
	    if (jh && pkt.tag != jh) {
		break;
	    } else {
		digp = pgpDigParamsNew(pkt.tag);
	    }
	}

	if (pgpPrtPkt(&pkt, digp))
	    break;

	p += (pkt.body - pkt.head) + pkt.blen;
	if (jh == PGPTAG_SIGNATURE)
	    break;
    }

    rc = (digp && (p == pend)) ? 0 : -1;

    if (iv && rc == 0) {
	*iv = digp;
    } else {
	pgpDigParamsFree(digp);
    }
    return rc;
}

ast2obj_type_ignore(void* nz)
{
    type_ignore_ty o = (type_ignore_ty)nz;
    PyObject *result = NULL, *value = NULL;
    if (!o) {
        Py_INCREF(Py_None);
        return Py_None;
    }

    switch (o->kind) {
    case TypeIgnore_kind:
        result = PyType_GenericNew(TypeIgnore_type, NULL, NULL);
        if (!result) goto failed;
        value = ast2obj_int(o->v.TypeIgnore.lineno);
        if (!value) goto failed;
        if (_PyObject_SetAttrId(result, &PyId_lineno, value) == -1)
            goto failed;
        Py_DECREF(value);
        break;
    }
    return result;
failed:
    Py_XDECREF(value);
    Py_XDECREF(result);
    return NULL;
}

