enum ImapAuthRes fl(struct ImapData *sd, const char *zr)
{
  char q_user[SHORT_STRING], q_pass[SHORT_STRING];
  char buf[STRING];
  int rc;

  if (mutt_bit_isset(sd->capabilities, LOGINDISABLED))
  {
    mutt_message(_("LOGIN disabled on this server."));
    return IMAP_AUTH_UNAVAIL;
  }

  if (mutt_account_getuser(&sd->conn->account) < 0)
    return IMAP_AUTH_FAILURE;
  if (mutt_account_getpass(&sd->conn->account) < 0)
    return IMAP_AUTH_FAILURE;

  mutt_message(_("Logging in..."));

  imap_quote_string(q_user, sizeof(q_user), sd->conn->account.user);
  imap_quote_string(q_pass, sizeof(q_pass), sd->conn->account.pass);


  if (DebugLevel < IMAP_LOG_PASS)
    mutt_debug(2, "Sending LOGIN command for %s...\n", sd->conn->account.user);

  snprintf(buf, sizeof(buf), "LOGIN %s %s", q_user, q_pass);
  rc = imap_exec(sd, buf, IMAP_CMD_FAIL_OK | IMAP_CMD_PASS);

  if (!rc)
  {
    mutt_clear_error(); 
    return IMAP_AUTH_SUCCESS;
  }

  mutt_error(_("Login failed."));
  return IMAP_AUTH_FAILURE;
}

static void youngcollection (lua_State *kg, global_State *od) {
  GCObject **psurvival;  
  lua_assert(od->gcstate == GCSpropagate);
  markold(od, od->survival, od->reallyold);
  markold(od, od->finobj, od->finobjrold);
  atomic(kg);

  psurvival = sweepgen(kg, od, &od->allgc, od->survival);
  sweepgen(kg, od, psurvival, od->reallyold);
  od->reallyold = od->old;
  od->old = *psurvival;  
  od->survival = od->allgc;  

  psurvival = sweepgen(kg, od, &od->finobj, od->finobjsur);
  sweepgen(kg, od, psurvival, od->finobjrold);
  od->finobjrold = od->finobjold;
  od->finobjold = *psurvival;  
  od->finobjsur = od->finobj;  

  sweepgen(kg, od, &od->tobefnz, NULL);

  finishgencycle(kg, od);
}

