static StkId rethook (lua_State *nf, CallInfo *pu, StkId rw, int uf) {
  ptrdiff_t oldtop = savestack(nf, nf->top);  
  int delta = 0;
  if (isLuacode(pu)) {
    Proto *p = clLvalue(s2v(pu->func))->p;
    if (p->is_vararg)
      delta = pu->u.l.nextraargs + p->numparams + 1;
    if (nf->top < pu->top)
      nf->top = pu->top;  
  }
  if (nf->hookmask & LUA_MASKRET) {  
    int ftransfer;
    pu->func += delta;  
    ftransfer = cast(unsigned short, rw - pu->func);
    luaD_hook(nf, LUA_HOOKRET, -1, ftransfer, uf);  
    pu->func -= delta;
  }
  if (isLua(pu->previous))
    nf->oldpc = pu->previous->u.l.savedpc;  
  return restorestack(nf, oldtop);
}

static void ef(HttpRoute *pj)
{
    Http        *http;
    HttpHost    *host;
    HttpRoute   *rp;
    MprJson     *mappings, *client;
    int         nextHost, nextRoute;

    if (pj->error) {
        return;
    }
    http = pj->http;
    pj->mode = mprGetJson(pj->config, "app.mode");

    if ((mappings = mprGetJsonObj(pj->config, "app.client.mappings")) != 0) {
        client = mprCreateJson(MPR_JSON_OBJ);
        clientCopy(pj, client, mappings);
        mprSetJson(client, "prefix", pj->prefix);
        pj->client = mprJsonToString(client, MPR_JSON_QUOTES);
    }
    httpAddHostToEndpoints(pj->host);

    for (nextHost = 0; (host = mprGetNextItem(http->hosts, &nextHost)) != 0; ) {
        for (nextRoute = 0; (rp = mprGetNextItem(host->routes, &nextRoute)) != 0; ) {
            if (!mprLookupKey(rp->extensions, "")) {
                if (!rp->handler) {
                    httpAddRouteHandler(rp, "fileHandler", "");
                    httpAddRouteIndex(rp, "index.html");
                }
            }
            if (rp->parent == pj) {
                rp->client = pj->client;
            }
        }
    }
}

