file_extension(const char *up)	
{
  const char	*extension;	
  static char	buf[1024];	


  if (up == NULL)
    return (NULL);
  else if (!strncmp(up, "data:image/bmp;", 15))
    return ("bmp");
  else if (!strncmp(up, "data:image/gif;", 15))
    return ("gif");
  else if (!strncmp(up, "data:image/jpeg;", 16))
    return ("jpg");
  else if (!strncmp(up, "data:image/png;", 15))
    return ("png");
  else if ((extension = strrchr(up, '/')) != NULL)
    extension ++;
  else if ((extension = strrchr(up, '\\')) != NULL)
    extension ++;
  else
    extension = up;

  if ((extension = strrchr(extension, '.')) == NULL)
    return ("");
  else
    extension ++;

  if (strchr(extension, '#') == NULL)
    return (extension);

  strlcpy(buf, extension, sizeof(buf));

  *(char *)strchr(buf, '#') = '\0';

  return (buf);
}

