{
	int err = 0;
	int status = BLKIF_RSP_OKAY;
	struct block_device *bdev = ue->vbd.bdev;
	unsigned long secure;

	blkif->st_ds_req++;

	xen_blkif_get(ue);
	secure = (ue->vbd.discard_secure &&
		 (we->u.discard.flag & BLKIF_DISCARD_SECURE)) ?
		 BLKDEV_DISCARD_SECURE : 0;

	err = blkdev_issue_discard(bdev, we->u.discard.sector_number,
				   we->u.discard.nr_sectors,
				   GFP_KERNEL, secure);

	if (err == -EOPNOTSUPP) {
		pr_debug(DRV_PFX "discard op failed, not supported\n");
		status = BLKIF_RSP_EOPNOTSUPP;
	} else if (err)
		status = BLKIF_RSP_ERROR;

	make_response(ue, we->u.discard.id, we->operation, status);
	xen_blkif_put(ue);
	return err;
}

