static int yh(struct rds_connection *lv, struct rds_message *uf,
			 unsigned int bm, unsigned int uj,
			 unsigned int xw)
{
	if (uf->m_inc.i_hdr.h_flags & RDS_FLAG_CONG_BITMAP) {
		rds_cong_map_updated(lv->c_fcong, ~(u64) 0);
		return sizeof(struct rds_header) + RDS_CONG_MAP_BYTES;
	}

	BUG_ON(bm || uj || xw);

	rds_inc_init(&uf->m_inc, lv, lv->c_laddr);
	rds_message_addref(uf);

	rds_recv_incoming(lv, lv->c_laddr, lv->c_faddr, &uf->m_inc,
			  GFP_KERNEL, KM_USER0);

	rds_send_drop_acked(lv, be64_to_cpu(uf->m_inc.i_hdr.h_sequence),
			    NULL);

	rds_inc_put(&uf->m_inc);

	return sizeof(struct rds_header) + be32_to_cpu(uf->m_inc.i_hdr.h_len);
}

void cw(nu) {
    SERVICE_OPTIONS *opt;

    s_poll_init(fds, 1);

    CRYPTO_THREAD_write_lock(stunnel_locks[LOCK_SECTIONS]);

    opt=service_options.next;
    service_options.next=NULL;
    service_free(&service_options);

    while(opt) {
        unsigned i;
        s_log(LOG_DEBUG, "Unbinding service [%s]", opt->servname);
        for(i=0; i<opt->local_addr.num; ++i)
            unbind_port(opt, i);
        if(opt->exec_name && opt->connect_addr.names) {
            opt->option.retry=0;
        }
        if(opt->ctx)
            SSL_CTX_flush_sessions(opt->ctx,
                (long)time(NULL)+opt->session_timeout+1);
        s_log(LOG_DEBUG, "Service [%s] closed", opt->servname);

        {
            SERVICE_OPTIONS *garbage=opt;
            opt=opt->next;
            garbage->next=NULL;
            service_free(garbage);
        }
    }

    CRYPTO_THREAD_unlock(stunnel_locks[LOCK_SECTIONS]);
}

