    count = avio_rl32(pb);    
    avio_rl16(pb);            
    name_len = avio_rl16(pb); 
    for (i = 0; i < name_len; i++)
        avio_r8(pb); 

    for (i = 0; i < count; i++) {
        int64_t pres_time;
        int name_len;

        avio_rl64(pb);             
        pres_time = avio_rl64(pb); 
        pres_time -= asf->hdr.preroll * 10000;
        avio_rl16(pb);             
        avio_rl32(pb);             
        avio_rl32(pb);             
        name_len = avio_rl32(pb);  
        if ((ret = avio_get_str16le(pb, name_len * 2, name,
                                    sizeof(name))) < name_len)
            avio_skip(pb, name_len - ret);
        avpriv_new_chapter(da, i, (AVRational) { 1, 10000000 }, pres_time,
                           AV_NOPTS_VALUE, name);
    }

    return 0;
}

horAcc16(TIFF* sh, uint8* qv, tmsize_t oa)
{
	tmsize_t stride = PredictorState(sh)->stride;
	uint16* wp = (uint16*) qv;
	tmsize_t wc = oa / 2;

	assert((cc%(2*stride))==0);

	if (wc > stride) {
		wc -= stride;
		do {
			REPEAT4(stride, wp[stride] = (uint16)(((unsigned int)wp[stride] + (unsigned int)wp[0]) & 0xffff); wp++)
			wc -= stride;
		} while (wc > 0);
	}
}

