static int ye(AVFilterLink *je, AVFrame *my)
{
    GradFunContext *s = je->dst->priv;
    AVFilterLink *outlink = je->dst->outputs[0];
    AVFrame *out;
    int p, direct;

    if (av_frame_is_writable(my)) {
        direct = 1;
        out = my;
    } else {
        direct = 0;
        out = ff_get_video_buffer(outlink, outlink->w, outlink->h);
        if (!out) {
            av_frame_free(&my);
            return AVERROR(ENOMEM);
        }
        av_frame_copy_props(out, my);
    }

    for (p = 0; p < 4 && my->data[p]; p++) {
        int w = je->w;
        int h = je->h;
        int r = s->radius;
        if (p) {
            w = s->chroma_w;
            h = s->chroma_h;
            r = s->chroma_r;
        }

        if (FFMIN(w, h) > 2 * r)
            filter(s, out->data[p], my->data[p], w, h, out->linesize[p], my->linesize[p], r);
        else if (out->data[p] != my->data[p])
            av_image_copy_plane(out->data[p], out->linesize[p], my->data[p], my->linesize[p], w, h);
    }

    if (!direct)
        av_frame_free(&my);

    return ff_ye(outlink, out);
}

