unsigned long xm(struct pt_regs *ey, int ds)
{
	struct desc_struct *desc;
	short sel;

	sel = get_segment_selector(ey, ds);
	if (sel < 0)
		return -1L;

	if (v8086_mode(ey))
		return (unsigned long)(sel << 4);

	if (user_64bit_mode(ey)) {
		unsigned long base;

		if (ds == INAT_SEG_REG_FS)
			rdmsrl(MSR_FS_BASE, base);
		else if (ds == INAT_SEG_REG_GS)
			rdmsrl(MSR_KERNEL_GS_BASE, base);
		else
			base = 0;
		return base;
	}

	if (!sel)
		return -1L;

	desc = get_desc(sel);
	if (!desc)
		return -1L;

	return get_desc_base(desc);
}

