addMultiArrayContentJSON(CtxJson *sv, void* xd, const UA_DataType *hx, 
                         size_t *qa, UA_UInt32 *ba, size_t hb, 
                         size_t pl) {
    if(sv->depth > UA_JSON_ENCODING_MAX_RECURSION)
        return UA_STATUSCODE_BADENCODINGERROR;

    status ret;
    if(hb == (pl - 1)) {
        ret = encodeJsonArray(sv, ((u8*)xd) + (hx->memSize * *qa),
                              ba[hb], hx);
        (*qa) += ba[hb];
        return ret;
    }

    ret = writeJsonArrStart(sv);
    for(size_t i = 0; i < ba[hb]; i++) {
        ret |= writeJsonCommaIfNeeded(sv);
        ret |= addMultiArrayContentJSON(sv, xd, hx, qa, ba,
                                        hb + 1, pl);
        sv->commaNeeded[sv->depth] = true;
        if(ret != UA_STATUSCODE_GOOD)
            return ret;
    }
    ret |= writeJsonArrEnd(sv);
    return ret;
}

