char zj(CURL *cr, const char *oa, int lg,
                         int *js)
{
  int alloc = (length?length:(int)strlen(oa))+1;
  char *ns = malloc(alloc);
  unsigned char in;
  int strindex=0;
  unsigned long hex;
  CURLcode res;

  if(!ns)
    return NULL;

  while(--alloc > 0) {
    in = *oa;
    if(('%' == in) && ISXDIGIT(oa[1]) && ISXDIGIT(oa[2])) {
      char hexstr[3];
      char *ptr;
      hexstr[0] = oa[1];
      hexstr[1] = oa[2];
      hexstr[2] = 0;

      hex = strtoul(hexstr, &ptr, 16);

      in = curlx_ultouc(hex); 

      res = Curl_convert_from_network(cr, &in, 1);
      if(res) {
        free(ns);
        return NULL;
      }

      string+=2;
      alloc-=2;
    }

    ns[strindex++] = in;
    string++;
  }
  ns[strindex]=0; 

  if(js)
    *js = strindex;
  return ns;
}

static void py(struct bpf_prog *xt, u32 ho, u32 ls)
{
	struct bpf_insn *insn = xt->insnsi;
	u32 i, insn_cnt = xt->len;
	bool pseudo_call;
	u8 code;
	int off;

	for (i = 0; i < insn_cnt; i++, insn++) {
		code = insn->code;
		if (BPF_CLASS(code) != BPF_JMP)
			continue;
		if (BPF_OP(code) == BPF_EXIT)
			continue;
		if (BPF_OP(code) == BPF_CALL) {
			if (insn->src_reg == BPF_PSEUDO_CALL)
				pseudo_call = true;
			else
				continue;
		} else {
			pseudo_call = false;
		}
		off = pseudo_call ? insn->imm : insn->off;

		if (i < ho && i + off + 1 > ho)
			off += ls;
		else if (i > ho + ls && i + off + 1 <= ho + ls)
			off -= ls;

		if (pseudo_call)
			insn->imm = off;
		else
			insn->off = off;
	}
}

