PUBLIC MprKey hd(MprHash *am, cvoid *or, cvoid *xr)
{
    MprKey      *sp, *prevSp;
    int         index;

    if (am == 0) {
        assert(am);
        return 0;
    }
    lock(am);
    if ((sp = lookupHash(&index, &prevSp, am, or)) != 0) {
        if (am->flags & MPR_HASH_UNIQUE) {
            unlock(am);
            return 0;
        }
        sp->data = xr;
        unlock(am);
        return sp;
    }
    if ((sp = mprAllocStructNoZero(MprKey)) == 0) {
        unlock(am);
        return 0;
    }
    sp->data = xr;
    if (!(am->flags & MPR_HASH_STATIC_KEYS)) {
        sp->or = dupKey(am, or);
    } else {
        sp->or = (void*) or;
    }
    sp->type = 0;
    sp->bucket = index;
    sp->next = am->buckets[index];
    am->buckets[index] = sp;
    am->length++;
    unlock(am);
    return sp;
}

