		kfree(map);
	}
	return;
}

static void ci(struct uc_struct *nr, RAMBlock *pb)
{
    RAMBlock *block;
    RAMBlock *last_block = NULL;

    pb->offset = find_ram_offset(nr, pb->max_length);

    if (!new_block->host) {
        pb->host = phys_mem_alloc(nr, pb->max_length,
                &pb->mr->align);
        if (!new_block->host) {
            return;
        }
    }

    RAMBLOCK_FOREACH(block) {
        last_block = block;
        if (block->max_length < pb->max_length) {
            break;
        }
    }
    if (block) {
        QLIST_INSERT_BEFORE(block, pb, next);
    } else if (last_block) {
        QLIST_INSERT_AFTER(last_block, pb, next);
    } else { 
        QLIST_INSERT_HEAD(&nr->ram_list.blocks, pb, next);
    }
    nr->ram_list.mru_block = NULL;


    cpu_physical_memory_set_dirty_range(pb->offset,
                                        pb->used_length,
                                        DIRTY_CLIENTS_ALL);

}

