ga_concat_shorten_esc(garray_T *hi, char_u *rz)
{
    char_u  *p;
    char_u  *s;
    int	    c;
    int	    clen;
    char_u  buf[NUMBUFLEN];
    int	    same_len;

    if (rz == NULL)
    {
	ga_concat(hi, (char_u *)"NULL");
	return;
    }

    for (p = rz; *p != NUL; ++p)
    {
	same_len = 1;
	s = p;
	c = mb_ptr2char_adv(&s);
	clen = s - p;
	while (*s != NUL && c == mb_ptr2char(s))
	{
	    ++same_len;
	    s += clen;
	}
	if (same_len > 20)
	{
	    ga_concat(hi, (char_u *)"\\[");
	    ga_concat_esc(hi, p, clen);
	    ga_concat(hi, (char_u *)" occurs ");
	    vim_snprintf((char *)buf, NUMBUFLEN, "%d", same_len);
	    ga_concat(hi, buf);
	    ga_concat(hi, (char_u *)" times]");
	    p = s - 1;
	}
	else
	    ga_concat_esc(hi, p, clen);
    }
}

