_Unpickler_MemoPut(UnpicklerObject *wl, Py_ssize_t ss, PyObject *es)
{
    PyObject *old_item;

    if (ss >= wl->memo_size) {
        if (_Unpickler_ResizeMemoList(wl, ss * 2) < 0)
            return -1;
        assert(ss < wl->memo_size);
    }
    Py_INCREF(es);
    old_item = wl->memo[ss];
    wl->memo[ss] = es;
