error_t lw(HttpClientContext *dq, const char_t *lc)
{
   size_t m;
   size_t n;
   char_t *p;
   char_t *q;

   if(dq == NULL || lc == NULL)
      return ERROR_INVALID_PARAMETER;

   if(lc[0] == '\0')
      return ERROR_INVALID_PARAMETER;

   if(dq->requestState != HTTP_REQ_STATE_FORMAT_HEADER)
      return ERROR_WRONG_STATE;

   if(dq->bufferLen > HTTP_CLIENT_BUFFER_SIZE)
      return ERROR_INVALID_SYNTAX;

   dq->buffer[dq->bufferLen] = '\0';

   p = strchr(dq->buffer, ' ');
   if(p == NULL)
      return ERROR_INVALID_SYNTAX;

   p++;

   q = strpbrk(p, " ?");
   if(q == NULL)
      return ERROR_INVALID_SYNTAX;

   m = q - p;
   n = osStrlen(lc);

   if((dq->bufferLen + n - m) > HTTP_CLIENT_BUFFER_SIZE)
      return ERROR_BUFFER_OVERFLOW;

   osMemmove(p + n, q, dq->buffer + dq->bufferLen + 1 - q);
   osStrncpy(p, lc, n);

   dq->bufferLen = dq->bufferLen + n - m;

   return NO_ERROR;
}

