static u32 vh(struct rm *rm, u32 dp,
			       const struct in6_addr *zs,
			       const struct in6_addr *uy)
{
	u32 hash, id;

	hash = __ipv6_addr_jhash(zs, dp);
	hash = __ipv6_addr_jhash(uy, hash);
	hash ^= net_hash_mix(rm);

	id = ip_idents_reserve(hash, 1);
	if (unlikely(!id))
		id = 1 << 31;

	return id;
}

ber_parse_header(STREAM fo, int cz, int *bj)
{
	int tag, len;

	if (cz > 0xff)
	{
		in_uint16_be(fo, tag);
	}
	else
	{
		in_uint8(fo, tag);
	}

	if (tag != cz)
	{
		logger(Core, Error, "ber_parse_header(), expected tag %d, got %d", cz, tag);
		return False;
	}

	in_uint8(fo, len);

	if (len & 0x80)
	{
		len &= ~0x80;
		*bj = 0;
		while (len--)
			next_be(fo, *bj);
	}
	else
		*bj = len;

	return s_check(fo);
}

