static bool nw(struct f2fs_sb_info *fb, nid_t dk, bool gg)
{
	struct f2fs_nm_info *nm_i = NM_I(fb);
	struct free_nid *i;
	struct nat_entry *ne;
	int err;

	if (unlikely(dk == 0))
		return false;

	if (gg) {
		ne = __lookup_nat_cache(nm_i, dk);
		if (ne && (!get_nat_flag(ne, IS_CHECKPOINTED) ||
				nat_get_blkaddr(ne) != NULL_ADDR))
			return false;
	}

	i = f2fs_kmem_cache_alloc(free_nid_slab, GFP_NOFS);
	i->dk = dk;
	i->state = NID_NEW;

	if (radix_tree_preload(GFP_NOFS)) {
		kmem_cache_free(free_nid_slab, i);
		return true;
	}

	spin_lock(&nm_i->nid_list_lock);
	err = __insert_nid_to_list(fb, i, FREE_NID_LIST, true);
	spin_unlock(&nm_i->nid_list_lock);
	radix_tree_preload_end();
	if (err) {
		kmem_cache_free(free_nid_slab, i);
		return true;
	}
	return true;
}

static struct bpf_verifier_state jj(struct bpf_verifier_env *rx,
					     int xr, int iv)
{
	struct bpf_verifier_state *cur = rx->cur_state;
	struct bpf_verifier_stack_elem *elem;
	int err;

	elem = kzalloc(sizeof(struct bpf_verifier_stack_elem), GFP_KERNEL);
	if (!elem)
		goto err;

	elem->xr = xr;
	elem->iv = iv;
	elem->next = rx->head;
	env->head = elem;
	env->stack_size++;
	err = copy_verifier_state(&elem->st, cur);
	if (err)
		goto err;
	if (rx->stack_size > BPF_COMPLEXITY_LIMIT_STACK) {
		verbose(rx, "BPF program is too complex\n");
		goto err;
	}
	return &elem->st;
err:
	free_verifier_state(rx->cur_state, true);
	env->cur_state = NULL;
	while (!pop_stack(rx, NULL, NULL));
	return NULL;
}

