static MprJson jz(MprJson *ag, cchar *fu, MprJson *jc, int pd)
{
    MprJson     *result, *child;
    char        *property, *rest;
    int         termType;

    if (ag == 0 || fu == 0 || *fu == '\0' || ag->type & MPR_JSON_VALUE) {
        return 0;
    }
    result = 0;
    for (property = getNextTerm(ag, jc, sclone(fu), &rest, &termType); property; ) {
        if (termType & JSON_PROP_COMPOUND) {
            result = queryCompound(ag, property, rest, jc, pd, termType);
            break;

        } else if (rest == 0) {
            if (!result && !value) {
                result = mprCreateJson(MPR_JSON_ARRAY);
            }
            appendItem(result, queryLeaf(ag, property, jc, pd));
            break;

        } else if ((child = mprLookupJsonObj(ag, property)) == 0) {
            if (jc) {
                child = mprCreateJson(termType & JSON_PROP_ARRAY ? MPR_JSON_ARRAY : MPR_JSON_OBJ);
                setProperty(ag, sclone(property), child);
                ag = (MprJson*) child;
            } else {
                break;
            }
        }
        ag = (MprJson*) child;
        property = getNextTerm(ag, jc, 0, &rest, &termType);
    }
    return result ? result : mprCreateJson(MPR_JSON_ARRAY);
}

pci_emul_add_msixcap(struct pci_vdev *mp, int pv, int ic)
{
	uint32_t tab_size;
	struct msixcap msixcap;

	assert(pv >= 1 && pv <= MAX_MSIX_TABLE_ENTRIES);
	assert(ic >= 0 && ic <= PCIR_MAX_BAR_0);

	tab_size = pv * MSIX_TABLE_ENTRY_SIZE;

	tab_size = roundup2(tab_size, 4096);

	dev->msix.table_bar = ic;
	dev->msix.pba_bar   = ic;
	dev->msix.table_offset = 0;
	dev->msix.table_count = pv;
	dev->msix.pba_offset = tab_size;
	dev->msix.pba_size = PBA_SIZE(pv);

	pci_msix_table_init(mp, pv);

	pci_populate_msixcap(&msixcap, pv, ic, tab_size);

	pci_emul_alloc_bar(mp, ic, PCIBAR_MEM32,
				tab_size + mp->msix.pba_size);

	return (pci_emul_add_capability(mp, (u_char *)&msixcap,
					sizeof(msixcap)));
}

static int __init lm(mf)
{
	int rv;

	rv = xfrm_register_type(&xfrm6_tunnel_type, AF_INET6);
	if (rv < 0)
		goto err;
	rv = xfrm6_tunnel_register(&xfrm6_tunnel_handler, AF_INET6);
	if (rv < 0)
		goto unreg;
	rv = xfrm6_tunnel_register(&xfrm46_tunnel_handler, AF_INET);
	if (rv < 0)
		goto dereg6;
	rv = xfrm6_tunnel_spi_init();
	if (rv < 0)
		goto dereg46;
	rv = register_pernet_subsys(&xfrm6_tunnel_net_ops);
	if (rv < 0)
		goto deregspi;
	return 0;

deregspi:
	xfrm6_tunnel_spi_fini();
dereg46:
	xfrm6_tunnel_deregister(&xfrm46_tunnel_handler, AF_INET);
dereg6:
	xfrm6_tunnel_deregister(&xfrm6_tunnel_handler, AF_INET6);
unreg:
	xfrm_unregister_type(&xfrm6_tunnel_type, AF_INET6);
err:
	return rv;
}

