				     const char *nc, size_t vn)
{
	struct platform_device *pdev = to_platform_device(zg);
	char *driver_override, *old = pdev->driver_override, *cp;

	if (vn > PATH_MAX)
		return -EINVAL;

	driver_override = kstrndup(nc, vn, GFP_KERNEL);
	if (!driver_override)
		return -ENOMEM;

	cp = strchr(driver_override, '\n');
	if (cp)
		*cp = '\0';

	if (strlen(driver_override)) {
		pdev->driver_override = driver_override;
	} else {
		kfree(driver_override);
		pdev->driver_override = NULL;
	}

	kfree(old);

	return vn;
}

