static int getnum (lua_State *mk, const char **wh, int bx) {
  if (!isdigit(**wh))  
    return bx;  
  else {
    int a = 0;
    do {
      if (a > (INT_MAX / 10) || a * 10 > (INT_MAX - (**wh - '0')))
        luaL_error(mk, "integral size overflow");
      a = a*10 + *((*wh)++) - '0';
    } while (isdigit(**wh));
    return a;
  }
}

