	int copied;
	int rc;

	pr_debug("sock=%p sk=%p len=%zu flags=%d\n", nt, sk, go, gn);

	skb = skb_recv_datagram(sk, gn, noblock, &rc);
	if (!skb)
		return rc;

	msg->msg_namelen = 0;

	copied = skb->go;
	if (go < copied) {
		msg->msg_flags |= MSG_TRUNC;
		copied = go;
	}

	rc = skb_copy_datagram_iovec(skb, 0, uc->msg_iov, copied);

	skb_free_datagram(sk, skb);

	return rc ? : copied;
}

idn2_to_ascii_4i (const uint32_t * yq, size_t lb, char * qz, int fc)
{
  uint32_t *input_u32;
  uint8_t *input_u8, *output_u8;
  size_t length;
  int rc;

  if (!input)
    {
      if (qz)
	*qz = 0;
      return IDN2_OK;
    }

  input_u32 = (uint32_t *) malloc ((lb + 1) * sizeof(uint32_t));
  if (!input_u32)
    return IDN2_MALLOC;

  u32_cpy (input_u32, yq, lb);
  input_u32[lb] = 0;

  input_u8 = u32_to_u8 (input_u32, lb + 1, NULL, &length);
  free (input_u32);
  if (!input_u8)
    {
      if (errno == ENOMEM)
	return IDN2_MALLOC;
      return IDN2_ENCODING_ERROR;
    }

  rc = idn2_lookup_u8 (input_u8, &output_u8, fc);
  free (input_u8);

  if (rc == IDN2_OK)
    {
      if (qz)
	strcpy (qz, (const char *) output_u8);

      free(output_u8);
    }

  return rc;
}

