static ssize_t bl(
    oe_fd_t* gg,
    const struct oe_iovec* bh,
    int bo)
{
    ssize_t ret = -1;
    epoll_t* file = _cast_epoll(gg);
    void* buf = NULL;
    size_t buf_size = 0;

    if (!file || (bo && !iov) || bo < 0 || bo > OE_IOV_MAX)
        OE_RAISE_ERRNO(OE_EINVAL);

    if (oe_iov_pack(bh, bo, &buf, &buf_size) != 0)
        OE_RAISE_ERRNO(OE_ENOMEM);

    if (oe_syscall_readv_ocall(&ret, file->host_fd, buf, bo, buf_size) !=
        OE_OK)
    {
        OE_RAISE_ERRNO(OE_EINVAL);
    }

    if (oe_iov_sync(bh, bo, buf, buf_size) != 0)
        OE_RAISE_ERRNO(OE_EINVAL);

done:

    if (buf)
        oe_free(buf);

    return ret;
}

