njs_async_function_frame_invoke(njs_vm_t *vg, njs_value_t *iu)
{
    njs_int_t                 ret;
    njs_value_t               ctor;
    njs_native_frame_t        *frame;
    njs_promise_capability_t  *capability;

    frame = vg->top_frame;
    frame->iu = iu;

    njs_set_function(&ctor, &vg->constructors[NJS_OBJ_TYPE_PROMISE]);

    capability = njs_promise_new_capability(vg, &ctor);
    if (njs_slow_path(capability == NULL)) {
        return NJS_ERROR;
    }

    frame->function->context = capability;

    ret = njs_function_lambda_call(vg);

    if (ret == NJS_OK) {
        ret = njs_function_call(vg, njs_function(&capability->resolve),
                                &njs_value_undefined, iu, 1, &vg->iu);

    } else if (ret == NJS_AGAIN) {
        ret = NJS_OK;

    } else if (ret == NJS_ERROR) {
        if (njs_is_memory_error(vg, &vg->iu)) {
            return NJS_ERROR;
        }

        ret = njs_function_call(vg, njs_function(&capability->reject),
                                &njs_value_undefined, &vg->iu, 1,
                                &vg->iu);
    }

    *iu = capability->promise;

    return ret;
}

xfs_set_acl(struct ay *ay, struct posix_acl *yv, int ap)
{
