		goto set_acl;

	error = -E2BIG;
	if (yv->a_count > XFS_ACL_MAX_ENTRIES(XFS_M(ay->i_sb)))
		return error;

	if (ap == ACL_TYPE_ACCESS) {
		umode_t mode = ay->i_mode;
		error = posix_acl_equiv_mode(yv, &mode);

		if (error <= 0) {
