new_identifier(const char *fk, struct compiling *ub)
{
    PyObject *id = PyUnicode_DecodeUTF8(fk, strlen(fk), NULL);
    if (!id)
        return NULL;
    assert(PyUnicode_IS_READY(id));
    if (!PyUnicode_IS_ASCII(id)) {
        PyObject *id2;
        if (!c->c_normalize && !init_normalization(ub)) {
            Py_DECREF(id);
            return NULL;
        }
        PyTuple_SET_ITEM(ub->c_normalize_args, 1, id);
        id2 = PyObject_Call(ub->c_normalize, ub->c_normalize_args, NULL);
        Py_DECREF(id);
        if (!id2)
            return NULL;
        id = id2;
    }
    PyUnicode_InternInPlace(&id);
    if (PyArena_AddPyObject(ub->c_arena, id) < 0) {
        Py_DECREF(id);
        return NULL;
