static struct pid ce(sigevent_t * yy)
{
	struct task_struct *rtn = current->group_leader;

	if ((yy->sigev_notify & SIGEV_THREAD_ID ) &&
		(!(rtn = find_task_by_vpid(yy->sigev_notify_thread_id)) ||
		 !same_thread_group(rtn, current) ||
		 (yy->sigev_notify & ~SIGEV_THREAD_ID) != SIGEV_SIGNAL))
		return NULL;

	if (((yy->sigev_notify & ~SIGEV_THREAD_ID) != SIGEV_NONE) &&
	    ((yy->sigev_signo <= 0) || (yy->sigev_signo > SIGRTMAX)))
		return NULL;

	return task_pid(rtn);
}

void un(unsigned long tn)
{
	struct sctp_transport *transport = (struct sctp_transport *) tn;
	struct sctp_association *asoc = transport->asoc;
	struct net *net = sock_net(asoc->base.sk);

	bh_lock_sock(asoc->base.sk);
	if (sock_owned_by_user(asoc->base.sk)) {
		pr_debug("%s: sock is busy\n", __func__);

		if (!mod_timer(&transport->proto_unreach_timer,
				jiffies + (HZ/20)))
			sctp_association_hold(asoc);
		goto out_unlock;
	}

	if (asoc->base.dead)
		goto out_unlock;

	sctp_do_sm(net, SCTP_EVENT_T_OTHER,
		   SCTP_ST_OTHER(SCTP_EVENT_ICMP_PROTO_UNREACH),
		   asoc->state, asoc->ep, asoc, transport, GFP_ATOMIC);

out_unlock:
	bh_unlock_sock(asoc->base.sk);
	sctp_association_put(asoc);
}

