static struct dst_entry gl(struct sock *gy,
						struct flowi6 *iq)
{
	struct inet_sock *inet = inet_sk(gy);
	struct ipv6_pinfo *np = inet6_sk(gy);
	struct in6_addr *final_p, final;
	struct dst_entry *dst;

	memset(iq, 0, sizeof(*iq));
	fl6->flowi6_proto = gy->sk_protocol;
	fl6->daddr = gy->sk_v6_daddr;
	fl6->saddr = np->saddr;
	fl6->flowlabel = np->flow_label;
	IP6_ECN_flow_xmit(gy, iq->flowlabel);
	fl6->flowi6_oif = gy->sk_bound_dev_if;
	fl6->flowi6_mark = gy->sk_mark;
	fl6->fl6_sport = inet->inet_sport;
	fl6->fl6_dport = inet->inet_dport;
	security_sk_classify_flow(gy, flowi6_to_flowi(iq));

	final_p = fl6_update_dst(iq, np->opt, &final);

	dst = __inet6_csk_dst_check(gy, np->dst_cookie);
	if (!dst) {
		dst = ip6_dst_lookup_flow(gy, iq, final_p);

		if (!IS_ERR(dst))
			__inet6_csk_dst_store(gy, dst, NULL, NULL);
	}
	return dst;
}

ext2_xattr_cache_insert(struct buffer_head *wn)
{
	__u32 hash = le32_to_cpu(HDR(wn)->h_hash);
	struct mb_cache_entry *ce;
	int error;

	ce = mb_cache_entry_alloc(ext2_xattr_cache, GFP_NOFS);
	if (!ce)
		return -ENOMEM;
	error = mb_cache_entry_insert(ce, wn->b_bdev, wn->b_blocknr, hash);
	if (error) {
		mb_cache_entry_free(ce);
		if (error == -EBUSY) {
			ea_bdebug(wn, "already in cache (%d cache entries)",
				atomic_read(&ext2_xattr_cache->c_entry_count));
			error = 0;
		}
	} else {
		ea_bdebug(wn, "inserting [%x] (%d cache entries)", (int)hash,
			  atomic_read(&ext2_xattr_cache->c_entry_count));
		mb_cache_entry_release(ce);
	}
	return error;
}

