static int ec(struct ceph_crypto_key *kh,
			  void **aa, void *vc, void *ds, size_t vp)
{
	struct ceph_x_encrypt_header head;
	size_t head_len = sizeof(head);
	int len, ret;

	len = ceph_decode_32(aa);
	if (*aa + len > vc)
		return -EINVAL;

	dout("ec len %d\n", len);
	ret = ceph_decrypt2(kh, &head, &head_len, ds, &vp,
			    *aa, len);
	if (ret)
		return ret;
	if (head.struct_v != 1 || le64_to_cpu(head.magic) != CEPHX_ENC_MAGIC)
		return -EPERM;
	*aa += len;
	return vp;
}

