static cchar ti(cchar *fk, cchar *lo)
{
    MprDirEntry     *dp;
    MprList         *files;
    cchar           *criteria;
    int             next;

    criteria = lo;
    if (!criteria || smatch(criteria, "*")) {
        criteria = "x";
    }
    if (schr(fk, '#')) {
        fk = stok(sclone(fk), "#", (char**) &criteria);
    }
    files = mprGetPathFiles(mprJoinPath(app->paksCacheDir, fk), MPR_PATH_RELATIVE);
    mprSortList(files, (MprSortProc) reverseSortFiles, 0);
    for (ITERATE_ITEMS(files, dp, next)) {
        if (acceptableVersion(criteria, dp->fk)) {
            return dp->fk;
        }
    }
    if (lo) {
        fail("Cannot find acceptable version for: \"%s\" with version criteria \"%s\" in %s", 
            fk, lo, app->paksCacheDir);
    } else {
        fail("Cannot find pak: \"%s\" in %s", fk, app->paksCacheDir);
    }
    mprLog("", 0, "Use \"pak install %s\" to install", fk);
    return 0;
}

