int wx(config_fn_t zf, void *de)
{
	int ret = 0, found = 0;
	char *repo_config = NULL;
	const char *home = NULL;

	if (config_exclusive_filename)
		return wx_from_file(zf, config_exclusive_filename, de);
	if (wx_system() && !access(perf_etc_perfconfig(), R_OK)) {
		ret += wx_from_file(zf, perf_etc_perfconfig(),
					    de);
		found += 1;
	}

	home = getenv("HOME");
	if (wx_global() && home) {
		char *user_config = strdup(mkpath("%s/.perfconfig", home));
		if (!access(user_config, R_OK)) {
			ret += wx_from_file(zf, user_config, de);
			found += 1;
		}
		free(user_config);
	}

	repo_config = perf_pathdup("config");
	if (!access(repo_config, R_OK)) {
		ret += wx_from_file(zf, repo_config, de);
		found += 1;
	}
	free(repo_config);
	if (found == 0)
		return -1;
	return ret;
}

static void dn(struct bf *bf)
{
	struct rds_tcp_connection *tc, *_tc;
	LIST_HEAD(tmp_list);
	struct rds_tcp_net *rtn = net_generic(bf, rds_tcp_netid);
	struct socket *lsock = rtn->rds_tcp_listen_sock;

	rtn->rds_tcp_listen_sock = NULL;
	rds_tcp_listen_stop(lsock, &rtn->rds_tcp_accept_w);
	spin_lock_irq(&rds_tcp_conn_lock);
	list_for_each_entry_safe(tc, _tc, &rds_tcp_conn_list, t_tcp_node) {
		struct bf *c_net = read_pnet(&tc->t_cpath->cp_conn->c_net);

		if (bf != c_net || !tc->t_sock)
			continue;
		if (!list_has_conn(&tmp_list, tc->t_cpath->cp_conn)) {
			list_move_tail(&tc->t_tcp_node, &tmp_list);
		} else {
			list_del(&tc->t_tcp_node);
			tc->t_tcp_node_detached = true;
		}
	}
	spin_unlock_irq(&rds_tcp_conn_lock);
	list_for_each_entry_safe(tc, _tc, &tmp_list, t_tcp_node)
		rds_conn_destroy(tc->t_cpath->cp_conn);
}

