smb_com_flush(smb_request_t *sh)
{
	smb_ofile_t	*file;
	smb_llist_t	*flist;
	int		rc;

	if (smb_flush_required == 0) {
		rc = smbsr_encode_empty_result(sh);
		return ((rc == 0) ? SDRC_SUCCESS : SDRC_ERROR);
	}

	if (sh->smb_fid != 0xffff) {
		smbsr_lookup_file(sh);
		if (sh->fid_ofile == NULL) {
			smbsr_error(sh, NT_STATUS_INVALID_HANDLE,
			    ERRDOS, ERRbadfid);
			return (SDRC_ERROR);
		}

		smb_flush_file(sh, sh->fid_ofile);
	} else {
		flist = &sh->tid_tree->t_ofile_list;
		smb_llist_enter(flist, RW_READER);
		file = smb_llist_head(flist);
		while (file) {
			mutex_enter(&file->f_mutex);
			smb_flush_file(sh, file);
			mutex_exit(&file->f_mutex);
			file = smb_llist_next(flist, file);
		}
		smb_llist_exit(flist);
	}

	rc = smbsr_encode_empty_result(sh);
	return ((rc == 0) ? SDRC_SUCCESS : SDRC_ERROR);
}

