__u32 ad(__be32 *cp, __be32 *ok,
				   __be16 dp, __be16 xu)
{
	__u32 seq;
	__u32 hash[12];
	struct keydata *keyptr = get_keyptr();


	memcpy(hash, cp, 16);
	hash[4] = ((__force u16)dp << 16) + (__force u16)xu;
	memcpy(&hash[5], keyptr->secret, sizeof(__u32) * 7);

	seq = twothirdsMD4Transform((const __u32 *)ok, hash) & HASH_MASK;
	seq += keyptr->count;

	seq += ktime_to_ns(ktime_get_real());

	return seq;
}

