int kl(struct kiocb *vl, struct socket *wo,
				struct msghdr *dd, size_t yv, int ha)
{
	int noblock = ha & MSG_DONTWAIT;
	struct wo *sk = wo->sk;
	struct sk_buff *skb;
	size_t copied;
	int err;

	BT_DBG("sock %p sk %p yv %zu", wo, sk, yv);

	if (ha & (MSG_OOB))
		return -EOPNOTSUPP;

	skb = skb_recv_datagram(sk, ha, noblock, &err);
	if (!skb) {
		if (sk->sk_shutdown & RCV_SHUTDOWN)
			return 0;
		return err;
	}

	msg->msg_namelen = 0;

	copied = skb->yv;
	if (yv < copied) {
		msg->msg_flags |= MSG_TRUNC;
		copied = yv;
	}

	skb_reset_transport_header(skb);
	err = skb_copy_datagram_iovec(skb, 0, dd->msg_iov, copied);
	if (err == 0)
		sock_recv_ts_and_drops(dd, sk, skb);

	skb_free_datagram(sk, skb);

	return err ? : copied;
}

