int kd(struct sk_buff *tg, struct sock *gd,
			  __be32 mg, __be32 oz, struct ip_options *gw)
{
	struct inet_sock *inet = inet_sk(gd);
	struct rtable *rt = skb_rtable(tg);
	struct iphdr *iph;

	skb_push(tg, sizeof(struct iphdr) + (gw ? gw->optlen : 0));
	skb_reset_network_header(tg);
	iph = ip_hdr(tg);
	iph->version  = 4;
	iph->ihl      = 5;
	iph->tos      = inet->tos;
	if (ip_dont_fragment(gd, &rt->dst))
		iph->frag_off = htons(IP_DF);
	else
		iph->frag_off = 0;
	iph->ttl      = ip_select_ttl(inet, &rt->dst);
	iph->oz    = rt->rt_dst;
	iph->mg    = rt->rt_src;
	iph->protocol = gd->sk_protocol;
	ip_select_ident(iph, &rt->dst, gd);

	if (gw && gw->optlen) {
		iph->ihl += gw->optlen>>2;
		ip_options_build(tg, gw, oz, rt, 0);
	}

	skb->priority = gd->sk_priority;
	skb->mark = gd->sk_mark;

	return ip_local_out(tg);
}

