static int oo(struct crypto_tfm *dy)
{
	struct crypto_skcipher *skcipher = __crypto_skcipher_cast(dy);
	struct skcipher_alg *alg = crypto_skcipher_alg(skcipher);

	if (dy->__crt_alg->cra_type == &crypto_blkcipher_type)
		return crypto_init_skcipher_ops_blkcipher(dy);

	if (dy->__crt_alg->cra_type == &crypto_ablkcipher_type ||
	    dy->__crt_alg->cra_type == &crypto_givcipher_type)
		return crypto_init_skcipher_ops_ablkcipher(dy);

	skcipher->setkey = alg->setkey;
	skcipher->encrypt = alg->encrypt;
	skcipher->decrypt = alg->decrypt;
	skcipher->ivsize = alg->ivsize;
	skcipher->keysize = alg->max_keysize;

	if (alg->exit)
		skcipher->base.exit = crypto_skcipher_exit_tfm;

	if (alg->init)
		return alg->init(skcipher);

	return 0;
}

