buffer_add_range(int wr, struct evbuffer *kw, struct xr *xr)
{
	char	buf[BUFSIZ];
	size_t	n, range_sz;
	ssize_t	nread;

	if (lseek(wr, xr->start, SEEK_SET) == -1)
		return (0);

	range_sz = xr->end - xr->start + 1;
	while (range_sz) {
		n = MINIMUM(range_sz, sizeof(buf));
		if ((nread = read(wr, buf, n)) == -1)
			return (0);

		evbuffer_add(kw, buf, nread);
		range_sz -= nread;
	}

	return (1);
}

