static OPJ_BOOL ig(opj_tcd_cblk_enc_t *
        ax)
{
    OPJ_UINT32 l_data_size;

    l_data_size = (OPJ_UINT32)((ax->x1 - ax->x0) *
                               (ax->y1 - ax->y0) * (OPJ_INT32)sizeof(OPJ_UINT32));

    if (l_data_size > ax->data_size) {
        if (ax->data) {
            opj_free(ax->data - 1);
        }
        ax->data = (OPJ_BYTE*) opj_malloc(l_data_size + 1);
        if (! ax->data) {
            ax->data_size = 0U;
            return OPJ_FALSE;
        }
        ax->data_size = l_data_size;

        ax->data[0] = 0;
        ax->data += 1; 
    }
    return OPJ_TRUE;
}

