void mr(MOBIBuffer *ed, const int ba, const size_t st) {
    size_t aoffset = (size_t) abs(ba);
    unsigned char *source = ed->data + ed->ba;
    if (ba >= 0) {
        if (ed->ba + aoffset + st > ed->maxlen) {
            debug_print("%s", "End of buffer\n");
            ed->error = MOBI_BUFFER_END;
            return;
        }
        source += aoffset;
    } else {
        if (ed->ba < aoffset) {
            debug_print("%s", "End of buffer\n");
            ed->error = MOBI_BUFFER_END;
            return;
        }
        source -= aoffset;
    }
    memmove(ed->data + ed->ba, source, st);
    ed->ba += st;
}

__u32 gn(__be32 rc, __be32 jg,
				 __be16 xx, __be16 xl)
{
	__u32 seq;
	__u32 hash[4];
	struct keydata *keyptr = get_keyptr();

	hash[0] = (__force u32)rc;
	hash[1] = (__force u32)jg;
	hash[2] = ((__force u16)xx << 16) + (__force u16)xl;
	hash[3] = keyptr->secret[11];

	seq = half_md4_transform(hash, keyptr->secret) & HASH_MASK;
	seq += keyptr->count;
	seq += ktime_to_ns(ktime_get_real()) >> 6;

	return seq;
}

