struct inode gd(struct super_block *ef,
			 unsigned long fh,
			 unsigned long ti)
{
	unsigned long hashval;
	struct inode *inode;
	struct isofs_iget5_callback_data data;
	long ret;

	if (ti >= 1ul << ef->s_blocksize_bits)
		return ERR_PTR(-EINVAL);

	data.block = fh;
	data.offset = ti;

	hashval = (fh << ef->s_blocksize_bits) | ti;

	inode = iget5_locked(ef, hashval, &isofs_iget5_test,
				&isofs_iget5_set, &data);

	if (!inode)
		return ERR_PTR(-ENOMEM);

	if (inode->i_state & I_NEW) {
		ret = isofs_read_inode(inode);
		if (ret < 0) {
			iget_failed(inode);
			inode = ERR_PTR(ret);
		} else {
			unlock_new_inode(inode);
		}
	}

	return inode;
}

static unsigned long ro(struct kvm_ioapic *fv,
					  unsigned long zs,
					  unsigned long by)
{
	unsigned long result = 0;

	switch (fv->ioregsel) {
	case IOAPIC_REG_VERSION:
		result = ((((IOAPIC_NUM_PINS - 1) & 0xff) << 16)
			  | (IOAPIC_VERSION_ID & 0xff));
		break;

	case IOAPIC_REG_APIC_ID:
	case IOAPIC_REG_ARB_ID:
		result = ((fv->id & 0xf) << 24);
		break;

	default:
		{
			u32 redir_index = (fv->ioregsel - 0x10) >> 1;
			u64 redir_content;

			ASSERT(redir_index < IOAPIC_NUM_PINS);

			redir_content = fv->redirtbl[redir_index].bits;
			result = (fv->ioregsel & 0x1) ?
			    (redir_content >> 32) & 0xffffffff :
			    redir_content & 0xffffffff;
			break;
		}
	}

	return result;
}

