static int ev(hashtable_t *gx,
                            const char *sp, size_t kl)
{
    pair_t *pair;
    bucket_t *bucket;
    size_t index;

    index = kl % num_buckets(gx);
    bucket = &gx->buckets[index];

    pair = hashtable_find_pair(gx, bucket, sp, kl);
    if(!pair)
        return -1;

    if(&pair->list == bucket->first && &pair->list == bucket->last)
        bucket->first = bucket->last = &gx->list;

    else if(&pair->list == bucket->first)
        bucket->first = pair->list.next;

    else if(&pair->list == bucket->last)
        bucket->last = pair->list.prev;

    list_remove(&pair->list);
    json_decref(pair->value);

    jsonp_free(pair);
    gx->size--;

    return 0;
}

