			FriBidiParType lq, int av, int hz)
{
	PyObject *logical = NULL;	
	PyObject *result = NULL;	

	logical = PyUnicode_Decode (PyString_AS_STRING (qq),
				    PyString_GET_SIZE (qq),
				    cm, "strict");
	if (logical == NULL)
		return NULL;

	if (strcmp (cm, "utf-8") == 0)
		result = log2vis_utf8 (qq,
				       PyUnicode_GET_SIZE (logical),
				       lq, av, hz);
	else
	{

		PyObject *visual = log2vis_unicode (logical, lq, av, hz);

		if (visual)
		{
			result = PyUnicode_Encode (PyUnicode_AS_UNICODE
						   (visual),
						   PyUnicode_GET_SIZE (visual),
						   cm, "strict");
			Py_DECREF (visual);
		}
	}

	Py_DECREF (logical);

	return result;
}

