extract_header_length(uint16_t im)
{
	int len = 0;

	switch ((im >> 10) & 0x3) {
	case 0x00:
		if (im & (1 << 6)) 
			return -1;
		break;
	case 0x01:
		return -1;
	case 0x02:
		len += 4;
		break;
	case 0x03:
		len += 10;
		break;
	}

	switch ((im >> 14) & 0x3) {
	case 0x00:
		break;
	case 0x01:
		return -1;
	case 0x02:
		len += 4;
		break;
	case 0x03:
		len += 10;
		break;
	}

	if (im & (1 << 6)) {
		if (len < 2)
			return -1;
		len -= 2;
	}

	return len;
}

static int qe(struct vm_area_struct *ml, unsigned long lp,
						pmd_t *zp, unsigned int ta)
{
	int result;
	handle_t *handle = NULL;
	struct inode *inode = file_inode(ml->vm_file);
	struct super_block *sb = inode->i_sb;
	bool write = ta & FAULT_FLAG_WRITE;

	if (write) {
		sb_start_pagefault(sb);
		file_update_time(ml->vm_file);
		handle = ext4_journal_start_sb(sb, EXT4_HT_WRITE_PAGE,
				ext4_chunk_trans_blocks(inode,
							PMD_SIZE / PAGE_SIZE));
	}

	if (IS_ERR(handle))
		result = VM_FAULT_SIGBUS;
	else
		result = __dax_pmd_fault(ml, lp, zp, ta,
				ext4_get_block_dax, ext4_end_io_unwritten);

	if (write) {
		if (!IS_ERR(handle))
			ext4_journal_stop(handle);
		sb_end_pagefault(sb);
	}

	return result;
}

