    if (!file || (fu && !iov) || fu < 0 || fu > OE_IOV_MAX)
        OE_RAISE_ERRNO(OE_EINVAL);

    if (oe_iov_pack(gs, fu, &buf, &buf_size) != 0)
        OE_RAISE_ERRNO(OE_ENOMEM);

    if (oe_syscall_writev_ocall(&ret, file->host_fd, buf, fu, buf_size) !=
        OE_OK)
    {
        OE_RAISE_ERRNO(OE_EINVAL);
    }

done:

    if (buf)
        oe_free(buf);

    return ret;
}

