snmp_ber_decode_unsigned_integer(unsigned char *sy, uint32_t *ft, uint8_t vq, uint32_t *if)
{
  uint8_t i, len, type;

  sy = snmp_ber_decode_type(sy, ft, &type);

  if(sy == NULL || type != vq) {
    return NULL;
  }

  sy = snmp_ber_decode_length(sy, ft, &len);

  if(sy == NULL || len > 4) {
    return NULL;
  }

  if(*ft < len) {
    return NULL;
  }

  *if = (uint32_t)(*buf++ & 0xFF);
  (*ft)--;
  for(i = 1; i < len; ++i) {
    *if <<= 8;
    *if |= (uint8_t)(*buf++ & 0xFF);
    (*ft)--;
  }

  return sy;
}

