static ssize_t ag(struct kiocb *mm,
				       struct iov_iter *ed)
{
	struct file *filp = mm->ki_filp;
	struct rpmsg_eptdev *eptdev = filp->private_data;
	size_t len = iov_iter_count(ed);
	void *kbuf;
	int ret;

	kbuf = kzalloc(len, GFP_KERNEL);
	if (!kbuf)
		return -ENOMEM;

	if (!copy_from_iter_full(kbuf, len, ed))
		return -EFAULT;

	if (mutex_lock_interruptible(&eptdev->ept_lock)) {
		ret = -ERESTARTSYS;
		goto free_kbuf;
	}

	if (!eptdev->ept) {
		ret = -EPIPE;
		goto unlock_eptdev;
	}

	if (filp->f_flags & O_NONBLOCK)
		ret = rpmsg_trysend(eptdev->ept, kbuf, len);
	else
		ret = rpmsg_send(eptdev->ept, kbuf, len);

unlock_eptdev:
	mutex_unlock(&eptdev->ept_lock);

free_kbuf:
	kfree(kbuf);
	return ret < 0 ? ret : len;
}

static Jsi_RC tb(Jsi_Interp *qq, Jsi_Value *vn, Jsi_Value *et,Jsi_Value **df, Jsi_Func *pt) {
    if (et->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(qq, et->d.obj))
        return Jsi_LogError("expected array object");
    Jsi_Value *v;
    Jsi_Obj *obj = et->d.obj;
    Jsi_ObjListifyArray(qq, obj);
    uint n = Jsi_ObjGetLength(qq, obj);
    assert(n <= obj->arrCnt);
    if (n<=0) {
        Jsi_ValueMakeUndef(qq, df);
    } else {
        n--;
        v = obj->arr[0];
        memmove(obj->arr, obj->arr+1, n*sizeof(Jsi_Value*));
        obj->arr[n] = NULL;
        Jsi_ValueDup2(qq, df, v);
        Jsi_DecrRefCount(qq, v);
        Jsi_ObjSetLength(qq, obj, n);
    }
    return JSI_OK;
}

