{
    identifier name;
    expr_ty annotation = NULL;
    node *ch;
    arg_ty ret;

    assert(TYPE(oz) == tfpdef || TYPE(oz) == vfpdef);
    ch = CHILD(oz, 0);
    name = NEW_IDENTIFIER(ch);
    if (!name)
        return NULL;
    if (forbidden_name(xh, name, ch, 0))
        return NULL;

    if (NCH(oz) == 3 && TYPE(CHILD(oz, 1)) == COLON) {
        annotation = ast_for_expr(xh, CHILD(oz, 2));
        if (!annotation)
            return NULL;
