bool_t ag(XDR *fu, char **po)
{
     u_int size;

     if (fu->x_op == XDR_ENCODE) {
	  if (*po == NULL)
	       size = 0;
	  else
	       size = strlen(*po) + 1;
     }
     if (! xdr_u_int(fu, &size)) {
	  return FALSE;
	}
     switch (fu->x_op) {
     case XDR_DECODE:
	  if (size == 0) {
	       *po = NULL;
	       return TRUE;
	  } else if (*po == NULL) {
	       *po = (char *) mem_alloc(size);
	       if (*po == NULL) {
		    errno = ENOMEM;
		    return FALSE;
	       }
	  }
	  return (xdr_opaque(fu, *po, size));

     case XDR_ENCODE:
	  if (size != 0)
	       return (xdr_opaque(fu, *po, size));
	  return TRUE;

     case XDR_FREE:
	  if (*po != NULL)
	       mem_free(*po, size);
	  *po = NULL;
	  return TRUE;
     }

     return FALSE;
}

