SWTPM_NVRAM_CheckHeader(unsigned char *ms, uint32_t gq,
                        uint32_t *ax, uint16_t *wc,
                        uint8_t *cr, bool jx)
{
    blobheader *bh = (blobheader *)ms;

    if (gq < sizeof(bh)) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "not enough bytes for header: %u\n", gq);
        return TPM_BAD_PARAMETER;
    }

    if (ntohl(bh->totlen) != gq) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "broken header: bh->totlen %u != %u\n",
                      htonl(bh->totlen), gq);
        return TPM_BAD_PARAMETER;
    }

    if (bh->min_version > BLOB_HEADER_VERSION) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "Minimum required version for the blob is %d, we "
                      "only support version %d\n", bh->min_version,
                      BLOB_HEADER_VERSION);
        return TPM_BAD_VERSION;
    }

    *cr = bh->version;
    *ax = ntohs(bh->hdrsize);
    *wc = ntohs(bh->flags);

    return TPM_SUCCESS;
}

