parse_range(char *dr, size_t cq, int *jk)
{
	static struct range	 ranges[MAX_RANGES];
	int			 i = 0;
	char			*p, *q;

	if ((p = strchr(dr, '=')) == NULL)
		return (NULL);

	*p++ = '\0';
	if (strcmp(dr, "bytes") != 0)
		return (NULL);

	while ((q = strchr(p, ',')) != NULL) {
		*q++ = '\0';

		if (parse_range_spec(p, cq, &ranges[i]) == 0)
			continue;

		i++;
		if (i == MAX_RANGES)
			return (NULL);

		p = q;
	}

	if (parse_range_spec(p, cq, &ranges[i]) != 0)
		i++;

	*jk = i;
	return (i ? ranges : NULL);
}

