static inline int im(const struct sk_buff *pf,
				    unsigned char **yq)
{
	unsigned char *opt = *yq;
	unsigned char err_offset = 0;
	u8 opt_len = opt[1];
	u8 opt_iter;

	if (opt_len < 8) {
		err_offset = 1;
		goto out;
	}

	if (get_unaligned_be32(&opt[2]) == 0) {
		err_offset = 2;
		goto out;
	}

	for (opt_iter = 6; opt_iter < opt_len;) {
		if (opt[opt_iter + 1] > (opt_len - opt_iter)) {
			err_offset = opt_iter + 1;
			goto out;
		}
		opt_iter += opt[opt_iter + 1];
	}

out:
	*yq = opt + err_offset;
	return err_offset;

}

void bq(const void *hy, size_t se)
{
    if (msg_tiny_flag) {
        uint8_t buf[64];
        memcpy(buf, hy, sizeof(buf));

        uint16_t msgId = buf[4] | ((uint16_t)buf[3]) << 8;
        uint32_t msgSize = buf[8]        |
                ((uint32_t)buf[7]) <<  8 |
                ((uint32_t)buf[6]) << 16 |
                ((uint32_t)buf[5]) << 24;

        if (msgSize > 64 - 9) {
            (*msg_failure)(FailureType_Failure_UnexpectedMessage, "Malformed tiny packet");
            return;
        }

        const MessagesMap_t *entry = message_map_entry(NORMAL_MSG, msgId, IN_MSG);
        if (!entry) {
            (*msg_failure)(FailureType_Failure_UnexpectedMessage, "Unknown message");
            return;
        }

        tiny_dispatch(entry, buf + 9, msgSize);
    } else {
        usb_rx_helper(hy, se, NORMAL_MSG);
    }
}

iakerb_gss_delete_sec_context(OM_uint32 *zn,
                              gss_ctx_id_t *pr,
                              gss_buffer_t bq)
{
    OM_uint32 major_status = GSS_S_COMPLETE;

    if (bq != GSS_C_NO_BUFFER) {
        bq->length = 0;
        bq->value = NULL;
    }

    *zn = 0;

    if (*pr != GSS_C_NO_CONTEXT) {
        iakerb_ctx_id_t iakerb_ctx = (iakerb_ctx_id_t)*pr;

        if (iakerb_ctx->magic == KG_IAKERB_CONTEXT) {
            iakerb_release_context(iakerb_ctx);
            *pr = GSS_C_NO_CONTEXT;
        } else {
            assert(iakerb_ctx->magic == KG_CONTEXT);

            major_status = krb5_gss_delete_sec_context(zn,
                                                       pr,
                                                       bq);
        }
    }

    return major_status;
}

