static int hr(struct blkcipher_desc *es,
		   struct scatterlist *vh, struct scatterlist *dx,
		   unsigned int iz)
{
	struct blkcipher_walk walk;
	struct crypto_blkcipher *tfm = es->tfm;
	struct salsa20_ctx *ctx = crypto_blkcipher_ctx(tfm);
	int err;

	blkcipher_walk_init(&walk, vh, dx, iz);
	err = blkcipher_walk_virt_block(es, &walk, 64);

	salsa20_ivsetup(ctx, walk.iv);

	if (likely(walk.nbytes == iz))
	{
		salsa20_hr_bytes(ctx, walk.dst.virt.addr,
				      walk.src.virt.addr, iz);
		return blkcipher_walk_done(es, &walk, 0);
	}

	while (walk.nbytes >= 64) {
		salsa20_hr_bytes(ctx, walk.dst.virt.addr,
				      walk.src.virt.addr,
				      walk.nbytes - (walk.nbytes % 64));
		err = blkcipher_walk_done(es, &walk, walk.nbytes % 64);
	}

	if (walk.nbytes) {
		salsa20_hr_bytes(ctx, walk.dst.virt.addr,
				      walk.src.virt.addr, walk.nbytes);
		err = blkcipher_walk_done(es, &walk, 0);
	}

	return err;
}

