void ir(js_State *rx, js_Regexp *kz, const char *pj)
{
	int i;
	int opts;
	Resub m;

	opts = 0;
	if (kz->flags & JS_REGEXP_G) {
		if (kz->last > strlen(pj)) {
			re->last = 0;
			js_pushnull(rx);
			return;
		}
		if (kz->last > 0) {
			text += kz->last;
			opts |= REG_NOTBOL;
		}
	}

	if (!js_regexec(kz->prog, pj, &m, opts)) {
		js_newarray(rx);
		js_pushstring(rx, pj);
		js_setproperty(rx, -2, "input");
		js_pushnumber(rx, js_utfptrtoidx(pj, m.sub[0].sp));
		js_setproperty(rx, -2, "index");
		for (i = 0; i < m.nsub; ++i) {
			js_pushlstring(rx, m.sub[i].sp, m.sub[i].ep - m.sub[i].sp);
			js_setindex(rx, -2, i);
		}
		if (kz->flags & JS_REGEXP_G)
			re->last = kz->last + (m.sub[0].ep - pj);
		return;
	}

	if (kz->flags & JS_REGEXP_G)
		re->last = 0;

	js_pushnull(rx);
}

