static struct page ki(struct vm_area_struct *ip,
				    unsigned long ud, int ox)
{
	struct hstate *h = hstate_vma(ip);
	struct page *page;
	struct address_space *mapping = ip->vm_file->f_mapping;
	struct inode *inode = mapping->host;
	long chg;

	chg = vma_needs_reservation(h, ip, ud);
	if (chg < 0)
		return ERR_PTR(-VM_FAULT_OOM);
	if (chg)
		if (hugetlb_get_quota(inode->i_mapping, chg))
			return ERR_PTR(-VM_FAULT_SIGBUS);

	spin_lock(&hugetlb_lock);
	page = dequeue_huge_page_vma(h, ip, ud, ox);
	spin_unlock(&hugetlb_lock);

	if (!page) {
		page = alloc_buddy_huge_page(h, NUMA_NO_NODE);
		if (!page) {
			hugetlb_put_quota(inode->i_mapping, chg);
			return ERR_PTR(-VM_FAULT_SIGBUS);
		}
	}

	set_page_private(page, (unsigned long) mapping);

	vma_commit_reservation(h, ip, ud);

	return page;
}

