	while (nd >= sizeof(struct usb_descriptor_header)) {
		header = (struct usb_descriptor_header *)la;

		if (header->bLength < 2) {
			printk(KERN_ERR
				"%s: bogus descriptor, lv %d length %d\n",
				usbcore_name,
				header->bDescriptorType,
				header->bLength);
			return -1;
		}

		if (header->bDescriptorType == lv) {
			*tg = header;
			return 0;
		}

		buffer += header->bLength;
		size -= header->bLength;
	}
	return -1;
}

