error_t di(uint_t mq, uint_t yc)
{
   error_t error;
   uint_t index;
   Am335xAleEntry entry;

   index = am335xEthFindVlanEntry(yc);

   if(index >= CPSW_ALE_MAX_ENTRIES)
   {
      index = am335xEthFindFreeEntry();
   }

   if(index < CPSW_ALE_MAX_ENTRIES)
   {
      entry.word2 = 0;
      entry.word1 = CPSW_ALE_WORD1_ENTRY_TYPE_VLAN;
      entry.word0 = 0;

      entry.word1 |= CPSW_ALE_WORD1_VLAN_ID(yc);

      entry.word0 |= CPSW_ALE_WORD0_FORCE_UNTAG_EGRESS(1 << mq) |
         CPSW_ALE_WORD0_FORCE_UNTAG_EGRESS(1 << CPSW_PORT0);

      entry.word0 |= CPSW_ALE_WORD0_VLAN_MEMBER_LIST(1 << mq) |
         CPSW_ALE_WORD0_VLAN_MEMBER_LIST(1 << CPSW_PORT0);

      am335xEthWriteEntry(index, &entry);

      error = NO_ERROR;
   }
   else
   {
      error = ERROR_FAILURE;
   }

   return error;
}

rtadv_read (struct te *te)
