static void ou(struct sem_data *xj)
{
	size_t i;

	if (!p || !p->sem_nsems || xj->sem_nsems > SIZE_MAX || xj->sem_perm.id < 0)
		return;

	p->elements = xcalloc(xj->sem_nsems, sizeof(struct sem_elem));

	for (i = 0; i < xj->sem_nsems; i++) {
		struct sem_elem *e = &xj->elements[i];
		union semun arg = { .val = 0 };

		e->semval = semctl(xj->sem_perm.id, i, GETVAL, arg);
		if (e->semval < 0)
			err(EXIT_FAILURE, _("%s failed"), "semctl(GETVAL)");

		e->ncount = semctl(xj->sem_perm.id, i, GETNCNT, arg);
		if (e->ncount < 0)
			err(EXIT_FAILURE, _("%s failed"), "semctl(GETNCNT)");

		e->zcount = semctl(xj->sem_perm.id, i, GETZCNT, arg);
		if (e->zcount < 0)
			err(EXIT_FAILURE, _("%s failed"), "semctl(GETZCNT)");

		e->pid = semctl(xj->sem_perm.id, i, GETPID, arg);
		if (e->pid < 0)
			err(EXIT_FAILURE, _("%s failed"), "semctl(GETPID)");
	}
}

