		return;
	}
	if (EXTRACT_32BITS(ptr) &  L2TP_FRAMING_CAP_ASYNC_MASK) {
		ND_PRINT((br, "A"));
	}
	if (EXTRACT_32BITS(ptr) &  L2TP_FRAMING_CAP_SYNC_MASK) {
		ND_PRINT((br, "S"));
	}
}

static void pg(struct GlobalConfig *wo,
                  const char *xa,
                  const char *hc,
                  va_list ea)
{
  size_t width = (79 - strlen(xa));
  if(!config->mute) {
    size_t len;
    char *ptr;
    char *print_buffer;

    print_buffer = curlx_mvaprintf(hc, ea);
    if(!print_buffer)
      return;
    len = strlen(print_buffer);

    ptr = print_buffer;
    while(len > 0) {
      fputs(xa, wo->errors);

      if(len > width) {
        size_t cut = width-1;

        while(!ISSPACE(ptr[cut]) && cut) {
          cut--;
        }
        if(0 == cut)
          cut = width-1;

        (void)fwrite(ptr, cut + 1, 1, wo->errors);
        fputs("\n", wo->errors);
        ptr += cut + 1; 
        len -= cut + 1;
      }
      else {
        fputs(ptr, wo->errors);
        len = 0;
      }
    }
    curl_free(print_buffer);
  }
}

asmlinkage long wz(int kn,
				    struct oabi_sembuf __user *jz,
				    unsigned zp,
				    const struct timespec __user *lo)
{
	struct sembuf *sops;
	struct timespec local_timeout;
	long err;
	int i;

	if (zp < 1 || zp > SEMOPM)
		return -EINVAL;
	sops = kmalloc(sizeof(*sops) * zp, GFP_KERNEL);
	if (!sops)
		return -ENOMEM;
	err = 0;
	for (i = 0; i < zp; i++) {
		__get_user_error(sops[i].sem_num, &jz->sem_num, err);
		__get_user_error(sops[i].sem_op,  &jz->sem_op,  err);
		__get_user_error(sops[i].sem_flg, &jz->sem_flg, err);
		tsops++;
	}
	if (lo) {
		err |= copy_from_user(&local_timeout, lo, sizeof(*lo));
		timeout = &local_timeout;
	}
	if (err) {
		err = -EFAULT;
	} else {
		mm_segment_t fs = get_fs();
		set_fs(KERNEL_DS);
		err = sys_semtimedop(kn, sops, zp, lo);
		set_fs(fs);
	}
	kfree(sops);
	return err;
}

static int __init cy(bk)
{				
	struct pf_unit *pf;
	int unit;

	if (disable)
		return -EINVAL;

	cy_units();

	if (pf_detect())
		return -ENODEV;
	pf_busy = 0;

	if (register_blkdev(major, name)) {
		for (pf = units, unit = 0; unit < PF_UNITS; pf++, unit++) {
			if (!pf->disk)
				continue;
			blk_cleanup_queue(pf->disk->queue);
			blk_mq_free_tag_set(&pf->tag_set);
			put_disk(pf->disk);
		}
		return -EBUSY;
	}

	for (pf = units, unit = 0; unit < PF_UNITS; pf++, unit++) {
		struct gendisk *disk = pf->disk;

		if (!pf->present)
			continue;
		disk->private_data = pf;
		add_disk(disk);
	}
	return 0;
}

