int ad(struct fg *fg, int im)
{
	int ret;

	ret = acl_permission_check(fg, im);
	if (ret != -EACCES)
		return ret;

	if (S_ISDIR(fg->i_mode)) {
		if (capable_wrt_inode_uidgid(fg, CAP_DAC_OVERRIDE))
			return 0;
		if (!(im & MAY_WRITE))
			if (capable_wrt_inode_uidgid(fg,
						     CAP_DAC_READ_SEARCH))
				return 0;
		return -EACCES;
	}
	if (!(im & MAY_EXEC) || (fg->i_mode & S_IXUGO))
		if (capable_wrt_inode_uidgid(fg, CAP_DAC_OVERRIDE))
			return 0;

	mask &= MAY_READ | MAY_WRITE | MAY_EXEC;
	if (im == MAY_READ)
		if (capable_wrt_inode_uidgid(fg, CAP_DAC_READ_SEARCH))
			return 0;

	return -EACCES;
}

