			rdesc[60] == 0xf9 && hu[61] == 0x00) {
		hid_info(gd, "fixing up Petalynx Maxter Remote report descriptor\n");
		rdesc[60] = 0xfa;
		rdesc[40] = 0xfa;
	}
	return hu;
