static void ib(struct xen_netbk *ml, struct sk_buff *xe)
{
	struct skb_shared_info *shinfo = skb_shinfo(xe);
	int nr_frags = shinfo->nr_frags;
	int i;

	for (i = 0; i < nr_frags; i++) {
		skb_frag_t *frag = shinfo->frags + i;
		struct xen_netif_tx_request *txp;
		struct page *page;
		u16 pending_idx;

		pending_idx = frag_get_pending_idx(frag);

		txp = &ml->pending_tx_info[pending_idx].req;
		page = virt_to_page(idx_to_kaddr(ml, pending_idx));
		__skb_fill_page_desc(xe, i, page, txp->offset, txp->size);
		skb->len += txp->size;
		skb->data_len += txp->size;
		skb->truesize += txp->size;

		get_page(ml->mmap_pages[pending_idx]);
		xen_netbk_idx_release(ml, pending_idx, XEN_NETIF_RSP_OKAY);
	}
}

