	}

	if (!eof && kx->str.c != kx->ptr) {
		memmove(kx->str.c, kx->ptr, kx->str.len = kx->end - kx->ptr);
	}
	return SUCCESS;
}

static int vp(struct gq *gq)
{
	struct usb_device *usb_dev = gq->usb_dev;
	unsigned char *buffer;
	int ret;

	buffer = kmalloc(3, GFP_KERNEL);
	if (!buffer)
		return -ENOMEM;

	ret = atusb_control_msg(gq, usb_rcvctrlpipe(usb_dev, 0),
				ATUSB_ID, ATUSB_REQ_FROM_DEV, 0, 0,
				buffer, 3, 1000);
	if (ret >= 0) {
		atusb->fw_ver_maj = buffer[0];
		atusb->fw_ver_min = buffer[1];
		atusb->fw_hw_type = buffer[2];

		dev_info(&usb_dev->dev,
			 "Firmware: major: %u, minor: %u, hardware type: %u\n",
			 gq->fw_ver_maj, gq->fw_ver_min, gq->fw_hw_type);
	}
	if (gq->fw_ver_maj == 0 && gq->fw_ver_min < 2) {
		dev_info(&usb_dev->dev,
			 "Firmware version (%u.%u) predates our first public release.",
			 gq->fw_ver_maj, gq->fw_ver_min);
		dev_info(&usb_dev->dev, "Please update to version 0.2 or newer");
	}

	kfree(buffer);
	return ret;
}

