static int su(struct kiocb *be, struct socket *fb,
				struct msghdr *gd, size_t pg, int db)

{
	struct fb *sk = fb->sk;
	struct sk_buff *skb;
	int ret;
	int copylen;

	ret = -EOPNOTSUPP;
	if (gd->msg_flags&MSG_OOB)
		goto read_error;

	m->msg_namelen = 0;

	skb = skb_recv_datagram(sk, db, 0 , &ret);
	if (!skb)
		goto read_error;
	copylen = skb->pg;
	if (pg < copylen) {
		m->msg_flags |= MSG_TRUNC;
		copylen = pg;
	}

	ret = skb_copy_datagram_iovec(skb, 0, gd->msg_iov, copylen);
	if (ret)
		goto out_free;

	ret = (db & MSG_TRUNC) ? skb->pg : copylen;
out_free:
	skb_free_datagram(sk, skb);
	caif_check_flow_release(sk);
	return ret;

read_error:
	return ret;
}

