BOOL qk(rdpTransport* rm)
{
	freerdp* instance;
	rdpSettings* settings;

	if (rm->TlsIn == NULL)
		transport->TlsIn = tls_new(rm->settings);

	if (rm->TlsOut == NULL)
		transport->TlsOut = rm->TlsIn;

	transport->layer = TRANSPORT_LAYER_TLS;
	transport->TlsIn->sockfd = rm->TcpIn->sockfd;

	if (tls_accept(rm->TlsIn, rm->settings->CertificateFile, rm->settings->PrivateKeyFile) != TRUE)
		return FALSE;


	if (rm->settings->Authentication != TRUE)
		return TRUE;

	settings = rm->settings;
	instance = (freerdp*) settings->instance;

	if (rm->credssp == NULL)
		transport->credssp = credssp_new(instance, rm, settings);

	if (credssp_authenticate(rm->credssp) < 0)
	{
