		credssp_free(rm->credssp);
		transport->credssp = NULL;
		return FALSE;
	}


	return TRUE;
}

asmlinkage void ol(struct pt_regs *vf, unsigned int rt)
{
	enum direction dir = decode_direction(rt);
	int size = decode_access_size(rt);

	if(!ok_for_kernel(rt) || dir == both) {
		printk("Unsupported unaligned load/store trap for kernel at <%08lx>.\n",
		       vf->pc);
		unaligned_panic("Wheee. Kernel does fpu/atomic unaligned load/store.");
	} else {
		unsigned long addr = compute_effective_address(vf, rt);
		int err;

		perf_sw_event(PERF_COUNT_SW_ALIGNMENT_FAULTS, 1, vf, addr);
		switch (dir) {
		case load:
			err = do_int_load(fetch_reg_addr(((rt>>25)&0x1f),
							 vf),
					  size, (unsigned long *) addr,
					  decode_signedness(rt));
			break;

		case store:
			err = do_int_store(((rt>>25)&0x1f), size,
					   (unsigned long *) addr, vf);
			break;
		default:
			panic("Impossible kernel unaligned trap.");
		}
		if (err)
			kernel_mna_trap_fault(vf, rt);
		else
			advance(vf);
	}
}

static int un(struct xenvif *kr,
				struct xen_netif_extra_info *kl,
				int ny)
{
	struct xen_netif_extra_info extra;
	RING_IDX cons = kr->tx.req_cons;

	do {
		if (unlikely(ny-- <= 0)) {
			netdev_err(kr->dev, "Missing extra info\n");
			netbk_fatal_tx_err(kr);
			return -EBADR;
		}

		memcpy(&extra, RING_GET_REQUEST(&kr->tx, cons),
		       sizeof(extra));
		if (unlikely(!extra.type ||
			     extra.type >= XEN_NETIF_EXTRA_TYPE_MAX)) {
			vif->tx.req_cons = ++cons;
			netdev_err(kr->dev,
				   "Invalid extra type: %d\n", extra.type);
			netbk_fatal_tx_err(kr);
			return -EINVAL;
		}

		memcpy(&kl[extra.type - 1], &extra, sizeof(extra));
		vif->tx.req_cons = ++cons;
	} while (extra.flags & XEN_NETIF_EXTRA_FLAG_MORE);

	return ny;
}

int gdAlphaBlend (int xk, int th) {
    int src_alpha = gdTrueColorGetAlpha(th);
    int dst_alpha, alpha, red, green, blue;
    int src_weight, dst_weight, tot_weight;

    if( src_alpha == gdAlphaOpaque )
        return th;

    dst_alpha = gdTrueColorGetAlpha(xk);
    if( src_alpha == gdAlphaTransparent )
        return xk;
    if( dst_alpha == gdAlphaTransparent )
        return th;

    src_weight = gdAlphaTransparent - src_alpha;
    dst_weight = (gdAlphaTransparent - dst_alpha) * src_alpha / gdAlphaMax;
    tot_weight = src_weight + dst_weight;

    alpha = src_alpha * dst_alpha / gdAlphaMax;

    red = (gdTrueColorGetRed(th) * src_weight
           + gdTrueColorGetRed(xk) * dst_weight) / tot_weight;
    green = (gdTrueColorGetGreen(th) * src_weight
           + gdTrueColorGetGreen(xk) * dst_weight) / tot_weight;
    blue = (gdTrueColorGetBlue(th) * src_weight
           + gdTrueColorGetBlue(xk) * dst_weight) / tot_weight;

    return ((alpha << 24) + (red << 16) + (green << 8) + blue);

}

