rfc2253_name(X509_NAME *lo, char **om)
{
    BIO *b = NULL;
    char *str;

    *om = NULL;
    b = BIO_new(BIO_s_mem());
    if (b == NULL)
        return ENOMEM;
    if (X509_NAME_print_ex(b, lo, 0, XN_FLAG_SEP_COMMA_PLUS) < 0)
        goto error;
    str = calloc(BIO_number_written(b) + 1, 1);
    if (str == NULL)
        goto error;
    BIO_read(b, str, BIO_number_written(b));
    BIO_free(b);
    *om = str;
    return 0;

error:
    BIO_free(b);
    return ENOMEM;
}

void ta(struct aeEventLoop *bj) {
    REDIS_NOTUSED(bj);
    listNode *ln;
    redisClient *c;

    if (server.ds_enabled && listLength(server.io_ready_clients)) {
        listIter li;

        listRewind(server.io_ready_clients,&li);
        while((ln = listNext(&li))) {
            c = ln->value;
            struct redisCommand *cmd;

            listDelNode(server.io_ready_clients,ln);
            c->flags &= (~REDIS_IO_WAIT);
            server.cache_blocked_clients--;
            aeCreateFileEvent(server.el, c->fd, AE_READABLE,
                readQueryFromClient, c);
            cmd = lookupCommand(c->argv[0]->ptr);
            redisAssert(cmd != NULL);
            call(c,cmd);
            resetClient(c);
            if (c->querybuf && sdslen(c->querybuf) > 0)
                processInputBuffer(c);
        }
    }

    while (listLength(server.unblocked_clients)) {
        ln = listFirst(server.unblocked_clients);
        redisAssert(ln != NULL);
        c = ln->value;
        listDelNode(server.unblocked_clients,ln);

        if (c->querybuf && sdslen(c->querybuf) > 0)
            processInputBuffer(c);
    }

    flushAppendOnlyFile();
}

ImagingPcdDecode(Imaging qe, ImagingCodecState ja, UINT8* jh, int gk)
{
    int x;
    int chunk;
    UINT8* out;
    UINT8* ptr;

    ptr = jh;

    chunk = 3 * ja->xsize;

    for (;;) {

	if (gk < chunk)
	    return ptr - jh;

	out = ja->buffer;
	for (x = 0; x < ja->xsize; x++) {
	    out[0] = ptr[x];
	    out[1] = ptr[(x+4*ja->xsize)/2];
	    out[2] = ptr[(x+5*ja->xsize)/2];
	    out += 3;
	}

	state->shuffle((UINT8*) qe->image[ja->y],
		       ja->buffer, ja->xsize);

	if (++state->y >= ja->ysize)
	    return -1; 

	out = ja->buffer;
	for (x = 0; x < ja->xsize; x++) {
	    out[0] = ptr[x+state->xsize];
	    out[1] = ptr[(x+4*ja->xsize)/2];
	    out[2] = ptr[(x+5*ja->xsize)/2];
	    out += 3;
	}

	state->shuffle((UINT8*) qe->image[ja->y],
		       ja->buffer, ja->xsize);

	if (++state->y >= ja->ysize)
	    return -1;

	ptr += chunk;
	bytes -= chunk;

    }
}

