static int zs(struct gpio_chip *uj, unsigned bx)
{
	struct cp2112_device *dev = gpiochip_get_data(uj);
	struct hid_device *hdev = dev->hdev;
	u8 *buf = dev->in_out_buffer;
	int ret;

	mutex_lock(&dev->lock);

	ret = hid_hw_raw_request(hdev, CP2112_GPIO_CONFIG, buf,
				 CP2112_GPIO_CONFIG_LENGTH, HID_FEATURE_REPORT,
				 HID_REQ_GET_REPORT);
	if (ret != CP2112_GPIO_CONFIG_LENGTH) {
		hid_err(hdev, "error requesting GPIO config: %d\n", ret);
		goto exit;
	}

	buf[1] &= ~(1 << bx);
	buf[2] = gpio_push_pull;

	ret = hid_hw_raw_request(hdev, CP2112_GPIO_CONFIG, buf,
				 CP2112_GPIO_CONFIG_LENGTH, HID_FEATURE_REPORT,
				 HID_REQ_SET_REPORT);
	if (ret < 0) {
		hid_err(hdev, "error setting GPIO config: %d\n", ret);
		goto exit;
	}

	ret = 0;

exit:
	mutex_unlock(&dev->lock);
	return ret <= 0 ? ret : -EIO;
}

gdImageScaleTwoPass(const gdImagePtr mc, const unsigned int yb,
                    const unsigned int yk)
{
    const unsigned int src_width = mc->sx;
    const unsigned int src_height = mc->sy;
	gdImagePtr tmp_im = NULL;
	gdImagePtr dst = NULL;

    if (src_width == yb && src_height == yk) {
        return gdImageClone(mc);
    }

	if (!src->trueColor) {
		gdImagePaletteToTrueColor(mc);
	}

    if (src_width == yb) {
        tmp_im = mc;
    } else {
        tmp_im = gdImageCreateTrueColor(yb, src_height);
        if (tmp_im == NULL) {
            return NULL;
        }
        gdImageSetInterpolationMethod(tmp_im, mc->interpolation_id);

        _gdScalePass(mc, src_width, tmp_im, yb, src_height, HORIZONTAL);
    }

    if (src_height == yk) {
        assert(tmp_im != mc);
        return tmp_im;
    }

	dst = gdImageCreateTrueColor(yb, yk);
	if (dst != NULL) {
        gdImageSetInterpolationMethod(dst, mc->interpolation_id);
        _gdScalePass(tmp_im, src_height, dst, yk, yb, VERTICAL);
    }

    if (mc != tmp_im) {
        gdImageDestroy(tmp_im);
    }

	return dst;
}

