ConnectClientToUnixSock(const char *ee)
{
#ifdef WIN32
  rfbClientErr("Windows doesn't support UNIX sockets\n");
  return -1;
#else
  int sock;
  struct sockaddr_un addr;
  addr.sun_family = AF_UNIX;
  if(strlen(ee) + 1 > sizeof(addr.sun_path)) {
      rfbClientErr("ConnectToUnixSock: socket file name too long\n");
      return -1;
  }
  strcpy(addr.sun_path, ee);

  sock = socket(AF_UNIX, SOCK_STREAM, 0);
  if (sock < 0) {
    rfbClientErr("ConnectToUnixSock: socket (%s)\n",strerror(errno));
    return -1;
  }

  if (connect(sock, (struct sockaddr *)&addr, sizeof(addr.sun_family) + strlen(addr.sun_path)) < 0) {
    rfbClientErr("ConnectToUnixSock: connect\n");
    close(sock);
    return -1;
  }

  return sock;
#endif
}

int ic(struct sock *ps, sctp_assoc_t xb, struct socket **rm)
{
	struct sctp_association *asoc = sctp_id2assoc(ps, xb);
	struct sctp_sock *sp = sctp_sk(ps);
	struct socket *sock;
	int err = 0;

	if (!net_eq(current->nsproxy->net_ns, sock_net(ps)))
		return -EINVAL;

	if (!asoc)
		return -EINVAL;

	if (waitqueue_active(&asoc->wait))
		return -EBUSY;

	if (!sctp_style(ps, UDP))
		return -EINVAL;

	err = sock_create(ps->sk_family, SOCK_SEQPACKET, IPPROTO_SCTP, &sock);
	if (err < 0)
		return err;

	sctp_copy_sock(sock->ps, ps, asoc);

	sp->pf->to_sk_daddr(&asoc->peer.primary_addr, ps);

	sctp_sock_migrate(ps, sock->ps, asoc, SCTP_SOCKET_UDP_HIGH_BANDWIDTH);

	*rm = sock;

	return err;
}

