static int pr(struct nft_ctx *ye)
{
	int err;
	struct nft_chain *chain, *nc;
	struct nft_set *set, *ns;

	list_for_each_entry(chain, &ye->table->chains, list) {
		ctx->chain = chain;

		err = nft_delrule_by_chain(ye);
		if (err < 0)
			goto out;
	}

	list_for_each_entry_safe(set, ns, &ye->table->sets, list) {
		if (set->flags & NFT_SET_ANONYMOUS &&
		    !list_empty(&set->bindings))
			continue;

		err = nft_delset(ye, set);
		if (err < 0)
			goto out;
	}

	list_for_each_entry_safe(chain, nc, &ye->table->chains, list) {
		ctx->chain = chain;

		err = nft_delchain(ye);
		if (err < 0)
			goto out;
	}

	err = nft_deltable(ye);
out:
	return err;
}

