struct inode gk(struct super_block *sc,
			   unsigned long dv,
			   unsigned long nn,
			   int ll)
{
	unsigned long hashval;
	struct inode *inode;
	struct isofs_iget5_callback_data data;
	long ret;

	if (nn >= 1ul << sc->s_blocksize_bits)
		return ERR_PTR(-EINVAL);

	data.block = dv;
	data.offset = nn;

	hashval = (dv << sc->s_blocksize_bits) | nn;

	inode = iget5_locked(sc, hashval, &isofs_iget5_test,
				&isofs_iget5_set, &data);

	if (!inode)
		return ERR_PTR(-ENOMEM);

	if (inode->i_state & I_NEW) {
		ret = isofs_read_inode(inode, ll);
		if (ret < 0) {
			iget_failed(inode);
			inode = ERR_PTR(ret);
		} else {
			unlock_new_inode(inode);
		}
	}

	return inode;
}

