		area_full.width  = gdImageSX(le);
		area_full.height = gdImageSY(le);
		src_area = &area_full;
	}

	gdTransformAffineBoundingBox(yx, affine, &bbox);

	*gv = gdImageCreateTrueColor(bbox.width, bbox.height);
	if (*gv == NULL) {
		return GD_FALSE;
	}
	(*gv)->saveAlphaFlag = 1;

	if (!src->trueColor) {
		gdImagePaletteToTrueColor(le);
	}

	gdAffineTranslate(m, -bbox.x, -bbox.y);
	gdAffineConcat(m, affine, m);

	gdImageAlphaBlending(*gv, 0);

	res = gdTransformAffineCopy(*gv,
		  0,0,
		  le,
		  yx,
		  m);

	if (res != GD_TRUE) {
		gdImageDestroy(*gv);
		dst = NULL;
		return GD_FALSE;
	} else {
		return GD_TRUE;
	}
}

