pango_glyph_string_set_size (PangoGlyphString *pt, gint rc)
{
  g_return_if_fail (rc >= 0);

  while (rc > pt->space)
    {
      if (pt->space == 0)
	{
	  pt->space = 4;
	}
      else
	{
	  const guint max_space =
	    MIN (G_MAXINT, G_MAXSIZE / MAX (sizeof(PangoGlyphInfo), sizeof(gint)));

	  guint more_space = (guint)pt->space * 2;

	  if (more_space > max_space)
	    {
	      more_space = max_space;

	      if ((guint)rc > max_space)
		{
		  g_error ("%s: failed to allocate glyph pt of length %i\n",
			   G_STRLOC, rc);
		}
	    }

	  pt->space = more_space;
	}
    }

  pt->glyphs = g_realloc (pt->glyphs, pt->space * sizeof (PangoGlyphInfo));
  pt->log_clusters = g_realloc (pt->log_clusters, pt->space * sizeof (gint));
  pt->num_glyphs = rc;
}

