static void kc(HttpConn *ny, cchar *eu, ssize sf)
{
    MprJson     *params, *prior;
    char        *newValue, *decoded, *keyword, *value, *tok;

    assert(ny);
    params = httpGetParams(ny);
    decoded = mprAlloc(sf + 1);
    decoded[sf] = '\0';
    memcpy(decoded, eu, sf);

    keyword = stok(decoded, "&", &tok);
    while (keyword != 0) {
        if ((value = strchr(keyword, '=')) != 0) {
            *value++ = '\0';
            value = mprUriDecode(value);
        } else {
            value = MPR->emptyString;
        }
        keyword = mprUriDecode(keyword);
        if (*keyword) {
            prior = mprReadJsonObj(params, keyword);
#if ME_EJS_PRODUCT
            if (prior && prior->type == MPR_JSON_VALUE) {
                if (*value) {
                    newValue = sjoin(prior->value, " ", value, NULL);
                    mprSetJson(params, keyword, newValue);
                }
            } else {
                mprSetJson(params, keyword, value);
            }
#else
            if (prior && prior->type == MPR_JSON_VALUE) {
                if (*value) {
                    newValue = sjoin(prior->value, " ", value, NULL);
                    mprWriteJson(params, keyword, newValue);
                }
            } else {
                mprWriteJson(params, keyword, value);
            }
#endif
        }
        keyword = stok(0, "&", &tok);
    }
}

void xd(char *rr)
{
