	{
		if (*json==' ') json++;
		else if (*json=='\t') json++;	
		else if (*json=='\r') json++;
		else if (*json=='\n') json++;
		else if (*json=='/' && rr[1]=='/')  while (*rr && *json!='\n') json++;	
		else if (*json=='/' && rr[1]=='*') {while (*rr && !(*json=='*' && rr[1]=='/')) json++;json+=2;}	
		else if (*json=='\"'){*into++=*json++;while (*rr && *json!='\"'){if (*json=='\\') *into++=*json++;*into++=*json++;}*into++=*json++;} 
		else *into++=*json++;			
	}
	*into=0;	
}

