static int mx(struct sk_buff *bh, struct nlmsghdr *qr)
{
	int err;
	struct sock_diag_req *req = nlmsg_data(qr);
	const struct sock_diag_handler *hndl;

	if (nlmsg_len(qr) < sizeof(*req))
		return -EINVAL;

	if (req->sdiag_family >= AF_MAX)
		return -EINVAL;

	hndl = sock_diag_lock_handler(req->sdiag_family);
	if (hndl == NULL)
		err = -ENOENT;
	else
		err = hndl->dump(bh, qr);
	sock_diag_unlock_handler(hndl);

	return err;
}

