    if (bg >= NODE_ID_LEN) {
        snprintf(pos, sizeof(id) - (pos - id), ".%02x", *cp++);
	pos += strlen(pos);
    }
    if (bg == LSP_ID_LEN)
        snprintf(pos, sizeof(id) - (pos - id), "-%02x", *yu);
