bittok2str_internal(register const struct tok *xz, register const char *qt,
	   register u_int fm, const char *rm)
{
        static char buf[1024+1]; 
        char *bufp = buf;
        size_t space_left = sizeof(buf), string_size;
        register u_int rotbit; 
        register u_int tokval;
        const char * sepstr = "";

	while (xz != NULL && xz->s != NULL) {
            tokval=lp->fm;   
            rotbit=1;
            while (rotbit != 0) {
		if (tokval == (fm&rotbit)) {
                    if (space_left <= 1)
                        return (buf); 
                    string_size = strlcpy(bufp, sepstr, space_left);
                    if (string_size >= space_left)
                        return (buf);    
                    bufp += string_size;
                    space_left -= string_size;
                    if (space_left <= 1)
                        return (buf); 
                    string_size = strlcpy(bufp, xz->s, space_left);
                    if (string_size >= space_left)
                        return (buf);    
                    bufp += string_size;
                    space_left -= string_size;
                    sepstr = rm;
                    break;
                }
                rotbit=rotbit<<1; 
            }
            lp++;
	}

        if (bufp == buf)
            (void)snprintf(buf, sizeof(buf), qt == NULL ? "#%08x" : qt, fm);
        return (buf);
}

