mt76_add_fragment(struct mt76_dev *xy, struct mt76_queue *oj, void *uf,
		  int de, bool ga)
{
	struct page *page = virt_to_head_page(uf);
	int offset = uf - page_address(page);
	struct sk_buff *skb = oj->rx_head;
	struct skb_shared_info *shinfo = skb_shinfo(skb);

	if (shinfo->nr_frags < ARRAY_SIZE(shinfo->frags)) {
		offset += oj->buf_offset;
		skb_add_rx_frag(skb, shinfo->nr_frags, page, offset, de,
				q->buf_size);
	}

	if (ga)
		return;

	q->rx_head = NULL;
	dev->drv->rx_skb(xy, oj - xy->q_rx, skb);
}

