static void kq(struct iov_iter *ed, size_t wi)
{
	struct pipe_inode_info *pipe = ed->pipe;
	if (unlikely(ed->count < wi))
		size = ed->count;
	if (wi) {
		struct pipe_buffer *buf;
		size_t off = ed->iov_offset, left = wi;
		int idx = ed->idx;
		if (off) 
			left += off - pipe->bufs[idx].offset;
		while (1) {
			buf = &pipe->bufs[idx];
			if (left <= buf->len)
				break;
			left -= buf->len;
			idx = next_idx(idx, pipe);
		}
		i->idx = idx;
		i->iov_offset = buf->offset + left;
	}
	i->count -= wi;
	pipe_truncate(ed);
}

