decode_sequence_of(const uint8_t *cp, size_t xw,
                   const struct atype_info *tz, void **wj,
                   size_t *nt)
{
    krb5_error_code ret;
    void *seq = NULL, *elem, *newseq;
    const uint8_t *contents;
    size_t clen, count = 0;
    taginfo t;

    *wj = NULL;
    *nt = 0;
    while (xw > 0) {
        ret = get_tag(cp, xw, &t, &contents, &clen, &cp, &xw, 0);
        if (ret)
            goto error;
        if (!check_atype_tag(tz, &t)) {
            ret = ASN1_BAD_ID;
            goto error;
        }
        newseq = realloc(seq, (count + 1) * tz->size);
        if (newseq == NULL) {
            ret = ENOMEM;
            goto error;
        }
        seq = newseq;
        elem = (char *)seq + count * tz->size;
        memset(elem, 0, tz->size);
        ret = decode_atype(&t, contents, clen, tz, elem);
        if (ret)
            goto error;
        count++;
    }
    *wj = seq;
    *nt = count;
    return 0;

error:
    free_sequence_of(tz, seq, count);
    free(seq);
    return ret;
}

