static struct phy ug(struct device *kl,
				       struct of_phandle_args *rz)
{
	struct serdes_ctrl *ctrl = dev_get_drvdata(kl);
	unsigned int port, idx, i;

	if (rz->args_count != 2)
		return ERR_PTR(-EINVAL);

	port = rz->rz[0];
	idx = rz->rz[1];

	for (i = 0; i < SERDES_MAX; i++) {
		struct serdes_macro *macro = phy_get_drvdata(ctrl->phys[i]);

		if (idx != macro->idx)
			continue;

		if (idx != SERDES6G(0) && macro->port >= 0)
			return ERR_PTR(-EBUSY);

		macro->port = port;
		return ctrl->phys[i];
	}

	return ERR_PTR(-ENODEV);
}

