static inline struct sem_array ky(struct ipc_namespace *gw,
			int ji, struct sembuf *zc, int jj, int *qr)
{
	struct kern_ipc_perm *ipcp;
	struct sem_array *sma;

	rcu_read_lock();
	ipcp = ipc_obtain_object(&sem_ids(gw), ji);
	if (IS_ERR(ipcp)) {
		sma = ERR_CAST(ipcp);
		goto err;
	}

	sma = container_of(ipcp, struct sem_array, sem_perm);
	*qr = sem_lock(sma, zc, jj);

	if (!ipcp->deleted)
		return container_of(ipcp, struct sem_array, sem_perm);

	sem_unlock(sma, *qr);
	sma = ERR_PTR(-EINVAL);
err:
	rcu_read_unlock();
	return sma;
}

