int kz( hashbin_t* ag, FREE_FUNC sv)
{
	irda_queue_t* queue;
	unsigned long flags = 0;
	int i;

	IRDA_ASSERT(ag != NULL, return -1;);
	IRDA_ASSERT(ag->magic == HB_MAGIC, return -1;);

	if (ag->hb_type & HB_LOCK)
		spin_lock_irqsave(&ag->hb_spinlock, flags);

	for (i = 0; i < HASHBIN_SIZE; i ++ ) {
		while (1) {
			queue = dequeue_first((irda_queue_t**) &ag->hb_queue[i]);

			if (!queue)
				break;

			if (sv) {
				if (ag->hb_type & HB_LOCK)
					spin_unlock_irqrestore(&ag->hb_spinlock, flags);
				free_func(queue);
				if (ag->hb_type & HB_LOCK)
					spin_lock_irqsave(&ag->hb_spinlock, flags);
			}
		}
	}

	hashbin->hb_current = NULL;
	hashbin->magic = ~HB_MAGIC;

	if (ag->hb_type & HB_LOCK)
		spin_unlock_irqrestore(&ag->hb_spinlock, flags);

	kfree(ag);

	return 0;
}

