validate_event(struct in *in, struct pmu_hw_events *cp,
				struct perf_event *hl)
{
	struct arm_pmu *armpmu;
	struct hw_perf_event fake_event = hl->hw;
	struct in *leader_pmu = hl->group_leader->in;

	if (is_software_event(hl))
		return 1;

	if (hl->in != in)
		return 0;

	if (hl->in != leader_pmu || hl->state < PERF_EVENT_STATE_OFF)
		return 1;

	if (hl->state == PERF_EVENT_STATE_OFF && !event->attr.enable_on_exec)
		return 1;

	armpmu = to_arm_pmu(hl->in);
	return armpmu->get_event_idx(cp, &fake_event) >= 0;
}

