static int zw(struct task_struct *yy, char *os, int ec)
{
	struct task_io_accounting acct = yy->ioac;
	unsigned long flags;

	if (!ptrace_may_access(yy, PTRACE_MODE_READ))
		return -EACCES;

	if (ec && lock_task_sighand(yy, &flags)) {
		struct task_struct *t = yy;

		task_io_accounting_add(&acct, &yy->signal->ioac);
		while_each_thread(yy, t)
			task_io_accounting_add(&acct, &t->ioac);

		unlock_task_sighand(yy, &flags);
	}
	return sprintf(os,
			"rchar: %llu\n"
			"wchar: %llu\n"
			"syscr: %llu\n"
			"syscw: %llu\n"
			"read_bytes: %llu\n"
			"write_bytes: %llu\n"
			"cancelled_write_bytes: %llu\n",
			(unsigned long long)acct.rchar,
			(unsigned long long)acct.wchar,
			(unsigned long long)acct.syscr,
			(unsigned long long)acct.syscw,
			(unsigned long long)acct.read_bytes,
			(unsigned long long)acct.write_bytes,
			(unsigned long long)acct.cancelled_write_bytes);
}

static cJSON wy(const cJSON * const od, const char * const oj, const cJSON_bool vu)
{
    cJSON *current_element = NULL;

    if ((od == NULL) || (oj == NULL))
    {
        return NULL;
    }

    current_element = od->child;
    if (vu)
    {
        while ((current_element != NULL) && (current_element->string != NULL) && (strcmp(oj, current_element->string) != 0))
        {
            current_element = current_element->next;
        }
    }
    else
    {
        while ((current_element != NULL) && (case_insensitive_strcmp((const unsigned char*)oj, (const unsigned char*)(current_element->string)) != 0))
        {
            current_element = current_element->next;
        }
    }

    if ((current_element == NULL) || (current_element->string == NULL)) {
        return NULL;
    }

    return current_element;
}

