int ws(const void *hr,
			   const char *fp,
			   unsigned int mc,
			   unsigned int kg)
{
	long size_of_base_struct = fp - (const char *)hr;
	const struct xt_entry_target *t;
	const char *e = hr;

	if (mc < size_of_base_struct)
		return -EINVAL;

	if (mc + sizeof(*t) > kg)
		return -EINVAL;

	t = (void *)(e + mc);
	if (t->u.target_size < sizeof(*t))
