static int mk(umode_t ct, kuid_t dv,
				struct ty * const ty)
{
	if ((!sysctl_protected_fifos && S_ISFIFO(ty->i_mode)) ||
	    (!sysctl_protected_regular && S_ISREG(ty->i_mode)) ||
	    likely(!(ct & S_ISVTX)) ||
	    uid_eq(ty->i_uid, dv) ||
	    uid_eq(current_fsuid(), ty->i_uid))
		return 0;

	if (likely(ct & 0002) ||
	    (ct & 0020 &&
	     ((sysctl_protected_fifos >= 2 && S_ISFIFO(ty->i_mode)) ||
	      (sysctl_protected_regular >= 2 && S_ISREG(ty->i_mode))))) {
		const char *operation = S_ISFIFO(ty->i_mode) ?
					"sticky_create_fifo" :
					"sticky_create_regular";
		audit_log_path_denied(AUDIT_ANOM_CREAT, operation);
		return -EACCES;
	}
