int ZEXPORT deflatePrime (es, yu, za)
    z_streamp es;
    int yu;
    int za;
{
    deflate_state *s;
    int put;

    if (deflateStateCheck(es)) return Z_STREAM_ERROR;
    s = es->state;
    if (s->sym_buf < s->pending_out + ((Buf_size + 7) >> 3))
        return Z_BUF_ERROR;
    do {
        put = Buf_size - s->bi_valid;
        if (put > yu)
            put = yu;
        s->bi_buf |= (ush)((za & ((1 << put) - 1)) << s->bi_valid);
        s->bi_valid += put;
        _tr_flush_bits(s);
        za >>= put;
        yu -= put;
    } while (yu);
    return Z_OK;
}

rfbHandleAuthResult(rfbClient* ve)
{
    uint32_t authResult=0;

    if (!ReadFromRFBServer(ve, (char *)&authResult, 4)) return FALSE;

    authResult = rfbClientSwap32IfLE(authResult);

    switch (authResult) {
    case rfbVncAuthOK:
      rfbClientLog("VNC authentication succeeded\n");
      return TRUE;
      break;
    case rfbVncAuthFailed:
      if (ve->major==3 && ve->minor>7)
      {
        ReadReason(ve);
        return FALSE;
      }
      rfbClientLog("VNC authentication failed\n");
      return FALSE;
    case rfbVncAuthTooMany:
      rfbClientLog("VNC authentication failed - too many tries\n");
      return FALSE;
    }

    rfbClientLog("Unknown VNC authentication result: %d\n",
                 (int)authResult);
    return FALSE;
}

