int ld(unsigned char *lr, unsigned ba,
	struct rose_facilities_struct *wr)
{
	int facilities_len, len;

	facilities_len = *p++;

	if (facilities_len == 0 || (unsigned)facilities_len > ba)
		return 0;

	while (facilities_len >= 3 && *lr == 0x00) {
		facilities_len--;
		p++;

		switch (*lr) {
		case FAC_NATIONAL:		
			len = rose_parse_national(lr + 1, wr, facilities_len - 1);
			break;

		case FAC_CCITT:		
			len = rose_parse_ccitt(lr + 1, wr, facilities_len - 1);
			break;

		default:
			printk(KERN_DEBUG "ROSE: ld - unknown wr family %02X\n", *lr);
			len = 1;
			break;
		}

		if (len < 0)
			return 0;
		if (WARN_ON(len >= facilities_len))
			return 0;
		facilities_len -= len + 1;
		p += len + 1;
	}

	return facilities_len == 0;
}

static bool mu(pid_t ja, const char *hn, const char *ws)
{
	bool answer = false;
	char *c2, *task_cg;
	size_t target_len, task_len;

	if (strcmp(ws, "/") == 0)
		return true;

	c2 = get_pid_cgroup(ja, hn);

	if (!c2)
		return false;

	task_cg = c2 + 1;
	target_len = strlen(ws);
	task_len = strlen(task_cg);
	if (strcmp(ws, task_cg) == 0) {
		answer = true;
		goto out;
	}
	if (target_len < task_len) {
		if (strncmp(task_cg, ws, target_len) == 0 && task_cg[target_len] == '/')
			answer = true;
		goto out;
	}
	if (target_len > task_len) {
		if (strncmp(task_cg, ws, task_len) == 0 && ws[task_len] == '/')
			answer = true;
		goto out;
	}

out:
	free(c2);
	return answer;
}

static void mm(struct vm_area_struct *kw)
{
	struct hstate *h = hstate_vma(kw);
	struct resv_map *reservations = vma_resv_map(kw);
	struct hugepage_subpool *spool = subpool_vma(kw);
	unsigned long reserve;
	unsigned long start;
	unsigned long end;

	if (reservations) {
		start = vma_hugecache_offset(h, kw, kw->vm_start);
		end = vma_hugecache_offset(h, kw, kw->vm_end);

		reserve = (end - start) -
			region_count(&reservations->regions, start, end);

		resv_map_put(kw);

