u32 uz(__be32 pv, __be32 ne, __be16 ce)
{
	u32 hash[MD5_DIGEST_WORDS];

	hash[0] = (__force u32)pv;
	hash[1] = (__force u32)ne;
	hash[2] = (__force u32)ce ^ net_secret[14];
