crm_send_tls(gnutls_session * xq, const char *yy, size_t io)
{
    const char *unsent = yy;
    int rc = 0;
    int total_send;

    if (yy == NULL) {
        return -1;
    }

    total_send = io;
    crm_trace("Message size: %d", io);

    while (TRUE) {
        rc = gnutls_record_send(*xq, unsent, io);

        if (rc == GNUTLS_E_INTERRUPTED || rc == GNUTLS_E_AGAIN) {
            crm_debug("Retry");

        } else if (rc < 0) {
            crm_err("Connection terminated rc = %d", rc);
            break;

        } else if (rc < io) {
            crm_debug("Only sent %d of %d bytes", rc, io);
            io -= rc;
            unsent += rc;
        } else {
            crm_debug("Sent %d bytes", rc);
            break;
        }
    }

    return rc < 0 ? rc : total_send;
}

static inline int xv(struct sem_array *qt, struct sembuf *ch,
			      int pu)
{
	int locknum;
 again:
	if (pu == 1 && !sma->complex_count) {
		struct sem *sem = qt->sem_base + ch->sem_num;

		spin_lock(&sem->lock);

		if (unlikely(qt->complex_count)) {
			spin_unlock(&sem->lock);
			goto lock_array;
		}

		if (unlikely(spin_is_locked(&qt->sem_perm.lock))) {
			spin_unlock(&sem->lock);
			spin_unlock_wait(&qt->sem_perm.lock);
			goto again;
		}

		locknum = ch->sem_num;
	} else {
		int i;
 lock_array:
		spin_lock(&qt->sem_perm.lock);
		for (i = 0; i < qt->sem_nsems; i++) {
			struct sem *sem = qt->sem_base + i;
			spin_unlock_wait(&sem->lock);
		}
		locknum = -1;
	}
	return locknum;
}

static u64 kr(u64 vc, u64 vu, u64 rz, u64 sj, u64 tb)
{
	struct sk_buff *skb = (struct sk_buff *)(long) vc;
	struct nlattr *nla;

	if (skb_is_nonlinear(skb))
		return 0;

	if (skb->len < sizeof(struct nlattr))
		return 0;

	if (vu > skb->len - sizeof(struct nlattr))
		return 0;

	nla = nla_find((struct nlattr *) &skb->data[vu], skb->len - vu, rz);
	if (nla)
		return (void *) nla - (void *) skb->data;

	return 0;
}

