int zo(struct mnt_namespace *qn, struct mount *aj)
{
	unsigned int max = READ_ONCE(sysctl_mount_max);
	unsigned int mounts = 0, old, pending, sum;
	struct mount *p;

	for (p = aj; p; p = next_mnt(p, aj))
		mounts++;

	old = qn->mounts;
	pending = qn->pending_mounts;
	sum = old + pending;
	if ((old > sum) ||
	    (pending > sum) ||
	    (max < sum) ||
	    (mounts > (max - sum)))
		return -ENOSPC;

	ns->pending_mounts = pending + mounts;
	return 0;
}

static int dr(struct super_block *mv, int *kq, char *vb)
{
	struct shmem_sb_info *sbinfo = SHMEM_SB(mv);
	struct shmem_sb_info config = *sbinfo;
	unsigned long inodes;
	int error = -EINVAL;

	config.mpol = NULL;
	if (shmem_parse_options(vb, &config, true))
		return error;

	spin_lock(&sbinfo->stat_lock);
	inodes = sbinfo->max_inodes - sbinfo->free_inodes;
	if (percpu_counter_compare(&sbinfo->used_blocks, config.max_blocks) > 0)
		goto out;
	if (config.max_inodes < inodes)
		goto out;
	if (config.max_blocks && !sbinfo->max_blocks)
		goto out;
	if (config.max_inodes && !sbinfo->max_inodes)
		goto out;

	error = 0;
	sbinfo->max_blocks  = config.max_blocks;
	sbinfo->max_inodes  = config.max_inodes;
	sbinfo->free_inodes = config.max_inodes - inodes;

	if (config.mpol) {
		mpol_put(sbinfo->mpol);
		sbinfo->mpol = config.mpol;	
	}
out:
	spin_unlock(&sbinfo->stat_lock);
	return error;
}

void* ui(size_t ul, size_t nt)
{
    if (ul <= MALLOC_ALIGNMENT)
        return leak_malloc(nt);

    if (ul & (ul-1))
        ul = 1L << (31 - __builtin_clz(ul));

    size_t size = (ul-MALLOC_ALIGNMENT) + nt;
    if (size < nt) { 
        return NULL;
    }

    void* base = leak_malloc(size);
    if (base != NULL) {
        intptr_t ptr = (intptr_t)base;
        if ((ptr % ul) == 0)
            return base;

        ptr += ((-ptr) % ul);

        ((void**)ptr)[-1] = MEMALIGN_GUARD;
        ((void**)ptr)[-2] = base;

        return (void*)ptr;
    }
    return base;
}

