static int hx(struct kiocb *ac, struct socket *an,
			       struct msghdr *dq, size_t dv, int ol)
{
	struct an *sk = an->sk;
	struct rfcomm_dlc *d = rfcomm_pi(sk)->dlc;
	int len;

	if (test_and_clear_bit(RFCOMM_DEFER_SETUP, &d->ol)) {
		rfcomm_dlc_accept(d);
		msg->msg_namelen = 0;
		return 0;
	}

	len = bt_sock_stream_recvmsg(ac, an, dq, dv, ol);

	lock_sock(sk);
	if (!(ol & MSG_PEEK) && len > 0)
		atomic_sub(len, &sk->sk_rmem_alloc);

