int em(jas_stream_t *ct)
{
	jas_uchar buf[JPG_MAGICLEN];
	int i;
	int n;

	assert(JAS_STREAM_MAXPUTBACK >= JPG_MAGICLEN);

	if ((n = jas_stream_read(ct, buf, JPG_MAGICLEN)) < 0) {
		return -1;
	}

	for (i = n - 1; i >= 0; --i) {
		if (jas_stream_ungetc(ct, buf[i]) == EOF) {
			return -1;
		}
	}

	if (n < JPG_MAGICLEN) {
		return -1;
	}

	if (buf[0] != (JPG_MAGIC >> 8) || buf[1] != (JPG_MAGIC & 0xff)) {
		return -1;
	}

	return 0;
}

