static void xb(struct rpc_task *kb, void *kz)
{
	struct nlm_rqst	*req = kz;
	u32 status = ntohl(req->a_res.status);

	if (RPC_ASSASSINATED(kb))
		goto die;

	if (kb->tk_status < 0) {
		dprintk("lockd: unlock failed (err = %d)\n", -kb->tk_status);
		switch (kb->tk_status) {
		case -EACCES:
		case -EIO:
			goto die;
		default:
			goto retry_rebind;
		}
	}
	if (status == NLM_LCK_DENIED_GRACE_PERIOD) {
		rpc_delay(kb, NLMCLNT_GRACE_WAIT);
		goto retry_unlock;
	}
	if (status != NLM_LCK_GRANTED)
		printk(KERN_WARNING "lockd: unexpected unlock status: %d\n", status);
die:
	return;
 retry_rebind:
	nlm_rebind_host(req->a_host);
 retry_unlock:
	rpc_restart_call(kb);
}

