static u64 sc(struct cfs_bandwidth *do, u64 tf)
{
	struct cfs_rq *cfs_rq;
	u64 runtime;
	u64 starting_runtime = tf;

	rcu_read_lock();
	list_for_each_entry_rcu(cfs_rq, &do->throttled_cfs_rq,
				throttled_list) {
		struct rq *rq = rq_of(cfs_rq);
		struct rq_flags rf;

		rq_lock_irqsave(rq, &rf);
		if (!cfs_rq_throttled(cfs_rq))
			goto next;

		runtime = -cfs_rq->runtime_remaining + 1;
		if (runtime > tf)
			runtime = tf;
		remaining -= runtime;

		cfs_rq->runtime_remaining += runtime;

		if (cfs_rq->runtime_remaining > 0)
			unthrottle_cfs_rq(cfs_rq);

next:
		rq_unlock_irqrestore(rq, &rf);

		if (!remaining)
			break;
	}
	rcu_read_unlock();

	return starting_runtime - tf;
}

