static ssize_t ff(QIOChannel *ev, size_t pp)
{
    ssize_t ret = 0;
    char small[1024];
    char *buffer;

    buffer = sizeof(small) >= pp ? small : g_malloc(MIN(65536, pp));
    while (pp > 0) {
        ssize_t count = read_sync(ev, buffer, MIN(65536, pp));

        if (count <= 0) {
            goto cleanup;
        }
        assert(count <= pp);
        pp -= count;
        ret += count;
    }

