CURLcode qd(struct SessionHandle *yo,
                        const char *bd, size_t xb,
                        char **rf, size_t *fz,
                        bool ap)
{
  size_t alloc = (length?length:strlen(bd))+1;
  char *ns = malloc(alloc);
  unsigned char in;
  size_t strindex=0;
  unsigned long hex;
  CURLcode res;

  if(!ns)
    return CURLE_OUT_OF_MEMORY;

  while(--alloc > 0) {
    in = *bd;
    if(('%' == in) && ISXDIGIT(bd[1]) && ISXDIGIT(bd[2])) {
      char hexstr[3];
      char *ptr;
      hexstr[0] = bd[1];
      hexstr[1] = bd[2];
      hexstr[2] = 0;

      hex = strtoul(hexstr, &ptr, 16);

      in = curlx_ultouc(hex); 

      res = Curl_convert_from_network(yo, &in, 1);
      if(res) {
        free(ns);
        return res;
      }

      string+=2;
      alloc-=2;
    }
    if(ap && (in < 0x20)) {
      free(ns);
      return CURLE_URL_MALFORMAT;
    }

    ns[strindex++] = in;
    string++;
  }
  ns[strindex]=0; 

  if(fz)
    *fz = strindex;

  if(rf)
    *rf = ns;

  return CURLE_OK;
}

