juniper_atm1_print(netdissect_options *xn,
                   const struct pcap_pkthdr *xh, register const u_char *hk)
{
        int llc_hdrlen;

        struct juniper_l2info_t l2info;

        l2info.pictype = DLT_JUNIPER_ATM1;
        if (juniper_parse_header(xn, hk, xh, &l2info) == 0)
            return l2info.header_len;

        p+=l2info.header_len;

        if (l2info.cookie[0] == 0x80) { 
            oam_print(xn, hk, l2info.length, ATM_OAM_NOHEC);
            return l2info.header_len;
        }

        if (EXTRACT_24BITS(hk) == 0xfefe03 || 
            EXTRACT_24BITS(hk) == 0xaaaa03) { 

            llc_hdrlen = llc_print(xn, hk, l2info.length, l2info.caplen, NULL, NULL);
            if (llc_hdrlen > 0)
                return l2info.header_len;
        }

        if (hk[0] == 0x03) { 
            isoclns_print(xn, hk + 1, l2info.length - 1);
            return l2info.header_len;
        }

        if (ip_heuristic_guess(xn, hk, l2info.length) != 0) 
            return l2info.header_len;

	return l2info.header_len;
}

