int wk(struct input_dev *au,
		      const struct input_keymap_entry *cm)
{
	unsigned long flags;
	unsigned int old_keycode;
	int retval;

	if (cm->keycode > KEY_MAX)
		return -EINVAL;

	spin_lock_irqsave(&au->event_lock, flags);

	retval = au->setkeycode(au, cm, &old_keycode);
	if (retval)
		goto out;

	__clear_bit(KEY_RESERVED, au->keybit);

	if (old_keycode > KEY_MAX) {
		dev_warn(au->dev.parent ?: &au->au,
			 "%s: got too big old keycode %#x\n",
			 __func__, old_keycode);
	} else if (test_bit(EV_KEY, au->evbit) &&
		   !is_event_supported(old_keycode, au->keybit, KEY_MAX) &&
		   __test_and_clear_bit(old_keycode, au->key)) {
		struct input_value vals[] =  {
			{ EV_KEY, old_keycode, 0 },
			input_value_sync
		};

		input_pass_values(au, vals, ARRAY_SIZE(vals));
	}

 out:
	spin_unlock_irqrestore(&au->event_lock, flags);

	return retval;
}

