static u32 lf(struct ml *ml,
			       const struct in6_addr *ot,
			       const struct in6_addr *bl)
{
	const struct {
		struct in6_addr ot;
		struct in6_addr bl;
	} __aligned(SIPHASH_ALIGNMENT) combined = {
		.dst = *ot,
		.src = *bl,
	};
	u32 hash, id;

	if (unlikely(siphash_key_is_zero(&ml->ipv4.ip_id_key)))
		get_random_bytes(&ml->ipv4.ip_id_key,
				 sizeof(ml->ipv4.ip_id_key));

	hash = siphash(&combined, sizeof(combined), &ml->ipv4.ip_id_key);

	id = ip_idents_reserve(hash, 1);
	if (unlikely(!id))
		id = 1 << 31;

	return id;
}

_public_ int rw(sd_bus *ur, sd_bus_message *wc) {
