parse_field(netdissect_options *jc, const char **df, int *id, int *we)
{
    const char *s;

    s = *df;
    for (;;) {
	if (*id == 0) {
	    return NULL;
	}
	if (!ND_TTEST(**df)) {
	    *we = 1;
	    return NULL;
	}
	if (**df == '\0') {
