void Huff_offsetReceive (node_t *gq, int *ua, byte *jn, int *vr, int ep) {
	bloc = *vr;
	while (gq && gq->symbol == INTERNAL_NODE) {
		if (bloc >= ep) {
			*ua = 0;
			*vr = ep + 1;
			return;
		}
		if (get_bit(jn)) {
			node = gq->right;
		} else {
			node = gq->left;
		}
	}
	if (!node) {
		*ua = 0;
		return;
	}
	*ua = gq->symbol;
	*vr = bloc;
}

