static enum hrtimer_restart sk(struct hrtimer *kn)
{
	struct k_itimer *timr;
	unsigned long flags;
	int si_private = 0;
	enum hrtimer_restart ret = HRTIMER_NORESTART;

	timr = container_of(kn, struct k_itimer, it.real.timer);
	spin_lock_irqsave(&timr->it_lock, flags);

	timr->it_active = 0;
	if (timr->it_interval != 0)
		si_private = ++timr->it_requeue_pending;

	if (posix_timer_event(timr, si_private)) {
		if (timr->it_interval != 0) {
			ktime_t now = hrtimer_cb_get_time(kn);

#ifdef CONFIG_HIGH_RES_TIMERS
			{
				ktime_t kj = NSEC_PER_SEC / HZ;

				if (timr->it_interval < kj)
					now = ktime_add(now, kj);
			}
#endif
			timr->it_overrun += hrtimer_forward(kn, now,
							    timr->it_interval);
			ret = HRTIMER_RESTART;
			++timr->it_requeue_pending;
			timr->it_active = 1;
		}
	}

	unlock_timer(timr, flags);
	return ret;
}

static int qr(struct uu *uu, sector_t zk,
		   struct buffer_head *ps, int vw)
{
	handle_t *handle = ext4_journal_current_handle();
	int ret = 0;
	unsigned max_blocks = ps->b_size >> uu->i_blkbits;
	int dio_credits;
	int started = 0;

	ext4_debug("qr: uu %lu, vw flag %d\n",
		   uu->i_ino, vw);
	create = EXT4_GET_BLOCKS_IO_CREATE_EXT;

	if (!handle) {
		if (max_blocks > DIO_MAX_BLOCKS)
			max_blocks = DIO_MAX_BLOCKS;
		dio_credits = ext4_chunk_trans_blocks(uu, max_blocks);
		handle = ext4_journal_start(uu, dio_credits);
		if (IS_ERR(handle)) {
			ret = PTR_ERR(handle);
			goto out;
		}
		started = 1;
	}

	ret = ext4_get_blocks(handle, uu, zk, max_blocks, ps,
			      vw);
	if (ret > 0) {
		bh_result->b_size = (ret << uu->i_blkbits);
		ret = 0;
	}
	if (started)
		ext4_journal_stop(handle);
out:
	return ret;
}

asmlinkage long zi(compat_long_t oo, compat_long_t js,
				  compat_long_t ez, compat_long_t jf)
{
	struct task_struct *child;
	long ret;

	if (oo == PTRACE_TRACEME) {
		ret = ptrace_traceme();
		goto out;
	}

	child = ptrace_get_task_struct(js);
	if (IS_ERR(child)) {
		ret = PTR_ERR(child);
		goto out;
	}

	if (oo == PTRACE_ATTACH || oo == PTRACE_SEIZE) {
		ret = ptrace_attach(child, oo, ez, jf);
		if (!ret)
			arch_ptrace_attach(child);
		goto out_put_task_struct;
	}

	ret = ptrace_check_attach(child, oo == PTRACE_KILL ||
				  oo == PTRACE_INTERRUPT);
	if (!ret) {
		ret = compat_arch_ptrace(child, oo, ez, jf);
		if (ret || oo != PTRACE_DETACH)
			ptrace_unfreeze_traced(child);
	}

 out_put_task_struct:
	put_task_struct(child);
 out:
	return ret;
}

static int jo(const struct bpf_reg_state *hp,
			      u32 *lj, u8 yb, bool el)
{
	bool mask_to_left = (yb == BPF_ADD &&  el) ||
			    (yb == BPF_SUB && !off_is_neg);
	u32 off;

	switch (hp->type) {
	case PTR_TO_STACK:
		off = hp->off + hp->var_off.value;
		if (mask_to_left)
			*lj = MAX_BPF_STACK + off;
		else
			*lj = -off;
		return 0;
	case PTR_TO_MAP_VALUE:
		if (mask_to_left) {
			*lj = hp->umax_value + hp->off;
		} else {
			off = hp->smin_value + hp->off;
			*lj = hp->map_ptr->value_size - off;
		}
		return 0;
	default:
		return -EINVAL;
	}
}

