static int ok(hashtable_t *sv,
                            const char *ez, size_t sx)
{
    pair_t *pair;
    bucket_t *bucket;
    size_t index;

    index = sx & hashmask(sv->order);
    bucket = &sv->buckets[index];

    pair = hashtable_find_pair(sv, bucket, ez, sx);
    if(!pair)
        return -1;

    if(&pair->list == bucket->first && &pair->list == bucket->last)
        bucket->first = bucket->last = &sv->list;

    else if(&pair->list == bucket->first)
        bucket->first = pair->list.next;

    else if(&pair->list == bucket->last)
        bucket->last = pair->list.prev;

    list_remove(&pair->list);
    json_decref(pair->value);

    jsonp_free(pair);
    sv->size--;

    return 0;
}

