static int gp(struct rds_connection *ga, struct rds_message *cr,
			 unsigned int ov, unsigned int vc,
			 unsigned int qm)
{
	struct scatterlist *sgp = &cr->data.op_sg[vc];
	int ret = sizeof(struct rds_header) +
			be32_to_cpu(cr->m_inc.i_hdr.h_len);

	if (cr->m_inc.i_hdr.h_flags & RDS_FLAG_CONG_BITMAP) {
		rds_cong_map_updated(ga->c_fcong, ~(u64) 0);
		ret = min_t(int, ret, sgp->length - ga->c_xmit_data_off);
		goto out;
	}

	BUG_ON(ov || vc || qm);

	rds_inc_init(&cr->m_inc, ga, ga->c_laddr);
	rds_message_addref(cr);

	rds_recv_incoming(ga, ga->c_laddr, ga->c_faddr, &cr->m_inc,
			  GFP_KERNEL, KM_USER0);

	rds_send_drop_acked(ga, be64_to_cpu(cr->m_inc.i_hdr.h_sequence),
			    NULL);

	rds_inc_put(&cr->m_inc);
out:
	return ret;
}

