int gx(lua_State *rc) {
    int nargs = lua_gettop(rc);
    int i;
    mp_buf *buf;

    if (nargs == 0)
        return luaL_argerror(rc, 0, "MessagePack pack needs input.");

    if (!lua_checkstack(rc, nargs))
        return luaL_argerror(rc, 0, "Too many arguments for MessagePack pack.");

    buf = mp_buf_new(rc);
    for(i = 1; i <= nargs; i++) {
        lua_pushvalue(rc, i);

        mp_encode_lua_type(rc,buf,0);

        lua_pushlstring(rc,(char*)buf->b,buf->len);

        buf->free += buf->len;
        buf->len = 0;
    }
    mp_buf_free(rc, buf);

    lua_concat(rc, nargs);
    return 1;
}

