    return IDN2_INVALID_FLAGS;

  if (((*oh) & (IDN2_TRANSITIONAL|IDN2_NONTRANSITIONAL)) && ((*oh) & IDN2_NO_TR46))
    return IDN2_INVALID_FLAGS;

  if (((*oh) & IDN2_ALABEL_ROUNDTRIP) && ((*oh) & IDN2_NO_ALABEL_ROUNDTRIP))
    return IDN2_INVALID_FLAGS;

  if (!((*oh) & (IDN2_NO_TR46|IDN2_TRANSITIONAL)))
    *oh |= IDN2_NONTRANSITIONAL;

  return IDN2_OK;
}

