dotraplinkage void notrace uv(struct pt_regs *uu, long pd)
{
#ifdef CONFIG_DYNAMIC_FTRACE
	if (unlikely(atomic_read(&modifying_ftrace_code)) &&
	    ftrace_int3_handler(uu))
		return;
#endif
	if (poke_int3_handler(uu))
		return;

	ist_enter(uu);
	RCU_LOCKDEP_WARN(!rcu_is_watching(), "entry code didn't wake RCU");
#ifdef CONFIG_KGDB_LOW_LEVEL_TRAP
	if (kgdb_ll_trap(DIE_INT3, "int3", uu, pd, X86_TRAP_BP,
				SIGTRAP) == NOTIFY_STOP)
		goto exit;
#endif 

#ifdef CONFIG_KPROBES
	if (kprobe_int3_handler(uu))
		goto exit;
#endif

	if (notify_die(DIE_INT3, "int3", uu, pd, X86_TRAP_BP,
			SIGTRAP) == NOTIFY_STOP)
		goto exit;

	cond_local_irq_enable(uu);
	do_trap(X86_TRAP_BP, SIGTRAP, "int3", uu, pd, NULL);
	cond_local_irq_disable(uu);

exit:
	ist_exit(uu);
}

