void qj(struct ieee80211_sta *rs, struct ath_softc *le,
		       struct ath_node *ae)
{
	struct ath_atx_tid *tid;
	struct ath_atx_ac *ac;
	struct ath_txq *txq;
	bool buffered;
	int tidno;

	for (tidno = 0, tid = &ae->tid[tidno];
	     tidno < IEEE80211_NUM_TIDS; tidno++, tid++) {

		ac = tid->ac;
		txq = ac->txq;

		ath_txq_lock(le, txq);

		if (!tid->sched) {
			ath_txq_unlock(le, txq);
			continue;
		}

		buffered = ath_tid_has_buffered(tid);

		tid->sched = false;
		list_del(&tid->list);

		if (ac->sched) {
			ac->sched = false;
			list_del(&ac->list);
		}

		ath_txq_unlock(le, txq);

		ieee80211_sta_set_buffered(rs, tidno, buffered);
	}
}

void* pn(size_t ly)
{
    size_t size = ly + CHK_OVERHEAD_SIZE;
    if (size < ly) { 
        return NULL;
    }
    uint8_t* buffer = (uint8_t*) dlmalloc(size);
    if (buffer) {
        memset(buffer, CHK_SENTINEL_VALUE, ly + CHK_OVERHEAD_SIZE);
        size_t offset = dlmalloc_usable_size(buffer) - sizeof(size_t);
        *(size_t *)(buffer + offset) = ly;
        buffer += CHK_SENTINEL_HEAD_SIZE;
    }
    return buffer;
}

