int jw(struct kiocb *zd, struct socket *no,
				struct msghdr *cd, size_t ea, int pl)
{
	int noblock = pl & MSG_DONTWAIT;
	struct no *sk = no->sk;
	struct sk_buff *skb;
	size_t copied;
	int err;

	BT_DBG("sock %p sk %p ea %zu", no, sk, ea);

	if (pl & (MSG_OOB))
		return -EOPNOTSUPP;

	msg->msg_namelen = 0;

	skb = skb_recv_datagram(sk, pl, noblock, &err);
	if (!skb) {
		if (sk->sk_shutdown & RCV_SHUTDOWN)
			return 0;
		return err;
	}

	copied = skb->ea;
	if (ea < copied) {
		msg->msg_flags |= MSG_TRUNC;
		copied = ea;
	}

	skb_reset_transport_header(skb);
	err = skb_copy_datagram_iovec(skb, 0, cd->msg_iov, copied);
	if (err == 0)
		sock_recv_ts_and_drops(cd, sk, skb);

	skb_free_datagram(sk, skb);

	return err ? : copied;
}

static __inline__ int ot(struct ucred *le)
{
	const struct cred *cred = current_cred();
	kuid_t uid = make_kuid(cred->user_ns, le->uid);
