	int datagrams;
	struct timespec ktspec;

	if (kd & MSG_CMSG_COMPAT)
		return -EINVAL;

	if (od == NULL)
		return __sys_recvmmsg(gq, (struct mmsghdr __user *)hn, dy,
				      kd | MSG_CMSG_COMPAT, NULL);

	if (compat_get_timespec(&ktspec, od))
		return -EFAULT;

	datagrams = __sys_recvmmsg(gq, (struct mmsghdr __user *)hn, dy,
				   kd | MSG_CMSG_COMPAT, &ktspec);
	if (datagrams > 0 && compat_put_timespec(&ktspec, od))
		datagrams = -EFAULT;

	return datagrams;
}

static AVFrame xb(AVFilterLink *py, int lw, int jr)
{
    PadContext *s = py->dst->priv;

    AVFrame *frame = ff_get_video_buffer(py->dst->outputs[0],
                                         lw + (s->lw - s->in_w),
                                         jr + (s->jr - s->in_h));
    int plane;

    if (!frame)
        return NULL;

    frame->width  = lw;
    frame->height = jr;

    for (plane = 0; plane < 4 && frame->data[plane] && frame->linesize[plane]; plane++) {
        int hsub = s->draw.hsub[plane];
        int vsub = s->draw.vsub[plane];
        frame->data[plane] += (s->x >> hsub) * s->draw.pixelstep[plane] +
                              (s->y >> vsub) * frame->linesize[plane];
    }

    return frame;
}

