static u64 ej(u64 bc, u64 pv, u64 af, u64 mt, u64 vk)
{
	struct sk_buff *skb = (struct sk_buff *)(long) bc;
	struct nlattr *nla;

	if (skb_is_nonlinear(skb))
		return 0;

	if (skb->len < sizeof(struct nlattr))
		return 0;

	if (pv > skb->len - sizeof(struct nlattr))
		return 0;

	nla = (struct nlattr *) &skb->data[pv];
	if (nla->nla_len > skb->len - pv)
		return 0;

	nla = nla_find_nested(nla, af);
	if (nla)
		return (void *) nla - (void *) skb->data;

	return 0;
}

