		io1 = container_of(after, ext4_io_end_t, list);

		ext4_debug("io 0x%p from zh %lu,prev 0x%p,next 0x%p\n",
			    io, zh->i_ino, io0, io1);
	}
	spin_unlock_irqrestore(&EXT4_I(zh)->i_completed_io_lock, flags);
#endif
}

