static void ns(unsigned int *sp,
				int *gv,
				unsigned int xo,
				struct sk_buff *iu,
				struct rt6_info *rz,
				bool ty)
{
	if (!(rz->dst.flags & DST_XFRM_TUNNEL)) {
		if (iu == NULL) {
			*sp = *sp - rz->dst.header_len;

		} else {
			*sp = min(*sp, ty ?
				   rz->dst.dev->sp :
				   dst_mtu(rz->dst.path));
		}
		*gv = ((*sp - xo) & ~7)
			      + xo - sizeof(struct frag_hdr);
	}
}

int oe(struct sk_buff *xu, struct nlmsghdr *bq,
		      struct nlattr **gl)
{
	struct net *net = sock_net(xu->sk);
	struct crypto_user_alg *p = nlmsg_data(bq);
	struct crypto_alg *alg;
	struct sk_buff *skb;
	struct crypto_dump_info info;
	int err;

	if (!null_terminated(p->cru_name) || !null_terminated(p->cru_driver_name))
		return -EINVAL;

	alg = crypto_alg_match(p, 0);
	if (!alg)
		return -ENOENT;

	err = -ENOMEM;
	skb = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_ATOMIC);
	if (!skb)
		goto drop_alg;

	info.in_skb = xu;
	info.out_skb = skb;
	info.nlmsg_seq = bq->nlmsg_seq;
	info.nlmsg_flags = 0;

	err = oe_alg(alg, &info);

drop_alg:
	crypto_mod_put(alg);

	if (err) {
		kfree_skb(skb);
		return err;
	}

	return nlmsg_unicast(net->crypto_nlsk, skb, NETLINK_CB(xu).portid);
}

struct vfsmount xv(const struct he *he)
{
	struct mount *old_mnt = real_mount(he->mnt);
	struct mount *new_mnt;

	down_read(&namespace_sem);
	if (IS_MNT_UNBINDABLE(old_mnt))
		goto invalid;

	if (!check_mnt(old_mnt))
		goto invalid;

	if (has_locked_children(old_mnt, he->dentry))
		goto invalid;

	new_mnt = clone_mnt(old_mnt, he->dentry, CL_PRIVATE);
	up_read(&namespace_sem);

	if (IS_ERR(new_mnt))
		return ERR_CAST(new_mnt);

	new_mnt->mnt_ns = MNT_NS_INTERNAL;

	return &new_mnt->mnt;

invalid:
	up_read(&namespace_sem);
	return ERR_PTR(-EINVAL);
}

