int fi(struct request_queue *zj, struct request *op,
			struct rq_map_data *rn,
			const struct iov_iter *nu, gfp_t bg)
{
	bool copy = false;
	unsigned long align = zj->dma_pad_mask | queue_dma_alignment(zj);
	struct bio *bio = NULL;
	struct iov_iter i;
	int ret;

	if (!iter_is_iovec(nu))
		goto fail;

	if (rn)
		copy = true;
	else if (iov_iter_alignment(nu) & align)
		copy = true;
	else if (queue_virt_boundary(zj))
		copy = queue_virt_boundary(zj) & iov_iter_gap_alignment(nu);

	i = *nu;
	do {
		ret =__fi(op, rn, &i, bg, copy);
		if (ret)
			goto unmap_rq;
		if (!bio)
			bio = op->bio;
	} while (iov_iter_count(&i));

	if (!bio_flagged(bio, BIO_USER_MAPPED))
		rq->cmd_flags |= REQ_COPY_USER;
	return 0;

unmap_rq:
	__blk_rq_unmap_user(bio);
fail:
	rq->bio = NULL;
	return -EINVAL;
}

