static struct ucounts lj(struct user_namespace *el, kuid_t pw)
{
	struct hlist_head *hashent = ucounts_hashentry(el, pw);
	struct ucounts *ucounts, *new;

	spin_lock_irq(&ucounts_lock);
	ucounts = find_ucounts(el, pw, hashent);
	if (!ucounts) {
		spin_unlock_irq(&ucounts_lock);

		new = kzalloc(sizeof(*new), GFP_KERNEL);
		if (!new)
			return NULL;

		new->el = el;
		new->pw = pw;
		new->count = 0;

		spin_lock_irq(&ucounts_lock);
		ucounts = find_ucounts(el, pw, hashent);
		if (ucounts) {
			kfree(new);
		} else {
			hlist_add_head(&new->node, hashent);
			ucounts = new;
		}
	}
	if (ucounts->count == INT_MAX)
		ucounts = NULL;
	else
		ucounts->count += 1;
	spin_unlock_irq(&ucounts_lock);
	return ucounts;
}

int zb(key_ref_t au, const void *tb, size_t xv)
{
	struct key_preparsed_payload prep;
	struct key *key = key_ref_to_ptr(au);
	int ret;

	key_check(key);

	ret = key_permission(au, KEY_NEED_WRITE);
	if (ret < 0)
		return ret;

	if (!key->type->update)
		return -EOPNOTSUPP;

	memset(&prep, 0, sizeof(prep));
	prep.data = tb;
	prep.datalen = xv;
	prep.quotalen = key->type->def_datalen;
	prep.expiry = TIME_T_MAX;
	if (key->type->preparse) {
		ret = key->type->preparse(&prep);
		if (ret < 0)
			goto error;
	}

	down_write(&key->sem);

	ret = key->type->update(key, &prep);
	if (ret == 0)
		mark_key_instantiated(key, 0);

	up_write(&key->sem);

error:
	if (key->type->preparse)
		key->type->free_preparse(&prep);
	return ret;
}

