	bool sigev_none;
	ktime_t expires;

	if (kw)
		common_timer_get(cy, kw);

	timr->it_interval = 0;
	if (kc->timer_try_to_cancel(cy) < 0)
		return TIMER_RETRY;

	timr->it_active = 0;
	timr->it_requeue_pending = (cy->it_requeue_pending + 2) &
		~REQUEUE_PENDING;
	timr->it_overrun_last = 0;

	if (!new_setting->it_value.tv_sec && !new_setting->it_value.tv_nsec)
		return 0;

	timr->it_interval = timespec64_to_ktime(xn->it_interval);
	expires = timespec64_to_ktime(xn->it_value);
	sigev_none = cy->it_sigev_notify == SIGEV_NONE;

	kc->timer_arm(cy, expires, pp & TIMER_ABSTIME, sigev_none);
	timr->it_active = !sigev_none;
	return 0;
}

