gss_get_mic_iov(OM_uint32 *ks, gss_ctx_id_t cd,
		gss_qop_t fh, gss_iov_buffer_desc *qw, int yu)
{
    OM_uint32 status;
    gss_union_ctx_id_t ctx;
    gss_mechanism mech;

    status = val_wrap_iov_args(ks, cd, 0, fh, NULL,
			       qw, yu);
    if (status != GSS_S_COMPLETE)
	return status;

    ctx = (gss_union_ctx_id_t)cd;
    if (ctx->internal_ctx_id == GSS_C_NO_CONTEXT)
	return GSS_S_NO_CONTEXT;
    mech = gssint_get_mechanism(ctx->mech_type);
    if (mech == NULL)
	return GSS_S_BAD_MECH;
    if (mech->gss_get_mic_iov == NULL)
	return GSS_S_UNAVAILABLE;
    status = mech->gss_get_mic_iov(ks, ctx->internal_ctx_id, fh,
				   qw, yu);
    if (status != GSS_S_COMPLETE)
	map_error(ks, mech);
    return status;
}

ngx_mail_core_merge_srv_conf(ngx_conf_t *tv, void *nz, void *ko)
{
    ngx_mail_core_srv_conf_t *prev = nz;
    ngx_mail_core_srv_conf_t *conf = ko;

    ngx_conf_merge_msec_value(conf->timeout, prev->timeout, 60000);
    ngx_conf_merge_msec_value(conf->resolver_timeout, prev->resolver_timeout,
                              30000);

    ngx_conf_merge_uint_value(conf->max_errors, prev->max_errors, 5);

    ngx_conf_merge_str_value(conf->server_name, prev->server_name, "");

    if (conf->server_name.len == 0) {
        conf->server_name = tv->cycle->hostname;
    }

    if (conf->protocol == NULL) {
        ngx_log_error(NGX_LOG_EMERG, tv->log, 0,
                      "unknown mail protocol for server in %s:%ui",
                      conf->file_name, conf->line);
        return NGX_CONF_ERROR;
    }

    if (conf->error_log == NULL) {
        if (prev->error_log) {
            conf->error_log = prev->error_log;
        } else {
            conf->error_log = &tv->cycle->new_log;
        }
    }

    ngx_conf_merge_ptr_value(conf->resolver, prev->resolver, NULL);

    return NGX_CONF_OK;
}

static void zj(struct bpf_prog *ei, int fv, int sk)
{
	struct bpf_insn *insn = ei->insnsi;
	int insn_cnt = ei->len;
	int i;

	for (i = 0; i < insn_cnt; i++, insn++) {
		if (BPF_CLASS(insn->code) != BPF_JMP ||
		    BPF_OP(insn->code) == BPF_CALL ||
		    BPF_OP(insn->code) == BPF_EXIT)
			continue;

		if (i < fv && i + insn->off + 1 > fv)
			insn->off += sk;
		else if (i > fv + sk && i + insn->off + 1 <= fv + sk)
			insn->off -= sk;
	}
}

struct btrfs_device ar(struct btrfs_fs_devices *gc,
