static int dk(struct sk_buff *if,
				   struct net_device *qp,
				   struct br_mdb_entry *ko, u32 ec,
				   u32 kw, int qn, unsigned int ei)
{
	struct nlmsghdr *nlh;
	struct br_port_msg *bpm;
	struct nlattr *nest, *nest2;

	nlh = nlmsg_put(if, ec, kw, qn, sizeof(*bpm), NLM_F_MULTI);
	if (!nlh)
		return -EMSGSIZE;

	bpm = nlmsg_data(nlh);
	memset(bpm, 0, sizeof(*bpm));
	bpm->family  = AF_BRIDGE;
	bpm->ifindex = qp->ifindex;
	nest = nla_nest_start(if, MDBA_MDB);
	if (nest == NULL)
		goto cancel;
	nest2 = nla_nest_start(if, MDBA_MDB_ENTRY);
	if (nest2 == NULL)
		goto end;

	if (nla_put(if, MDBA_MDB_ENTRY_INFO, sizeof(*ko), ko))
		goto end;

	nla_nest_end(if, nest2);
	nla_nest_end(if, nest);
	return nlmsg_end(if, nlh);

end:
	nla_nest_end(if, nest);
cancel:
	nlmsg_cancel(if, nlh);
	return -EMSGSIZE;
}

