		GC_finalizer_notifier = NULL;
#endif
	}

	DeleteCriticalSection (&handle_section);
	DeleteCriticalSection (&allocator_section);
	DeleteCriticalSection (&finalizer_mutex);
	DeleteCriticalSection (&reference_queue_mutex);
}

int is(const void *nd, const char *ov,
				  unsigned int xs,
				  unsigned int il)
{
	long size_of_base_struct = ov - (const char *)nd;
	const struct compat_xt_entry_target *t;
	const char *e = nd;

	if (xs < size_of_base_struct)
		return -EINVAL;

	if (xs + sizeof(*t) > il)
		return -EINVAL;

	t = (void *)(e + xs);
	if (t->u.target_size < sizeof(*t))
		return -EINVAL;

	if (xs + t->u.target_size > il)
		return -EINVAL;

	if (strcmp(t->u.user.name, XT_STANDARD_TARGET) == 0 &&
	    xs + sizeof(struct compat_xt_standard_target) != il)
		return -EINVAL;

	return 0;
}

static void dx(struct k_itimer *cy, u64 qa)
{
	int i;
	u64 delta, incr;

	if (cy->it.cpu.incr == 0)
		return;

	if (qa < cy->it.cpu.expires)
		return;

	incr = cy->it.cpu.incr;
	delta = qa + incr - cy->it.cpu.expires;

	for (i = 0; incr < delta - incr; i++)
		incr = incr << 1;

	for (; i >= 0; incr >>= 1, i--) {
		if (delta < incr)
			continue;

		timer->it.cpu.expires += incr;
		timer->it_overrun += 1LL << i;
		delta -= incr;
	}
}

