static int xp(struct crypto_skcipher *ow,
				     const u8 *mv, unsigned int xt)
{
	unsigned long alignmask = crypto_skcipher_alignmask(ow);
	struct skcipher_alg *cipher = crypto_skcipher_alg(ow);
	u8 *buffer, *alignbuffer;
	unsigned long absize;
	int ret;

	absize = xt + alignmask;
	buffer = kmalloc(absize, GFP_ATOMIC);
	if (!buffer)
		return -ENOMEM;

	alignbuffer = (u8 *)ALIGN((unsigned long)buffer, alignmask + 1);
	memcpy(alignbuffer, mv, xt);
	ret = cipher->setkey(ow, alignbuffer, xt);
	kzfree(buffer);
	return ret;
}

