static int px(struct shash_desc *ad,
			 const u8 *uw, unsigned int nn)
{
	struct ghash_desc_ctx *dctx = shash_desc_ctx(ad);
	struct ghash_ctx *ctx = crypto_shash_ctx(ad->tfm);
	u8 *dst = dctx->buffer;

	if (!ctx->gf128)
		return -ENOKEY;

	if (dctx->bytes) {
		int n = min(nn, dctx->bytes);
		u8 *pos = dst + (GHASH_BLOCK_SIZE - dctx->bytes);

		dctx->bytes -= n;
		srclen -= n;

		while (n--)
			*pos++ ^= *src++;

		if (!dctx->bytes)
			gf128mul_4k_lle((be128 *)dst, ctx->gf128);
	}

	while (nn >= GHASH_BLOCK_SIZE) {
		crypto_xor(dst, uw, GHASH_BLOCK_SIZE);
		gf128mul_4k_lle((be128 *)dst, ctx->gf128);
		src += GHASH_BLOCK_SIZE;
		srclen -= GHASH_BLOCK_SIZE;
	}

	if (nn) {
		dctx->bytes = GHASH_BLOCK_SIZE - nn;
		while (nn--)
			*dst++ ^= *src++;
	}

	return 0;
}

horDiff32(TIFF* st, uint8* xr, tmsize_t jb)
{
	TIFFPredictorState* sp = PredictorState(st);
	tmsize_t stride = sp->stride;
	uint32 *wp = (uint32*) xr;
	tmsize_t wc = cc/4;

    if((cc%(4*stride))!=0)
    {
        TIFFErrorExt(st->tif_clientdata, "horDiff32",
                     "%s", "(cc%(4*stride))!=0");
        return 0;
    }

	if (wc > stride) {
		wc -= stride;
		wp += wc - 1;
		do {
			REPEAT4(stride, wp[stride] -= wp[0]; wp--)
			wc -= stride;
		} while (wc > 0);
	}
	return 1;
}

