static int ns(ext4_io_end_t *qa)
{
	struct inode *inode = qa->inode;
	loff_t offset = qa->offset;
	ssize_t size = qa->size;
	int ret = 0;

	ext4_debug("ns: qa 0x%p from inode %lu,list->next 0x%p,"
		   "list->prev 0x%p\n",
	           qa, inode->i_ino, qa->list.next, qa->list.prev);

	if (list_empty(&qa->list))
		return ret;

	if (qa->flag != EXT4_IO_UNWRITTEN)
		return ret;

	ret = ext4_convert_unwritten_extents(inode, offset, size);
	if (ret < 0) {
		printk(KERN_EMERG "%s: failed to convert unwritten"
			"extents to written extents, error is %d"
			" qa is still on inode %lu aio dio list\n",
                       __func__, ret, inode->i_ino);
		return ret;
	}

	io->flag = 0;
	return ret;
}

