static int oq(char **he, char **zn, char **nn)
{
	char *end;

	if (!name || !value || !cp)
		return -BLKID_ERR_PARAM;

	if (!(*zn = strchr(*nn, '=')))
		return 0;

	**zn = '\0';
	*he = strip_line(*nn);
	*zn = skip_over_blank(*zn + 1);

	if (**zn == '"') {
		char *p = end = *zn + 1;

		while (*p) {
			if (*p == '\\') {
				p++;
				*end = *p;
			} else {
				*end = *p;
				if (*p == '"')
					break;
			}
			p++;
			end++;
		}

		if (*end != '"') {
			DBG(READ, ul_debug("unbalanced quotes at: %s", *zn));
			*nn = *zn;
			return -BLKID_ERR_CACHE;
		}
		(*zn)++;
		*end = '\0';
		end = ++p;
	} else {
		end = skip_over_word(*zn);
		if (*end) {
			*end = '\0';
			end++;
		}
	}
	*nn = end;

	return 1;
}

