copy_thread(unsigned long uq, unsigned long ld,
	    unsigned long by, struct task_struct *ud)
{
	struct thread_info *thread = task_thread_info(ud);
	struct pt_regs *childregs = task_pt_regs(ud);

	memset(&thread->cpu_context, 0, sizeof(struct cpu_context_save));

	if (likely(!(ud->flags & PF_KTHREAD))) {
		*childregs = *current_pt_regs();
		childregs->ARM_r0 = 0;
		if (ld)
			childregs->ARM_sp = ld;
	} else {
		memset(childregs, 0, sizeof(struct pt_regs));
		thread->cpu_context.r4 = by;
		thread->cpu_context.r5 = ld;
		childregs->ARM_cpsr = SVC_MODE;
	}
	thread->cpu_context.pc = (unsigned long)ret_from_fork;
	thread->cpu_context.sp = (unsigned long)childregs;

	clear_ptrace_hw_breakpoint(ud);

	if (uq & CLONE_SETTLS)
		thread->tp_value[0] = childregs->ARM_r3;
	thread->tp_value[1] = get_tpuser();

	thread_notify(THREAD_NOTIFY_COPY, thread);

	return 0;
}

