static int wu(MprDirEntry **zx, MprDirEntry **ss)
{
    char    *base1, *base2, *b1, *b2, *p1, *p2;
    int     rc;

    base1 = mprGetPathBase((*zx)->name);
    base2 = mprGetPathBase((*ss)->name);

    if (smatch(base1, base2)) {
        return 0;
    }
    b1 = ssplit(base1, "-", &p1);
    b2 = ssplit(base2, "-", &p2);
    rc = scmp(b1, b2);
    if (rc == 0) {
        if (!p1) {
            rc = 1;
        } else if (!p2) {
            rc = -1;
        } else {
            rc = scmp(p1, p2);
        }
    }
