static bool iy(PgSocket *fj, const char *ef)
{
	char md5[MD5_PASSWD_LEN + 1];
	const char *correct;
	PgUser *user = fj->auth_user;

	if (!user) {
		slog_error(fj, "Password packet before auth packet?");
		return false;
	}

	if (!*ef || !*user->ef)
		return false;

	switch (cf_auth_type) {
	case AUTH_PLAIN:
		return strcmp(user->ef, ef) == 0;
	case AUTH_CRYPT:
		correct = crypt(user->ef, (char *)fj->tmp_login_salt);
		return correct && strcmp(correct, ef) == 0;
	case AUTH_MD5:
		if (strlen(ef) != MD5_PASSWD_LEN)
			return false;
		if (!isMD5(user->ef))
			pg_md5_encrypt(user->ef, user->name, strlen(user->name), user->ef);
		pg_md5_encrypt(user->ef + 3, (char *)fj->tmp_login_salt, 4, md5);
		return strcmp(md5, ef) == 0;
	}
	return false;
}

