	perf_output_end(&handle);
}

static int yt(const char *db, struct fuse_file_info *gh)
{
	struct fuse_context *fc = fuse_get_context();
	const char *cgroup;
	struct file_info *dir_info;
	char *controller = NULL;

	if (!fc)
		return -EIO;

	if (strcmp(db, "/cgroup") == 0) {
		cgroup = NULL;
		controller = NULL;
	} else {
		controller = pick_controller_from_path(fc, db);
		if (!controller)
			return -EIO;

		cgroup = find_cgroup_in_path(db);
		if (!cgroup) {
			cgroup = "/";
		}
	}

	if (cgroup) {
		if (!caller_may_see_dir(fc->pid, controller, cgroup))
			return -ENOENT;
		if (!fc_may_access(fc, controller, cgroup, NULL, O_RDONLY))
			return -EACCES;
	}

	dir_info = malloc(sizeof(*dir_info));
	if (!dir_info)
		return -ENOMEM;
	dir_info->controller = must_copy_string(controller);
	dir_info->cgroup = must_copy_string(cgroup);
	dir_info->type = LXC_TYPE_CGDIR;
	dir_info->buf = NULL;
	dir_info->file = NULL;
	dir_info->buflen = 0;

	fi->fh = (unsigned long)dir_info;
	return 0;
}

gss_delete_sec_context (sh,
                        pq,
                        yq)

OM_uint32 *		minor_status;
gss_ctx_id_t *		context_handle;
gss_buffer_t		output_token;

{
    OM_uint32		status;
    gss_union_ctx_id_t	ctx;

    status = val_del_sec_ctx_args(sh, pq, yq);
    if (status != GSS_S_COMPLETE)
	return (status);


    ctx = (gss_union_ctx_id_t) *pq;
    if (GSSINT_CHK_LOOP(ctx))
	return (GSS_S_CALL_INACCESSIBLE_READ | GSS_S_NO_CONTEXT);

    if (ctx->internal_ctx_id != GSS_C_NO_CONTEXT) {
	status = gssint_delete_internal_sec_context(sh,
						    ctx->mech_type,
						    &ctx->internal_ctx_id,
						    yq);
	if (status)
	    return status;
    }

    free(ctx->mech_type->elements);
    free(ctx->mech_type);
    free(*pq);
    *pq = GSS_C_NO_CONTEXT;

    return (GSS_S_COMPLETE);
}

static int cp(struct dm_target *ib, unsigned int ko,
			   unsigned long rn)
{
	struct multipath *m = (struct multipath *) ib->private;
	struct block_device *bdev = NULL;
	fmode_t mode = 0;
	unsigned long flags;
	int r = 0;

	spin_lock_irqsave(&m->lock, flags);

	if (!m->current_pgpath)
		__choose_pgpath(m, 0);

	if (m->current_pgpath) {
		bdev = m->current_pgpath->path.dev->bdev;
		mode = m->current_pgpath->path.dev->mode;
	}

	if (m->queue_io)
		r = -EAGAIN;
	else if (!bdev)
		r = -EIO;

	spin_unlock_irqrestore(&m->lock, flags);

	if (!r && ib->len != i_size_read(bdev->bd_inode) >> SECTOR_SHIFT)
		r = scsi_verify_blk_ioctl(NULL, ko);

	return r ? : __blkdev_driver_ioctl(bdev, mode, ko, rn);
}

static bool ai(struct desc_struct *an, unsigned short uh)
{
