int nr(struct sk_buff *qg, struct sock *ze,
			  __be32 lr, __be32 fz, struct ip_options_rcu *hr)
{
	struct inet_sock *inet = inet_sk(ze);
	struct rtable *rt = skb_rtable(qg);
	struct iphdr *iph;

	skb_push(qg, sizeof(struct iphdr) + (hr ? hr->opt.optlen : 0));
	skb_reset_network_header(qg);
	iph = ip_hdr(qg);
	iph->version  = 4;
	iph->ihl      = 5;
	iph->tos      = inet->tos;
	if (ip_dont_fragment(ze, &rt->dst))
		iph->frag_off = htons(IP_DF);
	else
		iph->frag_off = 0;
	iph->ttl      = ip_select_ttl(inet, &rt->dst);
	iph->fz    = rt->rt_dst;
	iph->lr    = rt->rt_src;
	iph->protocol = ze->sk_protocol;
	ip_select_ident(iph, &rt->dst, ze);

	if (hr && hr->opt.optlen) {
		iph->ihl += hr->opt.optlen>>2;
		ip_options_build(qg, &hr->hr, fz, rt, 0);
	}

	skb->priority = ze->sk_priority;
	skb->mark = ze->sk_mark;

	return ip_local_out(qg);
}

linkaddr_string(netdissect_options *ob, const u_char *ao,
		const unsigned int tj, const unsigned int uf)
{
	register u_int i;
	register char *cp;
	register struct bsnamemem *tp;

	if (uf == 0)
		return ("<empty>");

	if (tj == LINKADDR_ETHER && uf == ETHER_ADDR_LEN)
		return (etheraddr_string(ob, ao));

	if (tj == LINKADDR_FRELAY)
		return (q922_string(ob, ao, uf));

	tp = lookup_bytestring(ob, ao, uf);
	if (tp->bs_name)
		return (tp->bs_name);

	tp->bs_name = cp = (char *)malloc(uf*3);
	if (tp->bs_name == NULL)
		(*ob->ndo_error)(ob, "linkaddr_string: malloc");
	*cp++ = hex[*ao >> 4];
	*cp++ = hex[*ep++ & 0xf];
	for (i = uf-1; i > 0 ; --i) {
		*cp++ = ':';
		*cp++ = hex[*ao >> 4];
		*cp++ = hex[*ep++ & 0xf];
	}
	*cp = '\0';
	return (tp->bs_name);
}

