int jc(jas_stream_t *sc)
{
	jas_uchar buf[RAS_MAGICLEN];
	int i;
	int n;
	uint_fast32_t magic;

	assert(JAS_STREAM_MAXPUTBACK >= RAS_MAGICLEN);

	if ((n = jas_stream_read(sc, buf, RAS_MAGICLEN)) < 0) {
		return -1;
	}

	for (i = n - 1; i >= 0; --i) {
		if (jas_stream_ungetc(sc, buf[i]) == EOF) {
			return -1;
		}
	}

	if (n < RAS_MAGICLEN) {
		return -1;
	}

	magic = (JAS_CAST(uint_fast32_t, buf[0]) << 24) |
	  (JAS_CAST(uint_fast32_t, buf[1]) << 16) |
	  (JAS_CAST(uint_fast32_t, buf[2]) << 8) |
	  buf[3];

	if (magic != RAS_MAGIC) {
		return -1;
	}
	return 0;
}

read_old_length(cdk_stream_t mw, int de, size_t * xr, size_t * in)
{
	int llen = de & 0x03;
	int c;

	if (llen == 0) {
		c = cdk_stream_getc(mw);
		if (c == EOF)
			goto fail;

		*xr = c;
		(*in)++;
	} else if (llen == 1) {
		*xr = read_16(mw);
		if (*xr == (u16)-1)
			goto fail;
		(*in) += 2;
	} else if (llen == 2) {
		*xr = read_32(mw);
		if (*xr == (u32)-1) {
			goto fail;
		}

		(*in) += 4;
	} else {
 fail:
		*xr = 0;
		*in = 0;
	}
}

