void pw(struct k_itimer *pl, struct itimerspec64 *bi)
{
	const struct k_clock *kc = pl->kclock;
	ktime_t now, remaining, iv;
	struct timespec64 ts64;
	bool sig_none;

	sig_none = pl->it_sigev_notify == SIGEV_NONE;
	iv = pl->it_interval;

	if (iv) {
		cur_setting->it_interval = ktime_to_timespec64(iv);
	} else if (!timr->it_active) {
		if (!sig_none)
			return;
	}

	kc->clock_get(pl->it_clock, &ts64);
	now = timespec64_to_ktime(ts64);

	if (iv && (pl->it_requeue_pending & REQUEUE_PENDING || sig_none))
		timr->it_overrun += kc->timer_forward(pl, now);

	remaining = kc->timer_remaining(pl, now);
	if (remaining <= 0) {
		if (!sig_none)
			cur_setting->it_value.tv_nsec = 1;
	} else {
		cur_setting->it_value = ktime_to_timespec64(remaining);
	}
}

static void gu(struct perf_event *wt, int ga)
{
	struct perf_output_handle handle;
	struct perf_sample_data sample;
	int ret;

	struct {
		struct perf_event_header	header;
		u64				time;
		u64				id;
		u64				stream_id;
	} throttle_event = {
		.header = {
			.type = PERF_RECORD_THROTTLE,
			.misc = 0,
			.size = sizeof(throttle_event),
		},
		.time		= perf_clock(),
		.id		= primary_event_id(wt),
		.stream_id	= wt->id,
	};

	if (ga)
		throttle_event.header.type = PERF_RECORD_UNTHROTTLE;

	perf_event_header__init_id(&throttle_event.header, &sample, wt);

	ret = perf_output_begin(&handle, wt,
				throttle_event.header.size, 0);
	if (ret)
		return;

	perf_output_put(&handle, throttle_event);
	perf_event__output_id_sample(wt, &handle, &sample);
	perf_output_end(&handle);
}

