                                        const char *lq,
                                        char **yb, size_t *xh)
{
  CURLcode result;
  char *plainauth;
  size_t ulen;
  size_t plen;
  size_t plainlen;

  *xh = 0;
  *yb = NULL;
  ulen = strlen(op);
  plen = strlen(lq);

  if((ulen > SIZE_T_MAX/4) || (plen > (SIZE_T_MAX/2 - 2)))
    return CURLE_OUT_OF_MEMORY;
  plainlen = 2 * ulen + plen + 2;

  plainauth = malloc(plainlen);
  if(!plainauth)
    return CURLE_OUT_OF_MEMORY;

  memcpy(plainauth, op, ulen);
  plainauth[ulen] = '\0';
  memcpy(plainauth + ulen + 1, op, ulen);
  plainauth[2 * ulen + 1] = '\0';
  memcpy(plainauth + 2 * ulen + 2, lq, plen);

  result = Curl_base64_encode(vq, plainauth, plainlen, yb, xh);
  free(plainauth);

  return result;
}

