	if (gk->header.indx + za > gk->header.end)
	{	count = psf_fread (gk->header.ptr + gk->header.end, 1, za - (gk->header.end - gk->header.indx), gk) ;
		if (count != za - (int) (gk->header.end - gk->header.indx))
