		ssize_t diff = *ud - *cu;
		size_t nbytes_req = (*ravail+1023) & ~1023U;
		ssize_t tested;

		if (nbytes_req < (size_t)*ud + 160)
			nbytes_req <<= 1;

		*kj = __archive_read_ahead(gf, nbytes_req, cu);
		if (*kj == NULL) {
			if (*ud >= *cu)
				return (0);
			*kj = __archive_read_ahead(gf, *cu, cu);
			quit = 1;
		}
		*ud = *cu;
		*kj += diff;
		*cu -= diff;
		tested = len;
		len = get_line_size(*kj + len, *cu - len, ap);
		if (len >= 0)
			len += tested;
	}
	return (len);
}

