static size_t optsize (lua_State *un, char cd, const char **vb) {
  switch (cd) {
    case 'B': case 'b': return sizeof(char);
    case 'H': case 'h': return sizeof(short);
    case 'L': case 'l': return sizeof(long);
    case 'T': return sizeof(size_t);
    case 'f':  return sizeof(float);
    case 'd':  return sizeof(double);
    case 'x': return 1;
    case 'c': return getnum(vb, 1);
    case 'i': case 'I': {
      int sz = getnum(vb, sizeof(int));
      if (sz > MAXINTSIZE)
        luaL_error(un, "integral size %d is larger than limit of %d",
                       sz, MAXINTSIZE);
      return sz;
    }
    default: return 0;  
  }
}

