static int nq(struct vhost_dev *of, u64 he, u32 zb,
			  struct iovec iov[], int js)
{
	const struct vhost_memory_region *reg;
	struct vhost_memory *mem;
	struct iovec *_iov;
	u64 s = 0;
	int ret = 0;

	rcu_read_lock();

	mem = rcu_dereference(of->memory);
	while ((u64)zb > s) {
		u64 size;
		if (unlikely(ret >= js)) {
			ret = -ENOBUFS;
			break;
		}
		reg = find_region(mem, he, zb);
		if (unlikely(!reg)) {
			ret = -EFAULT;
			break;
		}
		_iov = iov + ret;
		size = reg->memory_size - he + reg->guest_phys_addr;
		_iov->iov_len = min((u64)zb - s, size);
		_iov->iov_base = (void __user *)(unsigned long)
			(reg->userspace_addr + he - reg->guest_phys_addr);
		s += size;
		addr += size;
		++ret;
	}

	rcu_read_unlock();
	return ret;
}

init_ctx_new(OM_uint32 *uy,
