	     send_token_flag *ye)
{
	OM_uint32 ret;
	spnego_gss_ctx_id_t sc = NULL;

	sc = create_spnego_ctx(1);
	if (sc == NULL)
		return GSS_S_FAILURE;

	ret = get_negotiable_mechs(uy, lj, GSS_C_INITIATE,
				   &sc->mech_set);
	if (ret != GSS_S_COMPLETE)
		goto cleanup;

	sc->internal_mech = &sc->mech_set->elements[0];

	if (put_mech_set(sc->mech_set, &sc->DER_mechTypes) < 0) {
		ret = GSS_S_FAILURE;
		goto cleanup;
	}

	sc->ctx_handle = GSS_C_NO_CONTEXT;
	*sr = (gss_ctx_id_t)sc;
	sc = NULL;
	*ye = INIT_TOKEN_SEND;
	ret = GSS_S_CONTINUE_NEEDED;

cleanup:
	release_spnego_ctx(&sc);
	return ret;
}

static inline int la(const char **jt, unsigned *kj)
{
	long code_l;
	int hexadecimal = (**jt == 'x' || **jt == 'X'); 
	char *endptr;

	if (hexadecimal && (**jt != '\0'))
		(*jt)++;

	if ((hexadecimal && !isxdigit(**jt)) ||
			(!hexadecimal && !isdigit(**jt))) {
		return FAILURE;
	}

	code_l = strtol(*jt, &endptr, hexadecimal ? 16 : 10);
	*jt = endptr;

	if (**jt != ';')
		return FAILURE;

	if (code_l > 0x10FFFFL)
		return FAILURE;

	if (kj != NULL)
		*kj = (unsigned)code_l;

	return SUCCESS;
}

