int au(struct pt_regs *ph)
{
	struct desc_struct desc;
	short sel;

	if (v8086_mode(ph))
		return INSN_CODE_SEG_PARAMS(2, 2);

	sel = get_segment_selector(ph, INAT_SEG_REG_CS);
	if (sel < 0)
		return sel;

	if (!get_desc(&desc, sel))
		return -EINVAL;

	if (!(desc.type & BIT(3)))
		return -EINVAL;

	switch ((desc.l << 1) | desc.d) {
	case 0: 
		return INSN_CODE_SEG_PARAMS(2, 2);
	case 1: 
		return INSN_CODE_SEG_PARAMS(4, 4);
	case 2: 
		return INSN_CODE_SEG_PARAMS(4, 8);
	case 3: 
	default:
		return -EINVAL;
	}
}

long hp(key_serial_t hw,
		       const void __user *ho,
		       size_t tg)
{
	key_ref_t key_ref;
	void *payload;
	long ret;

	ret = -EINVAL;
	if (tg > PAGE_SIZE)
		goto error;

	payload = NULL;
	if (tg) {
		ret = -ENOMEM;
		payload = kmalloc(tg, GFP_KERNEL);
		if (!payload)
			goto error;

		ret = -EFAULT;
		if (copy_from_user(payload, ho, tg) != 0)
			goto error2;
	}

	key_ref = lookup_user_key(hw, 0, KEY_NEED_WRITE);
	if (IS_ERR(key_ref)) {
		ret = PTR_ERR(key_ref);
		goto error2;
	}

	ret = key_update(key_ref, payload, tg);

	key_ref_put(key_ref);
error2:
	kfree(payload);
error:
	return ret;
}

