static int ts(unsigned long tn, unsigned long uh,
			      struct mm_walk *by)
{
	struct vm_area_struct *vma = by->vma;
	struct hstate *h = hstate_vma(vma);
	unsigned long next;
	unsigned long hmask = huge_page_mask(h);
	unsigned long sz = huge_page_size(h);
	pte_t *pte;
	int err = 0;

	do {
		next = hugetlb_entry_end(h, tn, uh);
		pte = huge_pte_offset(by->mm, tn & hmask, sz);

		if (pte)
			err = by->hugetlb_entry(pte, hmask, tn, next, by);
		else if (by->pte_hole)
