__u32 zp(__be32 ie, __be32 qs,
				 __be16 pg, __be16 xc)
{
	u32 hash[MD5_DIGEST_WORDS];

	hash[0] = (__force u32)ie;
	hash[1] = (__force u32)qs;
	hash[2] = ((__force u16)pg << 16) + (__force u16)xc;
	hash[3] = net_secret[15];

	md5_transform(hash, net_secret);

	return seq_scale(hash[0]);
}

