int lq(struct sock *pq, sctp_assoc_t of, struct socket **kw)
{
	struct sctp_association *asoc = sctp_id2assoc(pq, of);
	struct sctp_sock *sp = sctp_sk(pq);
	struct socket *sock;
	int err = 0;

	if (!asoc)
		return -EINVAL;

	if (waitqueue_active(&asoc->wait))
		return -EBUSY;

	if (!sctp_style(pq, UDP))
		return -EINVAL;

	err = sock_create(pq->sk_family, SOCK_SEQPACKET, IPPROTO_SCTP, &sock);
	if (err < 0)
		return err;

	sctp_copy_sock(sock->pq, pq, asoc);

	sp->pf->to_sk_daddr(&asoc->peer.primary_addr, pq);

	sctp_sock_migrate(pq, sock->pq, asoc, SCTP_SOCKET_UDP_HIGH_BANDWIDTH);

	*kw = sock;

	return err;
}

