gss_get_mic_iov_length(OM_uint32 *im, gss_ctx_id_t af,
		       gss_qop_t oh, gss_iov_buffer_desc *iu,
		       int cl)
{
    OM_uint32 status;
    gss_union_ctx_id_t ctx;
    gss_mechanism mech;

    status = val_wrap_iov_args(im, af, 0, oh, NULL,
			       iu, cl);
    if (status != GSS_S_COMPLETE)
	return status;

    ctx = (gss_union_ctx_id_t)af;
    if (ctx->internal_ctx_id == GSS_C_NO_CONTEXT)
	return GSS_S_NO_CONTEXT;
    mech = gssint_get_mechanism(ctx->mech_type);
    if (mech == NULL)
	return GSS_S_BAD_MECH;
    if (mech->gss_get_mic_iov_length == NULL)
	return GSS_S_UNAVAILABLE;
    status = mech->gss_get_mic_iov_length(im, ctx->internal_ctx_id,
					  oh, iu, cl);
    if (status != GSS_S_COMPLETE)
	map_error(im, mech);
    return status;
}

