asmlinkage void cl(struct pt_regs *dd)
{
	unsigned int __user *pc;
	mm_segment_t seg;

	perf_sw_event(PERF_COUNT_SW_ALIGNMENT_FAULTS,
			1, dd, dd->cp0_badvaddr);
	if ((dd->cp0_badvaddr == dd->cp0_epc) || (dd->cp0_epc & 0x1))
		goto sigbus;

	pc = (unsigned int __user *) exception_epc(dd);
	if (user_mode(dd) && !test_thread_flag(TIF_FIXADE))
		goto sigbus;
	if (unaligned_action == UNALIGNED_ACTION_SIGNAL)
		goto sigbus;
	else if (unaligned_action == UNALIGNED_ACTION_SHOW)
		show_registers(dd);

	seg = get_fs();
	if (!user_mode(dd))
		set_fs(KERNEL_DS);
	emulate_load_store_insn(dd, (void __user *)dd->cp0_badvaddr, pc);
	set_fs(seg);

	return;

sigbus:
	die_if_kernel("Kernel unaligned instruction access", dd);
	force_sig(SIGBUS, current);

}

