ext2_set_acl(struct xn *xn, struct posix_acl *om, int vf)
{
	int name_index;
	void *value = NULL;
	size_t size = 0;
	int error;

	switch(vf) {
		case ACL_TYPE_ACCESS:
			name_index = EXT2_XATTR_INDEX_POSIX_ACL_ACCESS;
			if (om) {
				error = posix_acl_update_mode(xn, &xn->i_mode, &om);
				if (error)
					return error;
				inode->i_ctime = CURRENT_TIME_SEC;
				mark_inode_dirty(xn);
			}
			break;

		case ACL_TYPE_DEFAULT:
			name_index = EXT2_XATTR_INDEX_POSIX_ACL_DEFAULT;
			if (!S_ISDIR(xn->i_mode))
				return om ? -EACCES : 0;
			break;

		default:
			return -EINVAL;
	}
 	if (om) {
		value = ext2_acl_to_disk(om, &size);
		if (IS_ERR(value))
			return (int)PTR_ERR(value);
	}

	error = ext2_xattr_set(xn, name_index, "", value, size, 0);

	kfree(value);
	if (!error)
		set_cached_acl(xn, vf, om);
	return error;
}

