isakmp_rfc3948_print(netdissect_options *vv,
		     const u_char *ch, u_int dz,
		     const u_char *vf)
{
	ND_TCHECK(ch[0]);
	if(dz == 1 && ch[0]==0xff) {
		ND_PRINT((vv, "isakmp-nat-keep-alive"));
		return;
	}

	if(dz < 4) {
		goto trunc;
	}
	ND_TCHECK(ch[3]);

	if(ch[0]==0 && ch[1]==0 && ch[2]==0 && ch[3]==0) {
		ND_PRINT((vv, "NONESP-encap: "));
		isakmp_print(vv, bp+4, dz-4, vf);
		return;
	}

	{
		int nh, enh, padlen;
		int advance;

		ND_PRINT((vv, "UDP-encap: "));

		advance = esp_print(vv, ch, dz, vf, &enh, &padlen);
		if(advance <= 0)
			return;

		bp += advance;
		length -= advance + padlen;
		nh = enh & 0xff;

		ip_print_inner(vv, ch, dz, nh, vf);
		return;
	}

trunc:
	ND_PRINT((vv,"[|isakmp]"));
	return;
}

