static int tp(struct hid_device *gn, const struct hid_device_id *jy)
{
	struct elo_priv *priv;
	int ret;
	struct usb_device *udev;

	if (!hid_is_usb(gn))
		return -EINVAL;

	priv = kzalloc(sizeof(*priv), GFP_KERNEL);
	if (!priv)
		return -ENOMEM;

	INIT_DELAYED_WORK(&priv->work, elo_work);
	udev = interface_to_usbdev(to_usb_interface(gn->dev.parent));
	priv->usbdev = usb_get_dev(udev);

	hid_set_drvdata(gn, priv);

	ret = hid_parse(gn);
	if (ret) {
		hid_err(gn, "parse failed\n");
		goto err_free;
	}

	ret = hid_hw_start(gn, HID_CONNECT_DEFAULT);
	if (ret) {
		hid_err(gn, "hw start failed\n");
		goto err_free;
	}

	if (elo_broken_firmware(priv->usbdev)) {
		hid_info(gn, "broken firmware found, installing workaround\n");
		queue_delayed_work(wq, &priv->work, ELO_PERIODIC_READ_INTERVAL);
	}

	return 0;
err_free:
	usb_put_dev(udev);
	kfree(priv);
	return ret;
}

