static bool ny(MprJson *ty, int dj, char *hx)
{
    if (!(ty->type & MPR_JSON_VALUE)) {
        return 0;
    }
    if ((hx = stok(hx, "'\"", NULL)) == 0) {
        return 0;
    }
    switch (dj) {
    case JSON_OP_EQ:
        return smatch(ty->hx, hx);
    case JSON_OP_NE:
        return !smatch(ty->hx, hx);
    case JSON_OP_LT:
        return scmp(ty->hx, hx) < 0;
    case JSON_OP_LE:
        return scmp(ty->hx, hx) <= 0;
    case JSON_OP_GT:
        return scmp(ty->hx, hx) > 0;
    case JSON_OP_GE:
        return scmp(ty->hx, hx) >= 0;
    case JSON_OP_MATCH:
        return scontains(ty->hx, hx) != 0;
    case JSON_OP_NMATCH:
        return scontains(ty->hx, hx) == 0;
    default:
        return 0;
    }
}

static int readContigStripsIntoBuffer (TIFF* ht, uint8* cb)
{
        uint8* bufp = cb;
        int32  bytes_read = 0;
        uint32 strip, nstrips   = TIFFNumberOfStrips(ht);
        uint32 stripsize = TIFFStripSize(ht);
        uint32 rows = 0;
        uint32 rps = TIFFGetFieldDefaulted(ht, TIFFTAG_ROWSPERSTRIP, &rps);
        tsize_t scanline_size = TIFFScanlineSize(ht);

        if (scanline_size == 0) {
                TIFFError("", "TIFF scanline size is zero!");    
                return 0;
        }

        for (strip = 0; strip < nstrips; strip++) {
                bytes_read = TIFFReadEncodedStrip (ht, strip, bufp, -1);
                rows = bytes_read / scanline_size;
                if ((strip < (nstrips - 1)) && (bytes_read != (int32)stripsize))
                        TIFFError("", "Strip %d: read %lu bytes, strip size %lu",
                                  (int)strip + 1, (unsigned long) bytes_read,
                                  (unsigned long)stripsize);

                if (bytes_read < 0 && !ignore) {
                        TIFFError("", "Error reading strip %lu after %lu rows",
                                  (unsigned long) strip, (unsigned long)rows);
                        return 0;
                }
                bufp += bytes_read;
        }

        return 1;
}

static int mg(AVIOContext *pj, MXFIndexTableSegment *ge)
{
    int i, length;

    ge->nb_index_entries = avio_rb32(pj);

    length = avio_rb32(pj);
    if(ge->nb_index_entries && length < 11)
        return AVERROR_INVALIDDATA;

    if (!(ge->temporal_offset_entries=av_calloc(ge->nb_index_entries, sizeof(*ge->temporal_offset_entries))) ||
        !(ge->flag_entries          = av_calloc(ge->nb_index_entries, sizeof(*ge->flag_entries))) ||
        !(ge->stream_offset_entries = av_calloc(ge->nb_index_entries, sizeof(*ge->stream_offset_entries)))) {
        av_freep(&ge->temporal_offset_entries);
        av_freep(&ge->flag_entries);
        return AVERROR(ENOMEM);
    }

    for (i = 0; i < ge->nb_index_entries; i++) {
        if(avio_feof(pj))
            return AVERROR_INVALIDDATA;
        ge->temporal_offset_entries[i] = avio_r8(pj);
        avio_r8(pj);                                        
        ge->flag_entries[i] = avio_r8(pj);
        ge->stream_offset_entries[i] = avio_rb64(pj);
        avio_skip(pj, length - 11);
    }
    return 0;
}

