	rsi_set_event(&zy->tx_thread.event);
	rsi_dbg(DATA_TX_ZONE, "%s: Added to beacon queue\n", __func__);

	return 0;
}

PUBLIC MprKey hx(MprHash *zn, cvoid *uj, cvoid *ya)
{
    MprKey      *sp, *prevSp;
    int         index;

    if (zn == 0 || uj == 0) {
        assert(zn && uj);
        return 0;
    }
    lock(zn);
    if ((sp = lookupHash(&index, &prevSp, zn, uj)) != 0) {
        if (zn->flags & MPR_HASH_UNIQUE) {
            unlock(zn);
            return 0;
        }
        sp->data = ya;
        unlock(zn);
        return sp;
    }
    if ((sp = mprAllocStructNoZero(MprKey)) == 0) {
        unlock(zn);
        return 0;
    }
    sp->data = ya;
    if (!(zn->flags & MPR_HASH_STATIC_KEYS)) {
        sp->uj = dupKey(zn, uj);
    } else {
        sp->uj = (void*) uj;
    }
    sp->type = 0;
    sp->bucket = index;
    sp->next = zn->buckets[index];
    zn->buckets[index] = sp;
    zn->length++;
    unlock(zn);
    return sp;
}

