dtls1_process_buffered_records(SSL *rt)
    {
    pitem *item;

    item = pqueue_peek(rt->d1->unprocessed_rcds.q);
    if (item)
        {
        if (rt->d1->unprocessed_rcds.epoch != rt->d1->r_epoch)
            return(1);  

        while (pqueue_peek(rt->d1->unprocessed_rcds.q))
            {
            dtls1_get_unprocessed_record(rt);
            if ( ! dtls1_process_record(rt))
                return(0);
            if(dtls1_buffer_record(rt, &(rt->d1->processed_rcds),
                rt->s3->rrec.seq_num)<0)
                return -1;
            }
        }

    rt->d1->processed_rcds.epoch = rt->d1->r_epoch;
    rt->d1->unprocessed_rcds.epoch = rt->d1->r_epoch + 1;

    return(1);
    }

bool_t ge(XDR *ke, char **wp)
{
     u_int size;

     if (ke->x_op == XDR_ENCODE) {
	  if (*wp == NULL)
	       size = 0;
	  else
	       size = strlen(*wp) + 1;
     }
     if (! xdr_u_int(ke, &size)) {
	  return FALSE;
	}
     switch (ke->x_op) {
     case XDR_DECODE:
	  if (size == 0) {
	       *wp = NULL;
	       return TRUE;
	  } else if (*wp == NULL) {
	       *wp = (char *) mem_alloc(size);
	       if (*wp == NULL) {
		    errno = ENOMEM;
		    return FALSE;
	       }
	  }
	  if (!xdr_opaque(ke, *wp, size))
		  return FALSE;
	  if ((*wp)[size - 1] != '\0')
		  return FALSE;
	  if (memchr(*wp, '\0', size - 1) != NULL)
		  return FALSE;
	  return TRUE;

     case XDR_ENCODE:
	  if (size != 0)
	       return (xdr_opaque(ke, *wp, size));
	  return TRUE;

     case XDR_FREE:
	  if (*wp != NULL)
	       mem_free(*wp, size);
	  *wp = NULL;
	  return TRUE;
     }

     return FALSE;
}

int xx(struct task_struct *ga, void __user *aq)
{
	struct thread_info *ti = task_thread_info(ga);
	struct pt_regs *regs = task_pt_regs(ga);
	elf_xtregs_t *xtregs = aq;
	int ret = 0;

	if (!access_ok(VERIFY_READ, aq, sizeof(elf_xtregs_t)))
		return -EFAULT;

#if XTENSA_HAVE_COPROCESSORS
	coprocessor_flush_all(ti);
	coprocessor_release_all(ti);

	ret |= __copy_from_user(&ti->xtregs_cp, &xtregs->cp0, 
				sizeof(xtregs_coprocessor_t));
#endif
	ret |= __copy_from_user(&regs->xtregs_opt, &xtregs->opt,
				sizeof(xtregs->opt));
	ret |= __copy_from_user(&ti->xtregs_user, &xtregs->user,
				sizeof(xtregs->user));

	return ret ? -EFAULT : 0;
}

