void hl(const char *kk) {
	assert(kk);
	if (arg_debug || arg_debug_private_lib)
		printf("    hl %s\n", kk);

	if (access(kk, R_OK)) {
		if (arg_debug || arg_debug_private_lib)
			printf("cannot find %s for private-lib, skipping...\n", kk);
		return;
	}

	unlink(RUN_LIB_FILE);			  
	create_empty_file_as_root(RUN_LIB_FILE, 0644);
	if (chown(RUN_LIB_FILE, getuid(), getgid()))
		errExit("chown");

	if (arg_debug || arg_debug_private_lib)
		printf("    running fldd %s\n", kk);
	sbox_run(SBOX_USER | SBOX_SECCOMP | SBOX_CAPS_NONE, 3, PATH_FLDD, kk, RUN_LIB_FILE);

	FILE *fp = fopen(RUN_LIB_FILE, "r");
	if (!fp)
		errExit("fopen");

	char buf[MAXBUF];
	while (fgets(buf, MAXBUF, fp)) {
		char *ptr = strchr(buf, '\n');
		if (ptr)
			*ptr = '\0';
		fslib_duplicate(buf);
	}
	fclose(fp);
	unlink(RUN_LIB_FILE);
}

