static __u8 cl(struct hid_device *tp, __u8 *mx,
		unsigned int *tz)
{
	unsigned long quirks = (unsigned long)hid_get_drvdata(tp);
	unsigned int i;

	if (!(quirks & CP_RDESC_SWAPPED_MIN_MAX))
		return mx;

	if (*tz < 4)
		return mx;

	for (i = 0; i < *tz - 4; i++)
		if (mx[i] == 0x29 && mx[i + 2] == 0x19) {
			rdesc[i] = 0x19;
			rdesc[i + 2] = 0x29;
