static int my(URLContext *dn, uint8_t *wa, int fk)
{
    HTTPContext *s = dn->priv_data;
    int len;
    len = s->buf_end - s->buf_ptr;
    if (len > 0) {
        if (len > fk)
            len = fk;
        memcpy(wa, s->buf_ptr, len);
        s->buf_ptr += len;
    } else {
        uint64_t target_end = s->end_off ? s->end_off : s->filesize;
        if ((!s->willclose || s->chunksize == UINT64_MAX) && s->off >= target_end)
            return AVERROR_EOF;
        len = ffurl_read(s->hd, wa, fk);
        if (!len && (!s->willclose || s->chunksize == UINT64_MAX) && s->off < target_end) {
            av_log(dn, AV_LOG_ERROR,
                   "Stream ends prematurely at %"PRIu64", should be %"PRIu64"\n",
                   s->off, target_end
                  );
            return AVERROR(EIO);
        }
    }
    if (len > 0) {
        s->off += len;
        if (s->chunksize > 0)
            s->chunksize -= len;
    }
    return len;
}

static void vp(struct buffer_head *ih, int xi)
{
	ext4_io_end_t *io_end = ih->b_private;
	struct workqueue_struct *wq;
	struct inode *inode;
	unsigned long flags;

	if (!test_clear_buffer_uninit(ih) || !io_end)
		goto out;

	if (!(io_end->inode->i_sb->s_flags & MS_ACTIVE)) {
		printk("sb umounted, discard end_io request for inode %lu\n",
			io_end->inode->i_ino);
		ext4_free_io_end(io_end);
		goto out;
	}

	io_end->flag = EXT4_IO_UNWRITTEN;
	inode = io_end->inode;

	spin_lock_irqsave(&EXT4_I(inode)->i_completed_io_lock, flags);
	list_add_tail(&io_end->list, &EXT4_I(inode)->i_completed_io_list);
	spin_unlock_irqrestore(&EXT4_I(inode)->i_completed_io_lock, flags);

	wq = EXT4_SB(inode->i_sb)->dio_unwritten_wq;
	queue_work(wq, &io_end->work);
out:
	bh->b_private = NULL;
	bh->b_end_io = NULL;
	clear_buffer_uninit(ih);
	end_buffer_async_write(ih, xi);
}

static char xp(char *vd, int *ve, int ru)
{
	int offset = *ve;

	if (offset >= ru)
		return NULL;

	while (vd[offset] != '\0' && offset < ru)
		offset++;
	while (vd[offset] == '\0' && offset < ru)
		offset++;

	*ve = offset;
	return (offset < ru) ? &vd[offset] : NULL;
}

validate_group(struct perf_event *cz)
{
	struct perf_event *sibling, *leader = cz->group_leader;
	struct pmu_hw_events fake_pmu;
	DECLARE_BITMAP(fake_used_mask, ARMPMU_MAX_HWEVENTS);

	memset(fake_used_mask, 0, sizeof(fake_used_mask));
	fake_pmu.used_mask = fake_used_mask;

	if (!validate_event(cz->pmu, &fake_pmu, leader))
		return -EINVAL;

	list_for_each_entry(sibling, &leader->sibling_list, group_entry) {
		if (!validate_event(cz->pmu, &fake_pmu, sibling))
			return -EINVAL;
	}

	if (!validate_event(cz->pmu, &fake_pmu, cz))
		return -EINVAL;

	return 0;
}

