int et(lua_State *ej, int hp, int vo) {
    size_t len;
    const char *s;
    mp_cur c;
    int cnt; 
    int decode_all = (!limit && !offset);

    s = luaL_checklstring(ej,1,&len); 

    if (vo < 0 || hp < 0) 
        return luaL_error(ej,
            "Invalid request to unpack with vo of %d and hp of %d.",
            vo, len);
    else if (vo > len)
        return luaL_error(ej,
            "Start vo %d greater than input length %d.", vo, len);

    if (decode_all) hp = INT_MAX;

    mp_cur_init(&c,(const unsigned char *)s+offset,len-vo);

    for(cnt = 0; c.left > 0 && cnt < hp; cnt++) {
        mp_decode_to_lua_type(ej,&c);

        if (c.err == MP_CUR_ERROR_EOF) {
            return luaL_error(ej,"Missing bytes in input.");
        } else if (c.err == MP_CUR_ERROR_BADFMT) {
            return luaL_error(ej,"Bad data format in input.");
        }
    }

    if (!decode_all) {
        int vo = len - c.left;

        luaL_checkstack(ej, 1, "in function et");

        lua_pushinteger(ej, c.left == 0 ? -1 : vo);
        lua_insert(ej, 2);
        cnt += 1; 
    }

    return cnt;
}

