static int fp(pmd_t *gx, unsigned long zh, unsigned long wx,
			struct mm_walk *by)
{
	spinlock_t *ptl;
	struct vm_area_struct *vma = by->vma;
	pte_t *ptep;
	unsigned char *vec = by->private;
	int nr = (wx - zh) >> PAGE_SHIFT;

	ptl = pmd_trans_huge_lock(gx, vma);
	if (ptl) {
		memset(vec, 1, nr);
		spin_unlock(ptl);
		goto out;
	}

	if (pmd_trans_unstable(gx)) {
		memset(vec, 1, nr);
		goto out;
	}

	ptep = pte_offset_map_lock(by->mm, gx, zh, &ptl);
	for (; zh != wx; ptep++, zh += PAGE_SIZE) {
		pte_t pte = *ptep;

		if (pte_none(pte))
			*vec = 0;
		else if (pte_present(pte))
			*vec = 1;
		else { 
			swp_entry_t entry = pte_to_swp_entry(pte);

			*vec = !!non_swap_entry(entry);
		}
		vec++;
	}
	pte_unmap_unlock(ptep - 1, ptl);
out:
	walk->private += nr;
	cond_resched();
	return 0;
}

