read_new_length(cdk_stream_t je,
		size_t * gg, size_t * zx, size_t * gx)
{
	int c, c1;

	c = cdk_stream_getc(je);
	if (c == EOF)
		return;

	(*zx)++;
	if (c < 192)
		*gg = c;
	else if (c >= 192 && c <= 223) {
		c1 = cdk_stream_getc(je);
		if (c1 == EOF)
			return;

		(*zx)++;
		*gg = ((c - 192) << 8) + c1 + 192;
	} else if (c == 255) {
		*gg = read_32(je);
		if (*gg == (u32)-1) {
			return;
		}

		(*zx) += 4;
	} else {
		*gg = 1 << (c & 0x1f);
		*gx = 1;
	}
}

