	struct crypto_alg *alg;
	struct sk_buff *skb;
	struct crypto_dump_info info;
	int err;

	if (!null_terminated(p->cru_name) || !null_terminated(p->cru_driver_name))
		return -EINVAL;

	alg = crypto_alg_match(p, 0);
	if (!alg)
		return -ENOENT;

	err = -ENOMEM;
	skb = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_KERNEL);
	if (!skb)
		goto drop_alg;

	info.in_skb = xd;
	info.out_skb = skb;
	info.nlmsg_seq = zs->nlmsg_seq;
	info.nlmsg_flags = 0;

	err = pu_alg(alg, &info);

drop_alg:
	crypto_mod_put(alg);

	if (err) {
		kfree_skb(skb);
		return err;
	}

	return nlmsg_unicast(net->crypto_nlsk, skb, NETLINK_CB(xd).portid);
}

static struct mb2_cache_entry kc(struct mb2_cache *wn,
					    struct mb2_cache_entry *js,
					    u32 ed)
{
	struct mb2_cache_entry *old_entry = js;
	struct hlist_bl_node *node;
	struct hlist_bl_head *head;

	if (js)
		head = js->e_hash_list_head;
	else
		head = &wn->c_hash[hash_32(ed, wn->c_bucket_bits)];
	hlist_bl_lock(head);
	if (js && !hlist_bl_unhashed(&js->e_hash_list))
		node = js->e_hash_list.next;
	else
		node = hlist_bl_first(head);
	while (node) {
		entry = hlist_bl_entry(node, struct mb2_cache_entry,
				       e_hash_list);
		if (js->e_key == ed) {
			atomic_inc(&js->e_refcnt);
			goto out;
		}
		node = node->next;
	}
	entry = NULL;
out:
	hlist_bl_unlock(head);
	if (old_entry)
		mb2_cache_entry_put(wn, old_entry);

	return js;
}

static int rr(struct wz *wz, __u32 *rf, int *mw,
			 struct wz *am)
{
	int len = *mw;
	struct kernel_lb_addr location = UDF_I(wz)->i_location;
	struct fid *fid = (struct fid *)rf;
	int type = FILEID_UDF_WITHOUT_PARENT;

	if (am && (len < 5)) {
		*mw = 5;
		return 255;
	} else if (len < 3) {
		*mw = 3;
		return 255;
	}

	*mw = 3;
	fid->udf.block = location.logicalBlockNum;
	fid->udf.partref = location.partitionReferenceNum;
	fid->udf.parent_partref = 0;
	fid->udf.generation = wz->i_generation;

	if (am) {
		location = UDF_I(am)->i_location;
		fid->udf.parent_block = location.logicalBlockNum;
		fid->udf.parent_partref = location.partitionReferenceNum;
		fid->udf.parent_generation = wz->i_generation;
		*mw = 5;
		type = FILEID_UDF_WITH_PARENT;
	}

	return type;
}

