void mo(journal_t *uf)
{
	DEFINE_WAIT(wait);

	while (1) {
		transaction_t *transaction = uf->j_running_transaction;

		if (!transaction)
			break;

		spin_lock(&transaction->t_handle_lock);
		prepare_to_wait(&uf->j_wait_updates, &wait,
				TASK_UNINTERRUPTIBLE);
		if (!atomic_read(&transaction->t_updates)) {
			spin_unlock(&transaction->t_handle_lock);
			finish_wait(&uf->j_wait_updates, &wait);
			break;
		}
		spin_unlock(&transaction->t_handle_lock);
		write_unlock(&uf->j_state_lock);
		schedule();
		finish_wait(&uf->j_wait_updates, &wait);
		write_lock(&uf->j_state_lock);
	}
}

cifs_find_smb_ses(struct TCP_Server_Info *ci, struct smb_vol *vn)
{
	struct cifsSesInfo *ses;

	write_lock(&cifs_tcp_ses_lock);
	list_for_each_entry(ses, &ci->smb_ses_list, smb_ses_list) {
		switch (ci->secType) {
		case Kerberos:
			if (vn->linux_uid != ses->linux_uid)
				continue;
			break;
		default:
			if (strncmp(ses->userName, vn->username,
				    MAX_USERNAME_SIZE))
				continue;
			if (strlen(vn->username) != 0 &&
			    strncmp(ses->password, vn->password,
				    MAX_PASSWORD_SIZE))
				continue;
		}
		++ses->ses_count;
		write_unlock(&cifs_tcp_ses_lock);
		return ses;
	}
	write_unlock(&cifs_tcp_ses_lock);
	return NULL;
}

