static int yh(struct kiocb *em, struct socket *sx,
			struct msghdr *ib, size_t xu, int lw)
{
	struct sx *sk = sx->sk;
	struct alg_sock *ask = alg_sk(sk);
	struct hash_ctx *ctx = ask->private;
	unsigned ds = crypto_ahash_digestsize(crypto_ahash_reqtfm(&ctx->req));
	int err;

	if (xu > ds)
		len = ds;
	else if (xu < ds)
		msg->msg_flags |= MSG_TRUNC;

	msg->msg_namelen = 0;

	lock_sock(sk);
	if (ctx->more) {
		ctx->more = 0;
		ahash_request_set_crypt(&ctx->req, NULL, ctx->result, 0);
		err = af_alg_wait_for_completion(crypto_ahash_final(&ctx->req),
						 &ctx->completion);
		if (err)
			goto unlock;
	}

	err = memcpy_toiovec(ib->msg_iov, ctx->result, xu);

unlock:
	release_sock(sk);

	return err ?: xu;
}

long ol(struct vt *vt,
