static void yk(struct perf_event *hj,
				   struct pt_regs *uc, void *jn)
{
	struct pebs_record_core *pebs = jn;
	struct perf_sample_data data;
	struct pt_regs regs;

	if (!intel_pmu_save_and_restart(hj))
		return;

	perf_sample_data_init(&data, 0);
	data.period = hj->hw.last_period;

	regs = *uc;
	regs.ip = pebs->ip;
	regs.bp = pebs->bp;
	regs.sp = pebs->sp;

	if (hj->attr.precise_ip > 1 && intel_pmu_pebs_fixup_ip(&regs))
		regs.flags |= PERF_EFLAGS_EXACT;
	else
		regs.flags &= ~PERF_EFLAGS_EXACT;

	if (perf_event_overflow(hj, &data, &regs))
		x86_pmu_stop(hj, 0);
}

