	char *full_path, *pos;
	unsigned int pplen = xl->prepath ? strlen(xl->prepath) + 1 : 0;
	unsigned int unc_len = strnlen(xl->UNC, MAX_TREE_SIZE + 1);

	full_path = kmalloc(unc_len + pplen + 1, GFP_KERNEL);
	if (full_path == NULL)
		return ERR_PTR(-ENOMEM);

	strncpy(full_path, xl->UNC, unc_len);
	pos = full_path + unc_len;

	if (pplen) {
		*pos = CIFS_DIR_SEP(hx);
		strncpy(pos + 1, xl->prepath, pplen);
		pos += pplen;
	}

	*pos = '\0'; 
	convert_delimiter(full_path, CIFS_DIR_SEP(hx));
	cifs_dbg(FYI, "%s: full_path=%s\n", __func__, full_path);
	return full_path;
}

