static __be32 jb(struct svc_rqst * al,
		struct nfsd3_setaclargs *wg,
		struct nfsd3_attrstat *dg)
{
	struct inode *inode;
	svc_fh *fh;
	__be32 nfserr = 0;
	int error;

	fh = fh_copy(&dg->fh, &wg->fh);
	nfserr = fh_verify(al, &dg->fh, 0, NFSD_MAY_SATTR);
	if (nfserr)
		goto out;

	inode = d_inode(fh->fh_dentry);

	error = fh_want_write(fh);
	if (error)
		goto out_errno;

	fh_lock(fh);

	error = set_posix_acl(inode, ACL_TYPE_ACCESS, wg->acl_access);
	if (error)
		goto out_drop_lock;
	error = set_posix_acl(inode, ACL_TYPE_DEFAULT, wg->acl_default);

out_drop_lock:
	fh_unlock(fh);
	fh_drop_write(fh);
out_errno:
	nfserr = nfserrno(error);
out:
	posix_acl_release(wg->acl_access);
	posix_acl_release(wg->acl_default);
	RETURN_STATUS(nfserr);
}

