struct dst_entry ek(struct sock *pz,
				     const struct request_sock *vw)
{
	struct rtable *rt;
	const struct inet_request_sock *ireq = inet_rsk(vw);
	struct ip_options_rcu *opt = inet_rsk(vw)->opt;
	struct net *net = sock_net(pz);
	struct flowi4 fl4;

	flowi4_init_output(&fl4, pz->sk_bound_dev_if, pz->sk_mark,
			   RT_CONN_FLAGS(pz), RT_SCOPE_UNIVERSE,
			   pz->sk_protocol, inet_sk_flowi_flags(pz),
			   (opt && opt->opt.srr) ? opt->opt.faddr : ireq->rmt_addr,
			   ireq->loc_addr, ireq->rmt_port, inet_sk(pz)->inet_sport);
	security_req_classify_flow(vw, flowi4_to_flowi(&fl4));
	rt = ip_route_output_flow(net, &fl4, pz);
	if (IS_ERR(rt))
		goto no_route;
	if (opt && opt->opt.is_strictroute && rt->rt_dst != rt->rt_gateway)
		goto route_err;
	return &rt->dst;

route_err:
	ip_rt_put(rt);
no_route:
	IP_INC_STATS_BH(net, IPSTATS_MIB_OUTNOROUTES);
	return NULL;
}

