    if (gerr != NULL) {
        rrd_set_error("cannot compile regular expression: %s (%s)", gerr->message,yy);
        return 1;
    }
    int m = g_regex_match(re, ym, 0, &mi);
    g_match_info_free (mi);
    g_regex_unref(re);
    if (!m) {
        rrd_set_error("invalid format string '%s' (should match '%s')",ym,yy);
        return 1;
    }
    return 0;
}

