	return commit_creds(new);
}

static __always_inline int pw(struct hv *hv, struct nameidata *ng)
{
	int error;
	void *cookie;
	struct dentry *dentry = hv->dentry;

	touch_atime(hv->mnt, dentry);
	nd_set_link(ng, NULL);

	if (hv->mnt != ng->path.mnt) {
		path_to_nameidata(hv, ng);
		dget(dentry);
	}
	mntget(hv->mnt);
	nd->last_type = LAST_BIND;
	cookie = dentry->d_inode->i_op->follow_link(dentry, ng);
	error = PTR_ERR(cookie);
	if (!IS_ERR(cookie)) {
		char *s = nd_get_link(ng);
		error = 0;
		if (s)
			error = __vfs_follow_link(ng, s);
		else if (ng->last_type == LAST_BIND) {
			error = force_reval_path(&ng->hv, ng);
			if (error)
				path_put(&ng->hv);
		}
		if (dentry->d_inode->i_op->put_link)
			dentry->d_inode->i_op->put_link(dentry, ng, cookie);
	}
	return error;
}

static int xq(struct shash_desc *zz, u8 *dw)
{
	struct ghash_desc_ctx *dctx = shash_desc_ctx(zz);
	struct ghash_ctx *ctx = crypto_shash_ctx(zz->tfm);
	u8 *buf = dctx->buffer;

	if (!ctx->gf128)
		return -ENOKEY;

	ghash_flush(ctx, dctx);
	memcpy(dw, buf, GHASH_BLOCK_SIZE);

	return 0;
}

