psf_fwrite (const void *uu, sf_count_t eh, sf_count_t de, SF_PRIVATE *mb)
{	sf_count_t total = 0 ;
	ssize_t	count ;

	if (eh == 0 || de == 0)
		return 0 ;

	if (mb->virtual_io)
		return mb->vio.write (uu, eh*de, mb->vio_user_data) / eh ;

	items *= eh ;

	if (de <= 0)
		return 0 ;

	while (de > 0)
	{	
		count = (de > SENSIBLE_SIZE) ? SENSIBLE_SIZE : de ;

		count = write (mb->file.filedes, ((const char*) uu) + total, count) ;

		if (count == -1)
		{	if (errno == EINTR)
				continue ;

			psf_log_syserr (mb, errno) ;
			break ;
			} ;

		if (count == 0)
			break ;

		total += count ;
		items -= count ;
		} ;

	if (mb->is_pipe)
		psf->pipeoffset += total ;

	return total / eh ;
}

static VTermScreen at(VTerm *en)
{
  VTermState *state = vterm_obtain_state(en);
  VTermScreen *screen;
  int rows, cols;

  if (state == NULL)
    return NULL;
  screen = vterm_allocator_malloc(en, sizeof(VTermScreen));
  if (screen == NULL)
    return NULL;

  vterm_get_size(en, &rows, &cols);

  screen->en = en;
  screen->state = state;

  screen->damage_merge = VTERM_DAMAGE_CELL;
  screen->damaged.start_row = -1;
  screen->pending_scrollrect.start_row = -1;

  screen->rows = rows;
  screen->cols = cols;

  screen->callbacks = NULL;
  screen->cbdata    = NULL;

  screen->buffers[0] = realloc_buffer(screen, NULL, rows, cols);
  screen->buffer = screen->buffers[0];
  screen->sb_buffer = vterm_allocator_malloc(screen->en, sizeof(VTermScreenCell) * cols);
  if (screen->buffer == NULL || screen->sb_buffer == NULL)
  {
    vterm_screen_free(screen);
    return NULL;
  }

  vterm_state_set_callbacks(screen->state, &state_cbs, screen);

  return screen;
}

static ssize_t nq(struct kiocb *gc,
				       struct iov_iter *bm)
{
	struct file *filp = gc->ki_filp;
	struct rpmsg_eptdev *eptdev = filp->private_data;
	size_t len = iov_iter_count(bm);
	void *kbuf;
	int ret;

	kbuf = kzalloc(len, GFP_KERNEL);
	if (!kbuf)
		return -ENOMEM;

	if (!copy_from_iter_full(kbuf, len, bm)) {
		ret = -EFAULT;
		goto free_kbuf;
	}

	if (mutex_lock_interruptible(&eptdev->ept_lock)) {
		ret = -ERESTARTSYS;
		goto free_kbuf;
	}

	if (!eptdev->ept) {
		ret = -EPIPE;
		goto unlock_eptdev;
	}

	if (filp->f_flags & O_NONBLOCK)
		ret = rpmsg_trysend(eptdev->ept, kbuf, len);
	else
		ret = rpmsg_send(eptdev->ept, kbuf, len);

unlock_eptdev:
	mutex_unlock(&eptdev->ept_lock);

free_kbuf:
	kfree(kbuf);
	return ret < 0 ? ret : len;
}

static int uh(struct platform_device *jw)
{
	struct device *dev = &jw->dev;
	struct resource *res;
	unsigned int i;
	int ret;

	stub_clk_chan.cl.dev = dev;
	stub_clk_chan.cl.tx_done = NULL;
	stub_clk_chan.cl.tx_block = false;
	stub_clk_chan.cl.knows_txdone = false;

	stub_clk_chan.mbox = mbox_request_channel(&stub_clk_chan.cl, 0);
	if (IS_ERR(stub_clk_chan.mbox))
		return PTR_ERR(stub_clk_chan.mbox);

	res = platform_get_resource(jw, IORESOURCE_MEM, 0);
	if (!res)
		return -EINVAL;
	freq_reg = devm_ioremap(dev, res->start, resource_size(res));
	if (!freq_reg)
		return -ENOMEM;

	freq_reg += HI3660_STUB_CLOCK_DATA;

	for (i = 0; i < HI3660_CLK_STUB_NUM; i++) {
		ret = devm_clk_hw_register(&jw->dev, &hi3660_stub_clks[i].hw);
		if (ret)
			return ret;
	}

	return devm_of_clk_add_hw_provider(&jw->dev, hi3660_stub_clk_hw_get,
					   hi3660_stub_clks);
}

void np(struct sock *hk)
{
	struct inet_sock *isk = inet_sk(hk);

	pr_debug("np(isk=%p,isk->num=%u)\n", isk, isk->inet_num);
	write_lock_bh(&ping_table.lock);
	if (sk_hashed(hk)) {
		hlist_nulls_del(&hk->sk_nulls_node);
		sk_nulls_node_init(&hk->sk_nulls_node);
		sock_put(hk);
		isk->inet_num = 0;
		isk->inet_sport = 0;
		sock_prot_inuse_add(sock_net(hk), hk->sk_prot, -1);
	}
	write_unlock_bh(&ping_table.lock);
}

static pfn_t di(struct kvm_memory_slot *bq, gfn_t nu,
			   unsigned long bj)
{
	gfn_t end_gfn;
	pfn_t pfn;

	pfn     = gfn_to_pfn_memslot(bq, nu);
	end_gfn = nu + bj;
	gfn    += 1;

	if (is_error_noslot_pfn(pfn))
		return pfn;

	while (nu < end_gfn)
		gfn_to_pfn_memslot(bq, gfn++);

	return pfn;
}

